@dataclass
class TraySession:
    master_label_code: str = ""
    item_code: str = ""
    item_name: str = ""
    item_spec: str = ""
    scanned_barcodes: List[str] = field(default_factory=list)
    scan_times: List[datetime.datetime] = field(default_factory=list)
    preflight_scan_receipts: Dict[str, str] = field(default_factory=dict)
    tray_size: int = 60
    mismatch_error_count: int = 0
    total_idle_seconds: float = 0.0
    stopwatch_seconds: float = 0.0
    start_time: Optional[datetime.datetime] = None
    has_error_or_reset: bool = False
    is_test_tray: bool = False
    is_partial_submission: bool = False
    is_restored_session: bool = False
    canonical_input_tag_qr: str = ""
    active_label_qr_payload: str = ""
    active_label_id: str = ""
    active_label_business_date: str = ""
    active_label_worker_code: str = ""
    operation_lease_id: str = ""
    known_member_barcodes: List[str] = field(default_factory=list)
    exchange_idempotency_keys: List[str] = field(default_factory=list)
    scan_completion_context: Dict[str, Any] = field(default_factory=dict)
    # Transition mode: why this tray completes on this PC only (e.g. its preflight failure).
    transition_reasons: List[str] = field(default_factory=list)
    # Transition mode: the class this round got with the switch on. It keeps the
    # round on that path through a retry, a restart or the switch turned off.
    transition_class: str = ""
    # First attempt (timestamp, event file, detail) of an undo/reset whose write may
    # have landed: its retry, even after a restart on a later day, is the same row.
    cancel_event_attempts: Dict[str, Dict[str, Any]] = field(default_factory=dict)
    pending_audit_events: List[Dict[str, Any]] = field(default_factory=list)
    worker_id: Optional[str] = None
    worker_name_snapshot: str = ""


class _LocalValueVar:
    """Small test/headless stand-in for Tk variables."""

    def __init__(self, value: Any = None):
        self._value = value

    def get(self):
        return self._value

    def set(self, value: Any):
        self._value = value


def resource_path(relative_path: str) -> str:
    try:
        base_path = sys._MEIPASS
    except AttributeError:
        base_path = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base_path, relative_path)


def _recovery_item_firewall(action):
    """Keep an unexpected manager recovery error on its original item."""
    @wraps(action)
    def guarded(self, *args, **kwargs):
        try:
            return action(self, *args, **kwargs)
        except Exception as exc:
            print(f"관리자 복구 동작 보류: {action.__name__}: {exc.__class__.__name__}")
            try:
                messagebox.showerror(
                    "원본 보류 유지",
                    "이 항목을 확인하지 못했습니다. 원본을 유지하고 다시 확인하세요.",
                    parent=getattr(self, "root", None),
                )
            except Exception:
                pass
            return False
    return guarded


