    def on_ctrl_wheel(self, event):
        self.scale_factor += 0.1 if event.delta > 0 else -0.1
        self.scale_factor = max(0.7, min(2.5, self.scale_factor))
        self.apply_scaling()
        if self.worker_name:
            self.show_validation_screen()
        else:
            self.show_worker_input_screen()

    def _clear_main_frames(self):
        self._hide_logistics_progress()
        login_layout_job = getattr(self, "_worker_login_layout_job", None)
        if login_layout_job:
            try:
                self.root.after_cancel(login_layout_job)
            except (AttributeError, tk.TclError):
                pass
            self._worker_login_layout_job = None
        self.worker_input_frame.pack_forget()
        self.paned_window.pack_forget()

    def _get_worker_login_layout_metrics(
        self,
        content_width: int = 0,
        content_height: int = 0,
    ) -> Dict[str, Any]:
        if content_width <= 1 or content_height <= 1:
            for widget in (getattr(self, "worker_input_frame", None), getattr(self, "root", None)):
                try:
                    candidate_width = int(widget.winfo_width())
                    candidate_height = int(widget.winfo_height())
                except (AttributeError, TypeError, ValueError, tk.TclError):
                    continue
                if candidate_width > 1 and candidate_height > 1:
                    content_width = candidate_width
                    content_height = candidate_height
                    break
        metrics = calculate_worker_login_layout_metrics(
            max(1, content_width),
            max(1, content_height),
            getattr(self, "scale_factor", 1.0),
        )
        return {
            "profile": metrics.profile,
            "short_height": metrics.short_height,
            "horizontal_pad": metrics.horizontal_pad,
            "logo_max_width": metrics.logo_max_width,
            "logo_max_height": metrics.logo_max_height,
            "logo_pad_y": metrics.logo_pad_y,
            "title_pad_y": metrics.title_pad_y,
            "field_label_pad_y": metrics.field_label_pad_y,
            "entry_ipady": metrics.entry_ipady,
            "button_pad_y": metrics.button_pad_y,
            "button_pad_x": metrics.button_pad_x,
            "button_ipady": metrics.button_ipady,
            "estimated_content_height": metrics.estimated_content_height,
        }

    def _schedule_worker_login_layout_refresh(self, event=None) -> None:
        if getattr(self, "_worker_login_layout_job", None):
            return
        try:
            self._worker_login_layout_job = self.root.after_idle(self._apply_worker_login_layout)
        except AttributeError:
            try:
                self._worker_login_layout_job = self.root.after(0, self._apply_worker_login_layout)
            except AttributeError:
                self._apply_worker_login_layout()
        except tk.TclError:
            return

    def _apply_worker_login_layout(self, event=None) -> None:
        self._worker_login_layout_job = None
        center_frame = getattr(self, "_worker_login_center_frame", None)
        if center_frame is None:
            return
        try:
            if hasattr(center_frame, "winfo_exists") and not center_frame.winfo_exists():
                return
            width = int(self.worker_input_frame.winfo_width())
            height = int(self.worker_input_frame.winfo_height())
        except (AttributeError, TypeError, ValueError, tk.TclError):
            return
        if width <= 1 or height <= 1:
            try:
                width = int(self.root.winfo_width())
                height = int(self.root.winfo_height())
            except (AttributeError, TypeError, ValueError, tk.TclError):
                return
        metrics = self._get_worker_login_layout_metrics(width, height)
        metrics_key = tuple(metrics.items())
        if metrics_key == getattr(self, "_worker_login_layout_metrics_key", None):
            return
        self._worker_login_layout_metrics_key = metrics_key
        self._worker_login_layout_metrics = metrics

        try:
            center_frame.grid_configure(padx=metrics["horizontal_pad"])
            logo_label = getattr(self, "_worker_login_logo_label", None)
            if logo_label is not None:
                logo_label.pack_configure(pady=metrics["logo_pad_y"])
            self._worker_login_title_label.pack_configure(pady=metrics["title_pad_y"])
            self._worker_login_name_label.pack_configure(pady=metrics["field_label_pad_y"])
            self.worker_entry.pack_configure(ipady=metrics["entry_ipady"])
            self._worker_login_button_container.pack_configure(pady=metrics["button_pad_y"])
            for button in self._worker_login_buttons:
                button.pack_configure(
                    padx=metrics["button_pad_x"],
                    ipady=metrics["button_ipady"],
                )
        except (AttributeError, tk.TclError):
            return

        logo_source = getattr(self, "_worker_login_logo_source", None)
        logo_label = getattr(self, "_worker_login_logo_label", None)
        if logo_source is None or logo_label is None:
            return
        source_width = max(1, int(logo_source.width))
        source_height = max(1, int(logo_source.height))
        target_width = min(metrics["logo_max_width"], source_width)
        target_height = max(1, int(round(target_width * source_height / source_width)))
        if target_height > metrics["logo_max_height"]:
            target_height = metrics["logo_max_height"]
            target_width = max(1, int(round(target_height * source_width / source_height)))
        logo_size = (target_width, target_height)
        if logo_size == getattr(self, "_worker_login_logo_size", None):
            return
        try:
            resized = logo_source.resized(*logo_size, resample="bilinear")
            self.logo_photo_ref = resized.to_tk_photo_image(master=logo_label)
            logo_label.configure(image=self.logo_photo_ref)
            self._worker_login_logo_size = logo_size
        except Exception as exc:
            print(f"로고 크기 조정 실패: {exc}")

    def show_worker_input_screen(self):
        self._clear_main_frames()
        self.worker_role = ""
        self._admin_pin_login_epoch = uuid.uuid4().hex
        self.worker_input_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        for widget in self.worker_input_frame.winfo_children(): widget.destroy()
        self.worker_input_frame.grid_rowconfigure(0, weight=1)
        self.worker_input_frame.grid_columnconfigure(0, weight=1)
        center_frame = ttk.Frame(self.worker_input_frame, style='TFrame')
        center_frame.grid(row=0, column=0)
        self._worker_login_center_frame = center_frame
        self._worker_login_layout_job = None
        self._worker_login_layout_metrics_key = None
        self._worker_login_logo_source = None
        self._worker_login_logo_label = None
        self._worker_login_logo_size = None
        self._authenticated_protected_admin = False
        try:
            logo_path = resource_path(os.path.join('assets', 'logo.png'))
            self._worker_login_logo_source = RasterImage.from_png(logo_path)
            self._worker_login_logo_label = ttk.Label(center_frame, style='TLabel')
            self._worker_login_logo_label.pack()
        except Exception as e:
            print(f"로고 로드 실패: {e}")
        self._worker_login_title_label = ttk.Label(center_frame, text=self.APP_TITLE, style='Title.TLabel')
        self._worker_login_title_label.pack()
        self._worker_login_name_label = ttk.Label(
            center_frame,
            text="작업자 이름",
            style='TLabel',
            font=(self.DEFAULT_FONT, int(12*self.scale_factor)),
        )
        self._worker_login_name_label.pack()
        workers = self._worker_selection_names()
        self.worker_entry_var = tk.StringVar(value=workers[0] if workers else "")
        self.worker_entry = ttk.Combobox(
            center_frame,
            textvariable=self.worker_entry_var,
            values=workers,
            state='readonly',
            width=25,
            font=(self.DEFAULT_FONT, int(18*self.scale_factor), 'bold'),
            justify='center',
        )
        self.worker_entry.pack()
        self.worker_entry.bind('<Return>', self.start_work)
        self.worker_entry.bind('<<ComboboxSelected>>', self._update_worker_input_mask)
        self.worker_entry.focus()
        button_container = ttk.Frame(center_frame, style='TFrame')
        self._worker_login_button_container = button_container
        button_container.pack()
        admin_button = ttk.Button(
            button_container,
            text="관리자",
            command=self._start_protected_admin,
            style='Secondary.TButton',
            width=16,
        )
        start_button = ttk.Button(
            button_container,
            text="작업 시작",
            command=self.start_work,
            style='TButton',
            width=20,
        )
        self._worker_login_buttons = [admin_button, start_button]
        admin_button.pack(side=tk.LEFT)
        start_button.pack(side=tk.LEFT)
        self._worker_roster_notice = ttk.Label(center_frame, text=self._worker_roster_notice_text(), style='TLabel')
        self._worker_roster_notice.pack()
        self._apply_worker_login_layout()
        self.worker_input_frame.bind('<Configure>', self._schedule_worker_login_layout_refresh)
        self.root.after(0, self._apply_worker_login_layout)
        self._refresh_worker_roster()

    def _refresh_worker_entry_options(self):
        if not getattr(self, "worker_name", "") and hasattr(self, 'worker_entry') and hasattr(self.worker_entry, 'configure'):
            workers = self._worker_selection_names()
            self.worker_entry.configure(values=workers)
            if not getattr(self, "worker_name", "") and self.worker_entry.get() not in workers:
                self._set_worker_entry_value(workers[0] if workers else "")
        notice = getattr(self, "_worker_roster_notice", None)
        if notice is not None:
            try:
                notice.configure(text=self._worker_roster_notice_text())
            except tk.TclError:
                pass

    def _worker_selection_names(self):
        roster = getattr(self, "worker_roster", None)
        if roster is None or not roster.has_rows:
            return self.worker_registry.list_workers()
        return [row["display_name"] for row in self.worker_registry.order_roster(roster.active_workers())
                if row["display_name"] not in {PROTECTED_ADMIN_OPERATOR_ID, PROTECTED_ADMIN_DISPLAY_NAME}]

    def _worker_roster_notice_text(self):
        roster = getattr(self, "worker_roster", None)
        if (roster is None or not roster.has_rows) and self.worker_registry.list_workers():
            return "이 PC에 저장된 이름으로 한시 선택합니다. 관리자에게 명단 등록을 요청하세요."
        return "관리자에게 명단 등록을 요청하세요"

    def _refresh_worker_roster(self):
        job = getattr(self, "_roster_refresh_job", None)
        if job:
            self.root.after_cancel(job)
        self._roster_refresh_job = None
        roster = getattr(self, "worker_roster", None)
        if roster is None or getattr(self, "_ui_close_requested", False):
            return
        epoch = getattr(self, "_admin_pin_login_epoch", "")
        if (getattr(self, "_roster_pending_epoch", None) == epoch
                and getattr(self, "_roster_thread", None) is not None
                and self._roster_thread.is_alive()):
            return
        self._roster_pending_epoch = epoch
        # A login transition retires the old query. Its result has no cache/UI effects.
        attempt = uuid.uuid4().hex
        self._roster_attempt = attempt
        requested_version = roster.known_version
        results = queue.Queue(maxsize=1)
        def read():
            client = None
            try:
                client = self._admin_pin_client_for_work()
                answer = client.query_roster(authority_scope_id=roster.authority_scope_id,
                                             known_version=requested_version)
            except Exception:
                answer = None
            finally:
                if client is not None and getattr(self, "_admin_pin_client", None) is not client:
                    session = getattr(client, "session", None)
                    if session is not None:
                        session.close()
            capability_client = None
            enabled = False
            try:
                capability_client = logistics_transfer_client_from_env(probe_required=False)
                if capability_client is not None:
                    enabled = record_identity_enabled(capability_client.get_capabilities())
            except Exception:
                pass
            finally:
                if capability_client is not None:
                    session = getattr(capability_client, "session", None)
                    if session is not None:
                        session.close()
            if attempt == getattr(self, "_roster_attempt", None) and epoch == getattr(self, "_admin_pin_login_epoch", ""):
                self._worker_record_identity_enabled = enabled
            results.put(answer)
        self._roster_thread = threading.Thread(target=read, name="container-audit-roster", daemon=True)
        self._roster_thread.start()
        self._poll_worker_roster(results, attempt, epoch, requested_version)

    def _poll_worker_roster(self, results, attempt, epoch, requested_version):
        if (getattr(self, "_ui_close_requested", False) or attempt != getattr(self, "_roster_attempt", None)):
            return
        try:
            answer = results.get_nowait()
        except queue.Empty:
            self.root.after(50, lambda: self._poll_worker_roster(results, attempt, epoch, requested_version))
            return
        if epoch == getattr(self, "_admin_pin_login_epoch", "") and answer is not None:
            try:
                self.worker_roster.apply(answer, requested_version=requested_version)
                self._refresh_worker_entry_options()
                if not self._current_roster_worker_active():
                    self._disable_remembered_worker_start()
            except (OSError, ValueError, TypeError, WriterFencedError):
                pass  # Keep the last valid cache and the current tray's original owner.
        job = getattr(self, "_roster_refresh_job", None)
        if job:
            self.root.after_cancel(job)
        self._roster_refresh_job = self.root.after(60000, self._refresh_worker_roster)

    def _current_roster_worker_active(self):
        roster = getattr(self, "worker_roster", None)
        if roster is None or not roster.has_rows or getattr(self, "worker_role", "") == "ADMIN":
            return True
        name = getattr(self, "worker_name", "") or self.worker_registry.recent_worker() or ""
        worker_id = getattr(self, "_selected_roster_id", "") if getattr(self, "worker_name", "") else self.worker_registry.recent_worker_id()
        return roster.active_worker(worker_id=worker_id, name=name) is not None

    def _selected_worker_identity(self):
        worker_id = (getattr(self, "_selected_roster_id", "") or None) if getattr(self, "worker_role", "") != "ADMIN" else None
        roster = getattr(self, "worker_roster", None)
        row = roster.active_worker(worker_id=worker_id) if roster is not None and worker_id else None
        name = row["display_name"] if row else persistent_operator_name(getattr(self, "worker_name", ""))
        return record_identity({"worker_id": row["worker_id"] if row else None, "worker_name_snapshot": name}) if name else {}

    def _record_worker_name(self):
        return (getattr(getattr(self, "current_tray", None), "worker_name_snapshot", "")
                or persistent_operator_name(getattr(self, "worker_name", "")))

    def _worker_record_context(self):
        tray = getattr(self, "current_tray", None)
        if getattr(tray, "master_label_code", ""):
            identity = record_identity(vars(tray)) if getattr(tray, "worker_name_snapshot", "") else {}
        else:
            identity = self._selected_worker_identity()
        return {**identity, "enabled": getattr(self, "_worker_record_identity_enabled", False) is True} if identity else {}

    def _owns_worker_record(self, value):
        return record_owner_matches(value,
            worker_name=persistent_operator_name(getattr(self, "worker_name", "")),
            worker_id=getattr(self, "_selected_roster_id", ""))

    def _roster_allows_new_tray(self):
        if self._current_roster_worker_active():
            selected = self._selected_worker_identity()
            if selected and self.worker_name != selected["worker_name_snapshot"] and not self.current_tray.master_label_code:
                if not self._end_work_session(reason="roster_name_corrected"):
                    return False
                self.worker_name = selected["worker_name_snapshot"]
                self._load_session_state()
                if not self._begin_or_resume_work_session():
                    return False
            return True
        if not self._disable_remembered_worker_start():
            return False
        if not self._end_work_session(reason="roster_inactive"):
            self.show_status_message("작업 종료 기록을 저장하지 못했습니다. 다시 시도하세요.", self.COLOR_DANGER, duration=0)
            return False
        self._work_session_identity_bound = False
        self.worker_name = ""
        self.worker_role = ""
        self.show_worker_input_screen()
        return False

    def _start_protected_admin(self):
        code = simpledialog.askstring("관리자", "관리자 코드를 입력하세요.", parent=self.root, show="●")
        if code is None:
            return
        # Only this button routes a credential into the existing protected profile check.
        self._authenticated_protected_admin = False
        if not is_protected_admin_candidate(code):
            messagebox.showerror("인증 오류", "관리자 코드를 확인하세요.", parent=self.root)
            return
        if self._resolve_worker_login_candidate(code) == PROTECTED_ADMIN_OPERATOR_ID:
            self.start_work()

    def _set_worker_entry_value(self, value: str) -> None:
        if hasattr(self, "worker_entry_var"):
            self.worker_entry_var.set(value)
        elif hasattr(self, "worker_entry") and hasattr(self.worker_entry, "set"):
            self.worker_entry.set(value)
        self._update_worker_input_mask()

    def _update_worker_input_mask(self, event=None) -> None:
        entry = getattr(self, "worker_entry", None)
        if entry is None or not hasattr(entry, "configure"):
            return
        try:
            value = str(entry.get() or "").strip()
        except (AttributeError, tk.TclError):
            value = ""
        if value != PROTECTED_ADMIN_DISPLAY_NAME:
            self._authenticated_protected_admin = False
        try:
            entry.configure(show="")
        except (TypeError, tk.TclError):
            pass

    def _resolve_worker_login_candidate(self, worker_name: str) -> Optional[str]:
        candidate = WorkerRegistry.normalize_name(worker_name)
        if is_protected_admin_candidate(candidate):
            selected_profile = getattr(self, '_protected_admin_profile_path', None)
            try:
                authenticated = (
                    is_protected_admin_code(candidate, profile_path=selected_profile)
                    if selected_profile is not None else is_protected_admin_code(candidate)
                )
            except DataGenerationBlocked as exc:
                self._authenticated_protected_admin = False
                messagebox.showerror("자료 판 확인", exc.user_message, parent=self.root)
                return None
            if not authenticated:
                self._authenticated_protected_admin = False
                messagebox.showerror(
                    "인증 오류",
                    "관리자 코드를 확인할 수 없습니다. 보호 프로필과 입력값을 확인하세요.",
                    parent=self.root,
                )
                return None
            self._authenticated_protected_admin = True
            self._set_worker_entry_value(PROTECTED_ADMIN_DISPLAY_NAME)
            return PROTECTED_ADMIN_OPERATOR_ID
        if (
            candidate == PROTECTED_ADMIN_DISPLAY_NAME
            and getattr(self, "_authenticated_protected_admin", False)
        ):
            return PROTECTED_ADMIN_OPERATOR_ID
        if candidate in {PROTECTED_ADMIN_OPERATOR_ID, PROTECTED_ADMIN_DISPLAY_NAME}:
            messagebox.showerror(
                "인증 오류",
                "보호된 관리자는 관리자 코드를 다시 입력해야 합니다.",
                parent=self.root,
            )
            return None
        return candidate

    def _ensure_worker_login_name(self, worker_name: str) -> Optional[str]:
        name = WorkerRegistry.normalize_name(worker_name)
        if name == PROTECTED_ADMIN_DISPLAY_NAME and getattr(self, "_authenticated_protected_admin", False):
            return PROTECTED_ADMIN_OPERATOR_ID
        if name not in self._worker_selection_names():
            self.show_status_message("관리자에게 명단 등록을 요청하세요", self.COLOR_DANGER, duration=0)
            return None
        roster = getattr(self, "worker_roster", None)
        row = roster.active_worker(name=name) if roster is not None and roster.has_rows else None
        local_id = self.worker_registry.worker_id_for_name(name) if row is None else ""
        try:
            WorkerRegistry._validate_name(name, roster_identity=row is not None or bool(local_id),
                                          legacy_local=row is None and not local_id)
        except ValueError:
            return None
        self._selected_roster_id = row["worker_id"] if row else local_id
        self._authenticated_protected_admin = False
        return name

    def _disable_remembered_worker_start(self) -> bool:
        registry = getattr(self, "worker_registry", None)
        if registry is None:
            return True
        try:
            registry.disable_automatic_start()
        except (OSError, UnicodeError, ValueError):
            self.show_status_message("작업자 변경 정보를 저장하지 못했습니다. 다시 시도하세요.", self.COLOR_DANGER, duration=0)
            return False
        return True

    def _start_remembered_worker(self, worker_name: Optional[str]) -> None:
        if (not worker_name or self.worker_name
                or self._work_session_recovery_blocked
                or self.transfer_seal_coordinator.client is None):
            return
        remembered_name = worker_name
        try:
            roster = getattr(self, "worker_roster", None)
            if roster is not None and roster.has_rows:
                row = roster.active_worker(worker_id=self.worker_registry.recent_worker_id(), name=worker_name)
                if row is None:
                    self._disable_remembered_worker_start()
                    return
                self.worker_registry.bind_worker_id(worker_name, row["worker_id"])
                worker_name = row["display_name"]
            if (not self.worker_registry.automatic_start_enabled()
                or self.worker_registry.recent_worker() != remembered_name
                    or worker_name not in self._worker_selection_names()
                    or (Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE).exists()
                    or self._paired_preflight_store().unidentified_pending()):
                return
            previous_session = self._load_work_session_state()
            if previous_session and previous_session["worker_name"] != remembered_name:
                # Removing the latest registry row must not log in an older
                # remembered worker from the remaining history.
                return
            store = self._preflight_hold_store()
            if store.exists():
                held = store.load()
                if held.worker == worker_name or held.state == HOLD_DRAINING:
                    return
        except (OSError, ValueError, PreflightHoldError, PairedHandoffError):
            return
        self._set_worker_entry_value(worker_name)
        self.start_work(_automatic=True)

    def start_work(self, event=None, *, _automatic=False):
        worker_name = self._ensure_worker_login_name(self.worker_entry.get())
        if not worker_name:
            return
        protected_admin_authenticated = bool(
            worker_name == PROTECTED_ADMIN_OPERATOR_ID
            and getattr(self, "_authenticated_protected_admin", False)
        )
        if not self._disable_remembered_worker_start():
            return
        self._work_session_identity_bound = False
        self.worker_name = worker_name
        self.worker_role = "ADMIN" if protected_admin_authenticated else "WORKER"
        self._admin_pin_login_epoch = uuid.uuid4().hex
        self._load_session_state()
        self._admin_pin_resume_unverified_detachments(startup=True)
        # A paired handoff (including a legacy mismatched DRAINING pair) owns
        # the exact on-disk bytes. Ordinary tray recovery may rewrite or delete
        # that slot, so inspect it read-only before offering recovery choices.
        startup_evidence = self._parked_store().enumerate_key_evidence(
            pair_store=self._paired_preflight_store(),
        )
        skip_current_recovery = (self._paired_preflight_store().unidentified_pending()
                                 or any(row.kind == "atomic_temp" and row.unidentified
                                        for row in startup_evidence))
        if not skip_current_recovery and self._preflight_hold_store().exists():
            try:
                held = self._preflight_hold_store().load()
                if held.state == HOLD_DRAINING:
                    current_path = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
                    saved_read = read_recovery_file(current_path, "current", tray_size=self.TRAY_SIZE)
                    if not saved_read.verified:
                        raise TrayStateValidationError(saved_read.reason)
                    saved = saved_read.value
                    if not self._paired_preflight_blocks_label(
                        str(saved.get("master_label_code") or "")
                    ):
                        candidate = tray_session_from_state(
                            saved, session_factory=TraySession,
                            default_tray_size=self.TRAY_SIZE,
                        )
                        self.current_tray = candidate
                        skip_current_recovery = not self._preflight_hold_matches_current_tray(held)
                        if not skip_current_recovery:
                            self.current_tray = TraySession()
            except (OSError, ValueError, TypeError, PreflightHoldError, TrayStateValidationError):
                skip_current_recovery = True
        if not skip_current_recovery:
            self._load_current_tray_state()
        if not self.worker_name:
            return
        if not self._restore_preflight_scan_hold():
            self.current_tray = TraySession()
            self.worker_name = ""
            self.worker_role = ""
            self.show_worker_input_screen()
            return
        if not self._begin_or_resume_work_session():
            self.current_tray = TraySession()
            self.worker_name = ""
            self.worker_role = ""
            self.show_worker_input_screen()
            message = ("작업 세션과 감사 outbox를 함께 저장하거나 투영하지 못했습니다. "
                       "상태를 보존했으니 다시 시도하고 계속되면 관리자에게 문의하세요.")
            if _automatic:
                self.show_status_message(message, self.COLOR_DANGER, duration=0)
            else:
                messagebox.showerror("작업 시작 기록 대기", message, parent=self.root)
            return
        self._work_session_identity_bound = True
        self._refresh_worker_roster()
        worker_registry = getattr(self, "worker_registry", None)
        if worker_registry is not None and not protected_admin_authenticated:
            try:
                selected_id = getattr(self, "_selected_roster_id", "")
                if selected_id:
                    worker_registry.mark_recent(worker_name, worker_id=selected_id)
                else:
                    worker_registry.mark_recent(worker_name)
                self._refresh_worker_entry_options()
            except (OSError, ValueError):
                # The session is durable; a preference write must not unbind it.
                self.show_status_message("작업은 시작했지만 최근 작업자 이름을 저장하지 못했습니다.",
                                         self.COLOR_DANGER, duration=0)
        # Recovery only admits work after the login's durable session binding.
        self._schedule_startup_transfer_recovery()
        if not self._audit_recovered_atomic_temps(startup_evidence):
            self.show_status_message(
                "원자 저장 중단 파일의 격리 감사 기록을 확인하지 못했습니다. 관리자 목록에서 이 건을 다시 확인하세요.",
                self.COLOR_DANGER, duration=0,
            )
        if not self.root.winfo_exists(): return
        if not self.paned_window.winfo_ismapped():
            self.show_validation_screen()
        self._refresh_transfer_post_review_state()

    def change_worker(self, *, _short_settled=False, _confirmed=False):
        if getattr(self, "_short_confirmation_undo", None) and not _short_settled:
            self._commit_short_confirmation(on_settled=lambda: self.change_worker(_short_settled=True, _confirmed=_confirmed))
            return
        if self._preflight_context_blocks_mutation():
            self.show_status_message(
                "중앙 조회 보류 묶음을 먼저 재확인해야 작업자를 변경할 수 있습니다.",
                self.COLOR_DANGER,
                duration=0,
            )
            return
        if self._operator_review_blocks_mutation():
            self._render_warning_state()
            return
        if self._phs_label_exchange_blocks_tray_transition("작업자 변경"):
            return
        if self._transfer_member_exchange_blocks_local_action("작업자 변경"):
            return
        msg = "작업자를 변경하시겠습니까?"
        if self.current_tray.master_label_code:
            msg += "\n\n진행 중인 작업은 다음 로그인 시 복구할 수 있도록 저장됩니다."
        if not _confirmed:
            self._request_inline_choice(
                "작업자 변경",
                msg + "\n변경하려면 '작업자 변경'을 누르세요. 다음 스캔은 현재 작업자로 계속합니다.",
                [("작업자 변경", lambda: self.change_worker(_confirmed=True)),
                 ("작업 계속", lambda: True)],
                on_scan=lambda: True,
            )
            return
        if not self._disable_remembered_worker_start():
            return
        if self.current_tray.master_label_code:
            if not self._save_current_tray_state():
                messagebox.showerror("작업 저장 실패", "진행 중인 트레이 상태를 저장하지 못해 작업자를 변경하지 않습니다.")
                return
            if not self._log_event(
                'WORK_PAUSE',
                detail={
                    'message': (
                        f"Worker '{persistent_operator_name(self.worker_name)}' changed."
                    )
                },
                synchronous=True,
            ):
                messagebox.showerror("작업 중지 기록 실패", "진행 중인 트레이의 중지 기록을 남기지 못해 작업자를 변경하지 않습니다.")
                return
        if self.master_label_replace_state:
            if not self._log_master_label_replacement_cancel(reason="worker_change"):
                messagebox.showerror("교체 취소 기록 실패", "현품표 교체 취소 기록을 남기지 못해 작업자를 변경하지 않습니다.")
                return
        exchange_session = getattr(self, "current_exchange_session", ProductExchangeSession())
        if exchange_session.defective_barcodes or exchange_session.good_barcodes:
            if not self._cancel_exchange(reason="worker_change"):
                messagebox.showerror("교환 취소 기록 실패", "제품 교환 취소 기록을 남기지 못해 작업자를 변경하지 않습니다.")
                return
        if not self._end_work_session(reason="worker_change"):
            messagebox.showerror(
                "작업 종료 기록 대기",
                "작업 세션 종료 상태와 감사 outbox를 함께 저장하거나 투영하지 "
                "못해 작업자를 변경하지 않습니다.",
            )
            return
        self._cancel_all_jobs()
        self.worker_name = ""
        self.worker_role = ""
        self._authenticated_protected_admin = False
        self.current_tray = TraySession()
        self._invalidate_pending_scan_callbacks()
        self._reset_master_label_replacement_state()
        self.show_worker_input_screen()

    def _load_session_state(self):
        history = load_session_history(
            save_folder=self.save_folder,
            worker_name=persistent_operator_name(self.worker_name),
            today=datetime.date.today(),
            tray_size=self.TRAY_SIZE,
        )
        self.log_file_path = history.log_file_path
        self.total_tray_count = history.total_tray_count
        self.completed_tray_times = history.completed_tray_times
        self.completed_master_labels = set(history.completed_master_labels)
        self.completed_label_rounds = set(history.completed_label_rounds)
        self.work_summary = history.work_summary
        self.tray_last_end_time = None
        for error in history.load_errors:
            print(error)
        if history.load_errors:
            messagebox.showwarning(
                "작업 현황 확인 필요",
                "금일 작업 현황을 모두 확인하지 못했습니다.\n"
                f"작업 기록 읽기 오류: {len(history.load_errors)}건\n"
                "표시된 수량에 누락이 있을 수 있습니다.\n"
                "관리자에게 작업 기록 확인을 요청해 주세요.",
                parent=self.root,
            )
        elif any(self.work_summary):
            self.show_status_message(f"금일 작업 현황을 불러왔습니다. (총 {self.total_tray_count} 파렛트)", self.COLOR_PRIMARY)

    def _save_current_tray_state(self) -> bool:
        lock = getattr(self, "_tray_state_persist_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._tray_state_persist_lock = lock
        with writer_admission("gui_tray_state_save"), lock:
            if not self.current_tray.master_label_code:
                return False
            state = self._current_tray_state_snapshot()
            return self._save_tray_state_snapshot(state)

    def _current_tray_save_operation(self) -> Callable[[], bool]:
        """Freeze the UI-owned state before handing its write to the lane."""
        if not self.current_tray.master_label_code:
            return lambda: False
        state = self._current_tray_state_snapshot()
        return lambda: self._save_tray_state_snapshot(state)

    @writer_sink("gui_tray_state_save")
    def _save_tray_state_snapshot(self, state: Dict[str, Any]) -> bool:
        lock = getattr(self, "_tray_state_persist_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._tray_state_persist_lock = lock
        with lock:
            try:
                state_path = os.path.join(
                    self.save_folder,
                    self.CURRENT_TRAY_STATE_FILE,
                )
                if Path(state_path).exists():
                    try:
                        prior = json.loads(Path(state_path).read_text(encoding='utf-8'))
                    except (UnicodeError, json.JSONDecodeError):
                        prior = {}  # Preserve the existing explicit-save behavior.
                    pending = list(state.get('pending_audit_events', []))
                    for event in prior.get('pending_audit_events', []):
                        if event not in pending:
                            pending.append(event)
                    if pending:
                        state['pending_audit_events'] = pending
                atomic_write_json(state_path, state, indent=4)
                self._stage_checkpoint_audit_events(state)
                return True
            except Exception as e:
                print(f"현재 트레이 상태 저장 실패: {e}")
                return False

    def _checkpoint_audit_event(self, event_type: str, **kwargs) -> Dict[str, Any]:
        if 'worker_record' not in kwargs:
            kwargs['worker_record'] = self._worker_record_context()
        payload = self._prepare_event_log_entry(event_type, synchronous=True, **kwargs)
        if not payload:
            raise ValueError('checkpoint audit payload is invalid')
        return {'log_file_name': Path(kwargs.get('log_file_path_override') or (
                    self._completion_projection_log_path() if getattr(getattr(self, 'current_tray', None), 'worker_name_snapshot', '')
                    else self.log_file_path)).name,
                'local_only': payload['local_only'], 'log_entry': payload['log_entry'],
                'worker_record': payload['worker_record']}

    def _checkpoint_stored_audit_event(self, event_type: str, *, stored_worker_record, **kwargs):
        return self._checkpoint_audit_event(
            event_type, worker_record=dict(stored_worker_record or {}), **kwargs)

    def _project_stored_audit_event(self, event: Mapping[str, Any], *, stored_worker_record) -> bool:
        path = self._completion_projection_log_path(event['log_file_name'])
        if event['local_only']:
            path = local_only_event_log_path(path, local_events_dir=getattr(self, 'local_events_folder', ''))
        return self._write_event_log_entry({
            'log_file_path': str(path), 'log_entry': dict(event['log_entry']),
            'local_only': event['local_only'], 'worker_record': dict(stored_worker_record or {}),
        }, synchronous=True)

    def _stage_checkpoint_audit_events(self, state: Mapping[str, Any]) -> bool:
        try:
            for event in state.get('pending_audit_events', []):
                path = self._completion_projection_log_path(event['log_file_name'])
                if event['local_only']:
                    path = local_only_event_log_path(
                        path, local_events_dir=getattr(self, 'local_events_folder', ''))
                self._event_log_outbox(str(path)).stage(str(path), event['log_entry'],
                    worker_record=event.get('worker_record'))
            return True
        except Exception as exc:
            self._record_log_write_error(f'checkpoint 감사 재시도: {exc.__class__.__name__}')
            return False

    @writer_sink('gui_tray_state_save')
    def _recover_checkpoint_audit_events(self):
        """Read original rows before a subsequent scan can replace its checkpoint."""
        current_name = getattr(self, 'CURRENT_TRAY_STATE_FILE', '')
        paths = [Path(self.save_folder) / current_name] if current_name else []
        parked = getattr(self, 'parked_trays_dir', '')
        if parked:
            paths.extend(sorted(Path(parked).glob('*.json')))
        paths.extend(sorted((Path(self.save_folder) / 'short_confirmations').glob('*.json')))
        staged = []
        for path in paths:
            if not path.exists():
                continue
            try:
                state = json.loads(path.read_text(encoding='utf-8'))
                found = False
                # Short confirmations retain the original checkpoint and, on
                # cancellation, its restored state. Older records have no
                # top-level audit list; all three copies remain replay sources.
                for source in (state, state.get('state'), state.get('undo_state')):
                    if isinstance(source, dict) and source.get('pending_audit_events'):
                        validate_checkpoint_audit_events(source['pending_audit_events'])
                        if not self._stage_checkpoint_audit_events(source):
                            raise OSError('checkpoint audit outbox staging failed')
                        found = True
                if found:
                    staged.append((path, state))
            except (OSError, UnicodeError, ValueError, AttributeError) as exc:
                # Preserve this source while allowing unrelated CSV rows to drain.
                self._record_log_write_error(f'checkpoint 감사 원본 확인 필요: {path.name}: {exc.__class__.__name__}')
        return staged

    @writer_sink('gui_tray_state_save')
    def _clear_projected_checkpoint_audits(self, staged) -> None:
        lock = getattr(self, '_tray_state_persist_lock', None)
        if lock is None:
            lock = self._tray_state_persist_lock = threading.RLock()
        with lock:
            for path, original in staged:
                if not path.exists():
                    continue
                state = json.loads(path.read_text(encoding='utf-8'))
                events = []
                for name in (None, 'state', 'undo_state'):
                    source = state if name is None else state.get(name)
                    saved = original if name is None else original.get(name)
                    if not isinstance(source, dict) or not isinstance(saved, dict):
                        continue
                    projected = saved.get('pending_audit_events')
                    # A newer save owns its added rows; never overwrite it.
                    if not projected or source.get('pending_audit_events') != projected:
                        continue
                    source.pop('pending_audit_events')
                    events.extend(projected)
                if not events:
                    continue
                if state.get('audit_reset_committed'):
                    path.unlink()
                else:
                    atomic_write_json(path, state, indent=4)
                tray = getattr(self, 'current_tray', None)
                if tray is not None:
                    tray.pending_audit_events = [e for e in getattr(tray, 'pending_audit_events', []) if e not in events]

    @staticmethod
    def _activation_event_contract_from_state(
        state: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        payload = state.get(ACTIVATION_EVENT_STATE_KEY)
        if payload is None:
            return None
        return {
            "schema_version": int(payload["schema_version"]),
            "event_type": str(payload["event_type"]),
            "idempotency_key": str(payload["idempotency_key"]),
            "observed_at": str(payload["observed_at"]),
            "projection_log_name": str(payload["projection_log_name"]),
            "projection_worker_name": str(payload["projection_worker_name"]),
            "master_label_code": str(payload["master_label_code"]),
            "event_detail": dict(payload["event_detail"]),
            **({"worker_record": dict(payload["worker_record"])} if "worker_record" in payload else {}),
        }

    def _active_activation_event_contract(self) -> Optional[Dict[str, Any]]:
        payload = getattr(self, "_pending_activation_event_contract", None)
        return dict(payload) if isinstance(payload, Mapping) else None

    def _activation_event_contract(
        self,
        *,
        event_type: str,
        event_detail: Mapping[str, Any],
        master_label_code: str,
        observed_at: datetime.datetime,
    ) -> Dict[str, Any]:
        projection_worker = self._record_worker_name()
        if not projection_worker:
            raise ValueError("activation projection worker is missing")
        projection_path = self._completion_projection_log_path()
        return {
            "schema_version": ACTIVATION_EVENT_STATE_SCHEMA_VERSION,
            "event_type": str(event_type),
            "idempotency_key": f"tray-activation:{uuid.uuid4().hex}",
            "observed_at": observed_at.isoformat(),
            "projection_log_name": projection_path.name,
            "projection_worker_name": projection_worker,
            "master_label_code": str(master_label_code),
            "event_detail": dict(sanitize_persistent_value(dict(event_detail))),
            "worker_record": self._worker_record_context(),
        }

    def _project_activation_event_contract(
        self,
        contract: Mapping[str, Any],
    ) -> bool:
        try:
            projection_path = self._completion_projection_log_path(
                str(contract["projection_log_name"])
            )
            return self._log_stored_event(
                str(contract["event_type"]),
                detail=dict(contract["event_detail"]),
                synchronous=True,
                idempotency_key=str(contract["idempotency_key"]),
                event_timestamp=str(contract["observed_at"]),
                log_file_path_override=str(projection_path),
                deduplicate=True,
                worker_name_override=str(contract["projection_worker_name"]),
                stored_worker_record=contract.get("worker_record", {}),
            )
        except (KeyError, TypeError, ValueError) as exc:
            self._record_log_write_error(
                f"현품표 시작 감사 outbox 투영 오류: {exc}"
            )
            return False

    def _drain_pending_activation_event(self) -> bool:
        """Project and clear one activation outbox row without losing it.

        A failed CSV projection leaves the complete contract embedded in the
        current tray snapshot.  A crash after CSV fsync but before marker clear
        is reconciled by the idempotent event/key pair on the next start.
        """

        contract = self._active_activation_event_contract()
        if contract is None:
            return True
        if not self._project_activation_event_contract(contract):
            return False
        self._pending_activation_event_contract = None
        if self._clear_persisted_activation_event(contract):
            return True
        self._pending_activation_event_contract = contract
        print(
            "현품표 시작 감사 outbox 정리 실패: CSV는 durable 하며 "
            "다음 저장 또는 재시작에서 idempotent 재확인합니다."
        )
        return True

    def _clear_persisted_activation_event(
        self,
        contract: Mapping[str, Any],
    ) -> bool:
        lock = getattr(self, "_tray_state_persist_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._tray_state_persist_lock = lock
        with lock:
            try:
                state_path = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
                with state_path.open("r", encoding="utf-8") as f_handle:
                    persisted = json.load(f_handle)
                persisted_contract = self._activation_event_contract_from_state(
                    persisted
                )
                if persisted_contract != dict(contract):
                    return False
                persisted.pop(ACTIVATION_EVENT_STATE_KEY, None)
                validate_tray_state(
                    persisted,
                    default_tray_size=self.TRAY_SIZE,
                )
                return self._save_tray_state_snapshot(persisted)
            except (AttributeError, OSError, TypeError, ValueError):
                return False

    def _reconcile_activation_event_from_state(
        self,
        state: Dict[str, Any],
    ) -> bool:
        contract = self._activation_event_contract_from_state(state)
        self._pending_activation_event_contract = contract
        if contract is None:
            return True
        if not self._project_activation_event_contract(contract):
            return False
        self._pending_activation_event_contract = None
        if self._clear_persisted_activation_event(contract):
            state.pop(ACTIVATION_EVENT_STATE_KEY, None)
            return True
        self._pending_activation_event_contract = contract
        print(
            "복구된 현품표 시작 감사 outbox 정리 실패: CSV는 durable 하며 "
            "상태 marker를 보존합니다."
        )
        return True

    def _audit_event_contract(
        self,
        *,
        event_type: str,
        event_detail: Mapping[str, Any],
        idempotency_key: str,
        observed_at: datetime.datetime,
        projection_worker_name: str = "",
        canonical_event_name: str = "",
    ) -> Dict[str, Any]:
        projection_worker = persistent_operator_name(
            projection_worker_name or self._record_worker_name()
        )
        if not projection_worker:
            raise ValueError("audit projection worker is missing")
        projection_path = self._completion_projection_log_path()
        return {
            "schema_version": 1,
            "event_type": str(event_type),
            "canonical_event_name": str(canonical_event_name or ""),
            "idempotency_key": str(idempotency_key),
            "observed_at": observed_at.isoformat(),
            "projection_log_name": projection_path.name,
            "projection_worker_name": projection_worker,
            "event_detail": dict(sanitize_persistent_value(dict(event_detail))),
            "worker_record": self._worker_record_context(),
        }

    def _project_audit_event_contract(self, contract: Mapping[str, Any]) -> bool:
        try:
            projection_path = self._completion_projection_log_path(
                str(contract["projection_log_name"])
            )
            canonical_event_name = str(
                contract.get("canonical_event_name") or ""
            )
            return self._log_stored_event(
                str(contract["event_type"]),
                detail=dict(contract["event_detail"]),
                synchronous=True,
                canonical_event_name=canonical_event_name or None,
                idempotency_key=str(contract["idempotency_key"]),
                event_timestamp=str(contract["observed_at"]),
                log_file_path_override=str(projection_path),
                deduplicate=True,
                worker_name_override=str(contract["projection_worker_name"]),
                stored_worker_record=contract.get("worker_record", {}),
            )
        except (KeyError, TypeError, ValueError) as exc:
            self._record_log_write_error(f"감사 outbox 투영 오류: {exc}")
            return False

    @staticmethod
    def _parked_restore_contract_from_state(
        state: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        payload = state.get(PARKED_RESTORE_STATE_KEY)
        if payload is None:
            return None
        return {
            "schema_version": int(payload["schema_version"]),
            "operation_id": str(payload["operation_id"]),
            "parked_source_name": str(payload["parked_source_name"]),
            "parked_source_sha256": str(payload["parked_source_sha256"]),
            "restored_master_label_code": str(
                payload["restored_master_label_code"]
            ),
            "projection_events": [
                {
                    "schema_version": int(event["schema_version"]),
                    "event_type": str(event["event_type"]),
                    "canonical_event_name": str(
                        event.get("canonical_event_name") or ""
                    ),
                    "idempotency_key": str(event["idempotency_key"]),
                    "observed_at": str(event["observed_at"]),
                    "projection_log_name": str(event["projection_log_name"]),
                    "projection_worker_name": str(
                        event["projection_worker_name"]
                    ),
                    "event_detail": dict(event["event_detail"]),
                    **({"worker_record": dict(event["worker_record"])} if "worker_record" in event else {}),
                }
                for event in payload["projection_events"]
            ],
        }

    def _active_parked_restore_contract(self) -> Optional[Dict[str, Any]]:
        payload = getattr(self, "_pending_parked_restore_contract", None)
        if not isinstance(payload, Mapping):
            return None
        return self._parked_restore_contract_from_state(
            {PARKED_RESTORE_STATE_KEY: payload}
        )

    def _build_parked_restore_contract(
        self,
        *,
        parked_path: Path,
        restored_state: Mapping[str, Any],
        restore_detail: Mapping[str, Any],
        discard_detail: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        source_read = read_recovery_file(parked_path, "parked", tray_size=self.TRAY_SIZE)
        if not source_read.verified:
            raise ValueError("parked restore source cannot be verified")
        operation_id = f"parked-restore:{uuid.uuid4().hex}"
        observed_at = datetime.datetime.now()
        projection_events: List[Dict[str, Any]] = []
        if discard_detail is not None:
            projection_events.append(
                self._audit_event_contract(
                    event_type="TRAY_DISCARDED_BY_OPERATOR",
                    event_detail=discard_detail,
                    idempotency_key=f"{operation_id}:discard",
                    observed_at=observed_at,
                )
            )
        projection_events.append(
            self._audit_event_contract(
                event_type="TRAY_RESTORED_FROM_PARK",
                canonical_event_name="TRAY_RESTORED",
                event_detail=restore_detail,
                idempotency_key=f"{operation_id}:restore",
                observed_at=observed_at,
            )
        )
        restored_identity = record_identity(restored_state)
        projection_events[-1]["worker_record"] = (
            {**restored_identity, "enabled": getattr(self, "_worker_record_identity_enabled", False) is True}
            if restored_identity else {})
        if restored_identity:
            restored_name = restored_identity["worker_name_snapshot"]
            projection_events[-1]["projection_worker_name"] = restored_name
            projection_events[-1]["projection_log_name"] = self._completion_projection_log_path(
                worker_name_snapshot=restored_name).name
        return {
            "schema_version": PARKED_RESTORE_STATE_SCHEMA_VERSION,
            "operation_id": operation_id,
            "parked_source_name": parked_path.name,
            "parked_source_sha256": source_read.sha256,
            "restored_master_label_code": str(
                restored_state.get("master_label_code") or ""
            ),
            "projection_events": projection_events,
        }

    def _cleanup_parked_restore_source(
        self,
        contract: Mapping[str, Any],
    ) -> bool:
        try:
            source_name = str(contract["parked_source_name"])
            source_path = self._parked_store().directory / source_name
            if not self._is_parked_tray_path(str(source_path)):
                return False
            if not source_path.exists():
                return True
            source_read = read_recovery_file(source_path, "parked", tray_size=self.TRAY_SIZE)
            if not source_read.verified:
                return False
            source_sha256 = source_read.sha256
            if source_sha256 != str(contract["parked_source_sha256"]):
                self._record_log_write_error(
                    "보류 복원 source hash가 outbox와 일치하지 않습니다."
                )
                return False
            ParkedTrayStore.delete(source_path)
            return True
        except (KeyError, OSError, TypeError, ValueError) as exc:
            self._record_log_write_error(
                f"보류 복원 source 정리 오류: {exc.__class__.__name__}"
            )
            return False

    def _clear_persisted_parked_restore(
        self,
        contract: Mapping[str, Any],
    ) -> bool:
        lock = getattr(self, "_tray_state_persist_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._tray_state_persist_lock = lock
        with lock:
            try:
                state_path = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
                with state_path.open("r", encoding="utf-8") as f_handle:
                    persisted = json.load(f_handle)
                persisted_contract = self._parked_restore_contract_from_state(
                    persisted
                )
                if persisted_contract != dict(contract):
                    return False
                persisted.pop(PARKED_RESTORE_STATE_KEY, None)
                validate_tray_state(
                    persisted,
                    default_tray_size=self.TRAY_SIZE,
                )
                return self._save_tray_state_snapshot(persisted)
            except (AttributeError, KeyError, OSError, TypeError, ValueError):
                return False

    def _drain_pending_parked_restore(self) -> bool:
        contract = self._active_parked_restore_contract()
        if contract is None:
            return True
        for event in contract["projection_events"]:
            if not self._project_audit_event_contract(event):
                return False
        if not self._cleanup_parked_restore_source(contract):
            return False
        self._pending_parked_restore_contract = None
        if self._clear_persisted_parked_restore(contract):
            return True
        self._pending_parked_restore_contract = contract
        print(
            "보류 복원 감사 outbox 정리 실패: projection/source cleanup은 "
            "durable 하며 다음 재시작에서 idempotent 재확인합니다."
        )
        return True

    def _reconcile_parked_restore_from_state(
        self,
        state: Dict[str, Any],
    ) -> bool:
        contract = self._parked_restore_contract_from_state(state)
        self._pending_parked_restore_contract = contract
        if contract is None:
            return True
        if not self._drain_pending_parked_restore():
            return False
        if self._active_parked_restore_contract() is None:
            state.pop(PARKED_RESTORE_STATE_KEY, None)
        return True

    def _work_session_state_path(self) -> Optional[Path]:
        save_folder = str(getattr(self, "save_folder", "") or "").strip()
        state_file = str(
            getattr(self, "WORK_SESSION_STATE_FILE", "") or ""
        ).strip()
        if not save_folder or not state_file:
            return None
        return Path(save_folder) / state_file

    def _load_work_session_state(self) -> Optional[Dict[str, Any]]:
        state_path = self._work_session_state_path()
        if state_path is None or not state_path.exists():
            return None
        if state_path.stat().st_size > 64 * 1024:
            raise WorkSessionStateError("work session state is too large")
        with state_path.open("r", encoding="utf-8") as f_handle:
            state = json.load(f_handle)
        return validate_work_session_state(state)

    @writer_sink("gui_work_session_save")
    def _save_work_session_state(self, state: Mapping[str, Any]) -> bool:
        state_path = self._work_session_state_path()
        if state_path is None:
            return False
        lock = getattr(self, "_work_session_persist_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._work_session_persist_lock = lock
        with lock:
            try:
                normalized = validate_work_session_state(state)
                atomic_write_json(
                    state_path,
                    normalized,
                    indent=2,
                    ensure_ascii=False,
                    trailing_newline=True,
                )
                return True
            except (OSError, TypeError, ValueError) as exc:
                self._record_log_write_error(
                    f"작업 세션 journal 저장 오류: {exc.__class__.__name__}"
                )
                return False

    def _reconcile_work_session_state(self) -> bool:
        if self._work_session_state_path() is None:
            return True
        try:
            state = self._load_work_session_state()
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, WorkSessionStateError) as exc:
            self._record_log_write_error(
                f"작업 세션 journal 검증 오류: {exc.__class__.__name__}"
            )
            return False
        if state is None:
            self._work_session_id = ""
            return True
        phase = state["phase"]
        if phase in {
            WORK_SESSION_PHASE_START_PENDING,
            WORK_SESSION_PHASE_END_PENDING,
        }:
            if not self._project_audit_event_contract(state["pending_event"]):
                return False
            state["pending_event"] = None
            state["phase"] = (
                WORK_SESSION_PHASE_ACTIVE
                if phase == WORK_SESSION_PHASE_START_PENDING
                else WORK_SESSION_PHASE_CLOSED
            )
            if not self._save_work_session_state(state):
                return False
            phase = state["phase"]
        self._work_session_id = (
            state["session_id"] if phase == WORK_SESSION_PHASE_ACTIVE else ""
        )
        return True

    def _begin_or_resume_work_session(self) -> bool:
        if self._work_session_state_path() is None:
            return self._log_event(
                "WORK_START",
                detail={
                    "message": (
                        f"작업자 '{persistent_operator_name(self.worker_name)}'이(가) "
                        "작업을 시작했습니다."
                    )
                },
                synchronous=True,
            )
        if not self._reconcile_work_session_state():
            self._work_session_recovery_blocked = True
            return False
        try:
            previous = self._load_work_session_state()
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, WorkSessionStateError):
            self._work_session_recovery_blocked = True
            return False
        actor = persistent_operator_name(self.worker_name)
        if (
            previous is not None
            and previous["phase"] == WORK_SESSION_PHASE_ACTIVE
            and self._owns_worker_record(previous)
        ):
            self._work_session_id = previous["session_id"]
            self._work_session_recovery_blocked = False
            return True
        session_suffix = uuid.uuid4().hex
        session_id = f"work-session:{session_suffix}"
        observed_at = datetime.datetime.now()
        pending_event = self._audit_event_contract(
            event_type="WORK_START",
            event_detail={
                "message": f"작업자 '{actor}'이(가) 작업을 시작했습니다.",
                "work_session_id": session_id,
            },
            idempotency_key=f"work-session-start:{session_suffix}",
            observed_at=observed_at,
            projection_worker_name=actor,
        )
        state = {
            "schema_version": WORK_SESSION_STATE_SCHEMA_VERSION,
            "session_id": session_id,
            "previous_session_id": (
                str(previous.get("session_id") or "") if previous else ""
            ),
            "worker_name": actor,
            "worker_role": str(self.worker_role or "WORKER"),
            "phase": WORK_SESSION_PHASE_START_PENDING,
            "started_at": observed_at.isoformat(),
            "ended_at": "",
            "pending_event": pending_event,
            **self._selected_worker_identity(),
        }
        if not self._save_work_session_state(state):
            return False
        if not self._reconcile_work_session_state():
            self._work_session_recovery_blocked = True
            return False
        self._work_session_recovery_blocked = False
        return True

    def _end_work_session(self, *, reason: str) -> bool:
        if reason != "app_close" and not self._disable_remembered_worker_start():
            return False
        if self._work_session_state_path() is None:
            return self._log_event(
                "WORK_END",
                detail={"message": "User closed the program.", "reason": reason},
                synchronous=True,
            )
        if not self._reconcile_work_session_state():
            self._work_session_recovery_blocked = True
            return False
        try:
            state = self._load_work_session_state()
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, WorkSessionStateError):
            self._work_session_recovery_blocked = True
            return False
        actor = persistent_operator_name(self.worker_name)
        if (
            state is None
            or state["phase"] != WORK_SESSION_PHASE_ACTIVE
            or not self._owns_worker_record(state)
        ):
            return True
        session_suffix = state["session_id"].removeprefix("work-session:")
        observed_at = datetime.datetime.now()
        state["phase"] = WORK_SESSION_PHASE_END_PENDING
        state["ended_at"] = observed_at.isoformat()
        state["pending_event"] = self._audit_event_contract(
            event_type="WORK_END",
            event_detail={
                "message": "User ended the work session.",
                "reason": reason,
                "work_session_id": state["session_id"],
            },
            idempotency_key=f"work-session-end:{session_suffix}",
            observed_at=observed_at,
            projection_worker_name=state["worker_name"],
        )
        state["pending_event"]["worker_record"] = {
            **record_identity(state), "enabled": getattr(self, "_worker_record_identity_enabled", False) is True}
        if not self._save_work_session_state(state):
            return False
        if not self._reconcile_work_session_state():
            self._work_session_recovery_blocked = True
            return False
        self._work_session_recovery_blocked = False
        return True

    def _active_operator_review_snapshot(self) -> Optional[CompletionOutcomeSnapshot]:
        pending = getattr(self, "_pending_operator_review_snapshot", None)
        if pending is not None and pending.outcome is CompletionOutcome.OPERATOR_REVIEW:
            return pending
        completion = self._warning_state_presenter().state.completion
        if completion is not None and completion.outcome is CompletionOutcome.OPERATOR_REVIEW:
            return completion
        return None

    def _active_blocking_completion_snapshot(self) -> Optional[CompletionOutcomeSnapshot]:
        """Return the durable completion result that still owns this tray."""

        pending = getattr(self, "_pending_operator_review_snapshot", None)
        if pending is not None and pending.blocks_completion:
            return pending
        completion = self._warning_state_presenter().state.completion
        if completion is not None and completion.blocks_completion:
            return completion
        return None

    def _operator_review_state_payload(self) -> Optional[Dict[str, Any]]:
        # Keep the historic JSON key for backward compatibility.  It now also
        # persists retryable completion states, because a restart must not
        # release a tray whose transfer or local completion record is unsettled.
        snapshot = self._active_blocking_completion_snapshot()
        if snapshot is None:
            return None
        tray = self.current_tray
        return {
            "schema_version": OPERATOR_REVIEW_STATE_SCHEMA_VERSION,
            "outcome": snapshot.outcome.value,
            "item_name": str(tray.item_name or ""),
            "master_label": str(tray.master_label_code or ""),
            "scan_count": len(tray.scanned_barcodes),
            "target_count": int(tray.tray_size),
            "message": str(snapshot.message or "담당자 확인이 필요한 서버 판정입니다."),
            "receipt_id": str(snapshot.receipt_id or ""),
            "error_code": str(snapshot.error_code or ""),
        }

    @staticmethod
    def _completion_event_contract_from_state(
        state: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        payload = state.get(COMPLETION_EVENT_STATE_KEY)
        if payload is None:
            return None
        return {
            **({"worker_record": dict(payload["worker_record"])} if "worker_record" in payload else {}),
            "schema_version": int(payload["schema_version"]),
            "event_type": str(payload["event_type"]),
            "idempotency_key": str(payload["idempotency_key"]),
            "observed_at": str(payload["observed_at"]),
            "projection_log_name": str(payload["projection_log_name"]),
            "projection_worker_name": str(payload["projection_worker_name"]),
            "transfer_intent_id": str(payload["transfer_intent_id"]),
            "was_restored_session": bool(payload["was_restored_session"]),
            "log_may_have_been_attempted": bool(
                payload["log_may_have_been_attempted"]
            ),
            "transfer_detail": dict(payload["transfer_detail"]),
        }

    def _active_completion_event_contract(self) -> Optional[Dict[str, Any]]:
        payload = getattr(self, "_pending_completion_event_contract", None)
        return dict(payload) if isinstance(payload, Mapping) else None

    def _operator_review_snapshot_from_state(
        self,
        state: Dict[str, Any],
    ) -> Optional[CompletionOutcomeSnapshot]:
        payload = state.get(OPERATOR_REVIEW_STATE_KEY)
        if payload is None:
            return None
        outcome = CompletionOutcome(str(payload["outcome"]))
        return CompletionOutcomeSnapshot(
            outcome=outcome,
            item_name=str(payload["item_name"]),
            master_label=str(payload["master_label"]),
            scan_count=int(payload["scan_count"]),
            target_count=int(payload["target_count"]),
            message=str(payload["message"]),
            receipt_id=str(payload["receipt_id"]),
            error_code=str(payload["error_code"]),
        )

    def _restore_operator_review_from_state(self, state: Dict[str, Any]) -> bool:
        completion_event = self._completion_event_contract_from_state(state)
        self._pending_completion_event_contract = completion_event
        snapshot = self._operator_review_snapshot_from_state(state)
        presenter = self._warning_state_presenter()
        if snapshot is None and completion_event is not None:
            transfer_detail = completion_event.get("transfer_detail") or {}
            log_was_attempted = bool(
                completion_event.get("log_may_have_been_attempted")
            )
            snapshot = CompletionOutcomeSnapshot(
                outcome=(
                    CompletionOutcome.LOCAL_EVENT_RETRY
                    if log_was_attempted
                    else CompletionOutcome.RETRY_WAIT
                ),
                item_name=str(self.current_tray.item_name or ""),
                master_label=str(self.current_tray.master_label_code or ""),
                scan_count=len(self.current_tray.scanned_barcodes),
                target_count=max(
                    len(self.current_tray.scanned_barcodes),
                    int(self.current_tray.tray_size or 0),
                ),
                message=(
                    "완료 기록 저장 도중 프로그램이 종료되었습니다. "
                    "트레이를 잠근 채 동일 완료 기록을 재확인해야 합니다."
                    if log_was_attempted
                    else "이적 요청 준비 뒤 프로그램이 종료되었습니다. "
                    "트레이를 잠근 채 동일 이적 요청을 서버에서 재확인해야 합니다."
                ),
                receipt_id=str(transfer_detail.get("transfer_seal_receipt_id") or ""),
                error_code=(
                    "TRAY_COMPLETE_EVENT_RECOVERY_REQUIRED"
                    if log_was_attempted
                    else "TRAY_COMPLETE_TRANSFER_RECOVERY_REQUIRED"
                ),
            )
        if snapshot is None:
            self._pending_operator_review_snapshot = None
            self._pending_completion_event_contract = None
            presenter.clear_completion()
            return False
        self._pending_operator_review_snapshot = snapshot
        presenter.present_completion(snapshot)
        if snapshot.outcome is CompletionOutcome.OPERATOR_REVIEW:
            self._start_warning_beep()
        else:
            self._stop_warning_beep()
        return True

    def _current_tray_state_snapshot(self) -> Dict[str, Any]:
        state = tray_session_to_state(self.current_tray, worker_name=self._record_worker_name())
        activation_event = self._active_activation_event_contract()
        if activation_event is not None:
            state[ACTIVATION_EVENT_STATE_KEY] = activation_event
        parked_restore = self._active_parked_restore_contract()
        if parked_restore is not None:
            state[PARKED_RESTORE_STATE_KEY] = parked_restore
        completion_event = self._active_completion_event_contract()
        if completion_event is not None:
            state[COMPLETION_EVENT_STATE_KEY] = completion_event
        operator_review = self._operator_review_state_payload()
        if operator_review is not None:
            state[OPERATOR_REVIEW_STATE_KEY] = operator_review
        last_activity_time = getattr(self, "last_activity_time", None)
        if getattr(self, "is_idle", False) and last_activity_time:
            idle_duration = max(0.0, (datetime.datetime.now() - last_activity_time).total_seconds())
            state["total_idle_seconds"] = float(state.get("total_idle_seconds") or 0.0) + idle_duration
        return state

    def _load_current_tray_state(self, *, _recovery_choice="pending"):
        if _recovery_choice != "pending":
            self._inline_scan_choices = []
        state_path = os.path.join(self.save_folder, self.CURRENT_TRAY_STATE_FILE)
        if not os.path.exists(state_path): return
        try:
            state_read = read_recovery_file(Path(state_path), "current", tray_size=self.TRAY_SIZE)
            if not state_read.verified:
                raise TrayStateValidationError(state_read.reason)
            saved_state = state_read.value
            if saved_state.get('audit_reset_committed'):
                self._flush_pending_event_logs()
                return
            saved_master_label = str(saved_state.get('master_label_code') or '')
            if saved_master_label and self._paired_preflight_blocks_label(saved_master_label):
                original_bytes = state_read.raw
                quarantined_path = self._quarantine_current_tray_state(
                    "paired handoff label cannot resume"
                )
                try:
                    preserved = bool(
                        quarantined_path
                        and read_recovery_file(Path(quarantined_path), "stale",
                                               tray_size=self.TRAY_SIZE).raw == original_bytes
                    )
                except OSError:
                    preserved = False
                self._paired_stale_current_blocked = not preserved
                if not preserved:
                    self._paired_stale_current_path = state_path
                    self._paired_stale_current_original_hash = hashlib.sha256(original_bytes).hexdigest()
                    self._paired_stale_current_original_bytes = original_bytes
                    try:
                        fallback = preserve_stale_bytes(Path(state_path), original_bytes)
                    except Exception:
                        fallback = None
                    self._paired_stale_current_preserved_path = str(fallback or quarantined_path or "")
                    self._set_preflight_scan_input_locked(True)
                self._show_field_notice(
                    "이전 작업 복구 차단",
                    (
                        "이 현품표는 짝 인계 보류 중입니다. 원래 상태를 별도로 보존했습니다. "
                        "관리자 인계 목록에서 확인하세요."
                    ) if preserved else (
                        "이 현품표는 짝 인계 보류 중입니다. 상태 파일 보존을 확인하지 "
                        "못해 새 작업을 시작하지 않습니다. 운영 작업에서 관리자 재확인, "
                        "보존 다시 시도, 보류 후 다른 현품표 계속을 선택하세요."
                    ),
                )
                return
            saved_worker_raw = str(saved_state.get('worker_name') or '').strip()
            saved_worker_safe = persistent_operator_name(saved_worker_raw)
            if saved_worker_safe != saved_worker_raw:
                saved_state['worker_name'] = saved_worker_safe
                if not self._save_tray_state_snapshot(saved_state):
                    self._show_field_notice(
                        "이전 작업 확인 필요",
                        "이전 작업자 정보를 안전하게 변환하지 못했습니다. 관리자에게 문의하세요.",
                    )
                    return
            if not self._reconcile_activation_event_from_state(saved_state):
                self.current_tray = TraySession()
                self.worker_name = ""
                self._show_field_notice(
                    "현품표 시작 기록 복구 실패",
                    "저장된 현품표 시작 감사 기록을 복구하지 못했습니다. "
                    "상태와 감사 outbox를 보존했으니 관리자에게 문의하세요.",
                )
                return
            if not self._reconcile_parked_restore_from_state(saved_state):
                self.current_tray = TraySession()
                self.worker_name = ""
                self._show_field_notice(
                    "보류 작업 복구 기록 대기",
                    "저장된 보류 작업 복구 기록을 투영하거나 source를 정리하지 "
                    "못했습니다. 상태와 감사 outbox를 보존했으니 관리자에게 "
                    "문의하세요.",
                )
                return
        except Exception as e:
            print(f"현재 트레이 상태 로드 실패: {e}")
            quarantined_path = self._quarantine_current_tray_state(str(e))
            self.current_tray = TraySession()
            if quarantined_path:
                print(f"현재 트레이 상태 격리 위치: {quarantined_path}")
            self._show_field_notice(
                "이전 작업 확인 필요",
                "이전 작업 상태를 불러오지 못해 안전하게 분리했습니다. "
                "관리자에게 문의하세요.",
            )
            return

        try:
            saved_worker = persistent_operator_name(saved_state.get('worker_name'))
            current_worker_persistent = persistent_operator_name(self.worker_name)
            saved_master_label = saved_state.get('master_label_code')
            saved_operator_review = self._operator_review_snapshot_from_state(saved_state)
            saved_completion_event = self._completion_event_contract_from_state(
                saved_state
            )
            if saved_master_label and self._is_completed_tray_state(saved_state):
                self.current_tray = TraySession()
                if not self._delete_current_tray_state():
                    quarantined_path = self._quarantine_current_tray_state("completed tray state delete failed")
                    self._log_event(
                        'TRAY_STATE_DELETE_FAILED_AFTER_COMPLETION_RESTORE',
                        detail={
                            'master_label_code': saved_master_label,
                            'quarantined_path': quarantined_path,
                        },
                    )
                    path_notice = f"\n격리 파일: {quarantined_path}" if quarantined_path else ""
                    self._show_field_notice("작업 상태 정리 실패", f"이미 완료된 이전 작업 상태 파일을 삭제하지 못했습니다.{path_notice}")
                    return
                if not self._log_event(
                    'TRAY_STATE_DISCARDED_AFTER_COMPLETION',
                    detail={'master_label_code': saved_master_label},
                    synchronous=True,
                ):
                    restore_ok = self._save_tray_state_snapshot(saved_state)
                    if restore_ok:
                        self._show_field_notice("작업 기록 실패", "완료된 이전 작업 상태 정리 기록을 남기지 못해 상태 파일을 보존합니다.")
                    else:
                        self._show_field_notice("작업 기록 실패", "완료된 이전 작업 상태 정리 기록을 남기지 못했고 상태 파일 복원에도 실패했습니다. 상태 폴더를 확인하세요.")
                    return
                return
            if self._owns_worker_record(saved_state):
                msg = (
                    "이전에 마치지 못한 트레이 작업을 이어서 시작하시겠습니까?\n\n"
                    f"· 품목: {saved_state.get('item_name', '알 수 없음')}\n"
                    f"· 스캔 수: {len(saved_state.get('scanned_barcodes', []))}개\n\n"
                    "예: 계속 작업 / 아니오: 보류하고 새 작업 / 취소: 로그인 화면"
                )
                restore_required = (
                    saved_operator_review is not None
                    or saved_completion_event is not None
                )
                if not restore_required and _recovery_choice == "pending":
                    self._request_inline_choice("이전 작업 복구", msg, [
                        ("이어서 작업", lambda: self._load_current_tray_state(_recovery_choice=True)),
                        ("보류하고 새 작업", lambda: self._load_current_tray_state(_recovery_choice=False)),
                        ("로그인 화면", lambda: self._load_current_tray_state(_recovery_choice=None)),
                    ], on_scan=lambda: self._defer_scan_recovery_state(
                        saved_state, reason="scanner_continues_after_recovery_choice"))
                    return
                recovery_choice = True if restore_required else _recovery_choice
                if recovery_choice is None:
                    self.current_tray = TraySession()
                    self.worker_name = ""
                    self.worker_role = ""
                    self._authenticated_protected_admin = False
                    return
                if recovery_choice is True:
                    restore_detail = {
                        'message': 'Same worker restored their session.',
                    }
                    if restore_required:
                        restore_detail['operator_review_restored'] = True
                    if not self._log_event(
                        'TRAY_RESTORE',
                        detail=restore_detail,
                        synchronous=True,
                    ):
                        self.current_tray = TraySession()
                        self._show_field_notice("작업 기록 실패", "이전 작업 복구 기록을 남기지 못해 상태 파일을 보존합니다.")
                        return
                    self._restore_tray_from_state(saved_state)
                else:
                    if not self._defer_saved_recovery_state(saved_state):
                        self._show_field_notice(
                            "작업 보류 실패",
                            "이전 작업을 보류 상태로 안전하게 옮기지 못했습니다. "
                            "현재 상태를 보존했으니 다시 복구하거나 관리자에게 문의하세요.",
                        )
                        return
                    if hasattr(self, "_update_parked_trays_list"):
                        self._update_parked_trays_list()
                    if hasattr(self, "show_status_message"):
                        self.show_status_message(
                            "이전 작업을 보류했습니다. 보류 목록에서 다시 복구할 수 있습니다.",
                            self.COLOR_PRIMARY,
                        )
            else:
                saved_worker_display = display_operator_name(saved_worker)
                msg = f"이전 작업자 '{saved_worker_display}'님이 마치지 않은 작업이 있습니다.\n\n이 작업을 이어서 진행하시겠습니까?"
                if _recovery_choice == "pending":
                    self._request_inline_choice("작업 인수 확인", msg, [
                        ("이어서 작업", lambda: self._load_current_tray_state(_recovery_choice=True)),
                        ("원본 보존", lambda: self._load_current_tray_state(_recovery_choice=None)),
                    ], on_scan=lambda: self._defer_scan_recovery_state(
                        saved_state, reason="scanner_continues_after_takeover_choice"))
                    return
                response = _recovery_choice
                if response is True:
                    previous_operator_review = getattr(
                        self,
                        "_pending_operator_review_snapshot",
                        None,
                    )
                    previous_completion_event = getattr(
                        self,
                        "_pending_completion_event_contract",
                        None,
                    )
                    self.current_tray = tray_session_from_state(
                        saved_state,
                        session_factory=TraySession,
                        default_tray_size=self.TRAY_SIZE,
                    )
                    self._pending_operator_review_snapshot = saved_operator_review
                    self._pending_completion_event_contract = saved_completion_event
                    if not self._save_current_tray_state():
                        self._pending_operator_review_snapshot = previous_operator_review
                        self._pending_completion_event_contract = (
                            previous_completion_event
                        )
                        self.current_tray = TraySession()
                        self._show_field_notice("작업 저장 경고", "인수한 작업 상태의 작업자 정보를 저장하지 못해 작업을 복구하지 않습니다.")
                        return
                    takeover_detail = {
                        'previous_worker': saved_worker,
                        'new_worker': current_worker_persistent,
                        'item_name': saved_state.get('item_name'),
                    }
                    try:
                        takeover_logged = bool(
                            self._log_event(
                                'TRAY_TAKEOVER',
                                detail=takeover_detail,
                                synchronous=True,
                            )
                        )
                    except Exception as exc:
                        print(f"작업 인수 기록 실패: {exc}")
                        takeover_logged = False
                    if not takeover_logged:
                        try:
                            rollback_ok = self._save_tray_state_snapshot(saved_state)
                        except Exception as exc:
                            print(f"작업 인수 상태 롤백 실패: {exc}")
                            rollback_ok = False
                        self._pending_operator_review_snapshot = previous_operator_review
                        self._pending_completion_event_contract = (
                            previous_completion_event
                        )
                        self.current_tray = TraySession()
                        if rollback_ok:
                            self._show_field_notice("작업 기록 실패", "작업 인수 기록을 남기지 못해 이전 작업 상태를 보존합니다.")
                        else:
                            self._show_field_notice("작업 기록 실패", "작업 인수 기록을 남기지 못했고 이전 작업 상태 복원에도 실패했습니다. 상태 파일을 확인하세요.")
                        return
                    self._restore_operator_review_from_state(saved_state)
                    self._invalidate_pending_scan_callbacks()
                    self.show_status_message("이전 트레이 작업을 복구했습니다.", self.COLOR_PRIMARY)
                elif response is False:
                    if (
                        saved_operator_review is not None
                        or saved_completion_event is not None
                    ):
                        self._show_field_notice(
                            "삭제 불가",
                            "담당자 확인이 필요한 트레이는 삭제할 수 없습니다. "
                            "담당자 확인 후 기존 작업자가 다시 로그인해 주세요.",
                        )
                        self.worker_name = ""
                        self.current_tray = TraySession()
                        self.show_worker_input_screen()
                        return
                    if messagebox.askyesno("작업 삭제", "이전 작업을 영구적으로 삭제하시겠습니까?\n(이 작업은 복구할 수 없습니다.)"):
                        if not self._log_saved_tray_discarded(
                            saved_state,
                            reason='restore_takeover_declined_delete_confirmed',
                            discarded_worker_name=str(saved_worker or ""),
                        ):
                            self._show_field_notice("작업 기록 실패", "이전 작업 삭제 기록을 남기지 못해 상태 파일을 보존합니다.")
                            return
                        if not self._delete_current_tray_state():
                            self._show_field_notice("작업 삭제 실패", "현재 트레이 상태 파일을 삭제하지 못했습니다.")
                            return
                        self.current_tray = TraySession()
                        self._request_operation_lease_release(
                            str(saved_state.get("operation_lease_id") or "")
                        )
                        self.show_status_message(f"'{saved_worker_display}'님의 이전 작업이 삭제되었습니다.", self.COLOR_DANGER)
                    else:
                        self.worker_name = ""
                        self.current_tray = TraySession()
                        self.show_worker_input_screen()
                else:
                    self.worker_name = ""
                    self.current_tray = TraySession()
                    self.show_worker_input_screen()
        except Exception as e:
            print(f"현재 트레이 상태 로드 실패: {e}")
            self._show_field_notice(
                "이전 작업 확인 필요",
                "이전 작업 상태를 불러오지 못했습니다. 관리자에게 문의하세요.",
            )

    def _restore_tray_from_state(self, state: Dict[str, Any], *, preserve_held_scans: bool = False):
        self.current_tray = tray_session_from_state(
            state,
            session_factory=TraySession,
            default_tray_size=self.TRAY_SIZE,
        )
        restored_operator_review = self._restore_operator_review_from_state(state)
        if preserve_held_scans:
            # An exchange updates this same work round while its durable lane
            # is still running; invalidating that generation aborts its audit.
            self._scans_behind_save_work = (
                int(getattr(self, "_scan_callback_epoch", 0)), self.current_tray)
        else:
            self._invalidate_pending_scan_callbacks()
        if not restored_operator_review:
            self.show_status_message("이전 트레이 작업을 복구했습니다.", self.COLOR_PRIMARY)

    def _quarantine_current_tray_state(self, reason: str, *,
                                       approval: Optional[Mapping[str, str]] = None,
                                       expected_sha256: str = "") -> Optional[str]:
        state_path = os.path.join(self.save_folder, self.CURRENT_TRAY_STATE_FILE)
        if not os.path.exists(state_path):
            return None
        try:
            options = ({"expected_sha256": expected_sha256,
                        "move": lambda original, held, digest: self._admin_pin_move(
                            approval, original, held, digest)}
                       if approval and expected_sha256 else {})
            quarantined_path = quarantine_tray_state_file(state_path, **options)
            print(f"임시 트레이 상태 파일 격리: {quarantined_path} ({reason})")
            return str(quarantined_path)
        except Exception as e:
            print(f"임시 트레이 상태 파일 격리 실패: {e}")
            return None

    @_recovery_item_firewall
    def _recheck_paired_stale_current(self) -> bool:
        approval = self._authorize_blocked_work_supervisor()
        if approval is None or not self._blocked_work_identity_matches(approval):
            return False
        source = Path(str(getattr(self, "_paired_stale_current_path", "") or ""))
        preserved_name = str(getattr(self, "_paired_stale_current_preserved_path", "") or "")
        preserved = Path(preserved_name) if preserved_name else None
        expected = str(getattr(self, "_paired_stale_current_original_hash", "") or "")
        source_status = "원 위치에 남음" if source.is_file() else "원 위치에서 이동됨"
        source_read = read_recovery_file(source, "stale", tray_size=getattr(self, "TRAY_SIZE", 60))
        changed = bool(source_read.sha256 and source_read.sha256 != expected)
        preserved_status = "보존 확인 전"
        if preserved is not None and preserved.is_file():
            try:
                preserved_status = (
                    "원본 SHA256 일치" if read_recovery_file(preserved, "stale", tray_size=getattr(self, "TRAY_SIZE", 60)).sha256 == expected
                    else "원본 SHA256 불일치 · 잠금 유지"
                )
            except OSError:
                preserved_status = "보존 파일 읽기 실패 · 잠금 유지"
        messagebox.showinfo(
            "현재 현품표 보존 재확인",
            f"현재 상태 파일: {source_status}\n보존 사본: {preserved_status}\n"
            f"보존 시점 뒤 내용: {'SHA256 변경 · 두 바이트 모두 보존 필요' if changed else '변경 확인 안 됨'}\n"
            "보존을 다시 시도한 뒤 보류 후 다른 현품표 계속을 누르세요. "
            "원 현품표는 관리자 인계 목록에서 계속 막힙니다.",
            parent=getattr(self, "root", None),
        )
        return True

    def _preserve_paired_stale_current(self, approval: Mapping[str, str]) -> bool:
        if not getattr(self, "_paired_stale_current_blocked", False):
            return True
        if not self._blocked_work_identity_matches(approval):
            return False
        source = Path(str(getattr(self, "_paired_stale_current_path", "") or ""))
        expected = str(getattr(self, "_paired_stale_current_original_hash", "") or "")
        preserved_name = str(getattr(self, "_paired_stale_current_preserved_path", "") or "")
        try:
            if source.is_file():
                current_read = read_recovery_file(source, "stale", tray_size=self.TRAY_SIZE)
                if current_read.raw is None:
                    raise OSError("stale current cannot be read")
                changed_hash = current_read.sha256
                original_copy = read_recovery_file(Path(preserved_name), "stale", tray_size=self.TRAY_SIZE) if preserved_name else None
                if original_copy is None or original_copy.sha256 != expected:
                    original_bytes = getattr(self, "_paired_stale_current_original_bytes", None)
                    if original_bytes is None or hashlib.sha256(original_bytes).hexdigest() != expected:
                        if changed_hash != expected:
                            raise OSError("original stale bytes are unavailable")
                    else:
                        preserved_name = str(preserve_stale_bytes(source, original_bytes))
                        self._paired_stale_current_preserved_path = preserved_name
                if current_read.verified:
                    self._paired_stale_current_changed_label = str(current_read.value.get("master_label_code") or "")
                if changed_hash != expected:
                    preserve_stale_bytes(source, current_read.raw)
                try:
                    audited = self._blocked_work_identity_is_current(approval) and bool(
                        self._log_event(
                            "PHS2_PAIRED_STALE_CURRENT_PRESERVATION_REQUESTED",
                            detail={
                                "source_file": source.name,
                                "original_sha256": expected,
                                "current_sha256": changed_hash,
                                **self._blocked_work_audit_identity(approval),
                            },
                            synchronous=True,
                            idempotency_key=(
                                f"paired-stale-preservation:{expected}:{changed_hash}:"
                                f"{uuid.uuid4().hex}"
                            ),
                            deduplicate=True,
                        )
                    )
                except Exception:
                    audited = False
                if not audited:
                    raise OSError("stale current preservation audit failed")
                pinned = self._admin_pin_store().read(approval["operation_key"])["source_snapshot"]
                pinned_sha = str(pinned.get("current_sha256") or pinned.get("current_observed_sha256") or "")
                moved = str(self._quarantine_current_tray_state(
                    "paired stale current retry", approval=approval,
                    expected_sha256=pinned_sha) or "")
                moved_read = read_recovery_file(Path(moved), "stale", tray_size=self.TRAY_SIZE) if moved else None
                if moved_read is None or moved_read.sha256 != changed_hash:
                    raise OSError("changed stale current readback differs")
                self._paired_stale_current_changed_path = moved
                if changed_hash == expected and not preserved_name:
                    preserved_name = moved
                    self._paired_stale_current_preserved_path = moved
            preserved = Path(preserved_name) if preserved_name else None
            if source.exists() or preserved is None or not preserved.is_file():
                raise OSError("stale current remains in active slot")
            if read_recovery_file(preserved, "stale", tray_size=self.TRAY_SIZE).sha256 != expected:
                raise OSError("stale current preservation readback differs")
        except (OSError, UnicodeDecodeError, ValueError, TrayStateValidationError):
            messagebox.showerror(
                "현재 현품표 보존 대기",
                "원본 보존을 확인하지 못했습니다. 같은 현품표와 새 작업을 계속 막습니다. "
                "저장 공간과 파일 접근을 확인한 뒤 보존을 다시 시도하세요.",
                parent=getattr(self, "root", None),
            )
            return False
        return True

    @_recovery_item_firewall
    def _retry_paired_stale_current_preservation(self) -> bool:
        expected = str(getattr(self, "_paired_stale_current_original_hash", "") or "")

        def source():
            current = Path(self._paired_stale_current_path)
            read = read_recovery_file(current, "stale", tray_size=self.TRAY_SIZE)
            preserved_name = str(getattr(self, "_paired_stale_current_preserved_path", "") or "")
            return {"original_sha256": expected, "current_sha256": read.sha256,
                    "source_file": current.name,
                    "preserved_file": Path(preserved_name).name if preserved_name else ""}

        def effect(_intent):
            preserved = Path(str(getattr(self, "_paired_stale_current_preserved_path", "") or ""))
            return bool(preserved.is_file() and not Path(self._paired_stale_current_path).exists()
                        and read_recovery_file(preserved, "stale", tray_size=self.TRAY_SIZE).sha256 == expected)

        approval = self._admin_pin_approval_for(
            "CA.PAIR_RETRY", expected, source, (), effect)
        if approval is None or not self._preserve_paired_stale_current(approval):
            return False
        if not self._admin_pin_complete(approval, effect):
            return False
        messagebox.showinfo(
            "현재 현품표 보존 확인",
            "원본을 별도로 보존했습니다. 운영 작업에서 '보류 후 다른 현품표 계속'을 "
            "선택하면 다른 현품표를 시작할 수 있습니다.",
            parent=getattr(self, "root", None),
        )
        return True

    @_recovery_item_firewall
    def _continue_after_paired_stale_current(self) -> bool:
        expected = str(getattr(self, "_paired_stale_current_original_hash", "") or "")

        def source():
            original = Path(self._paired_stale_current_path)
            preserved = Path(str(getattr(self, "_paired_stale_current_preserved_path", "") or ""))
            first = preserved if preserved.is_file() else original
            return {"original_sha256": expected,
                    "source_file": original.name,
                    "original_observed_sha256": read_recovery_file(first, "stale").sha256,
                    "current_observed_sha256": read_recovery_file(original, "stale").sha256}

        def effect(_intent):
            marker = self._paired_preflight_store().directory / f"stale-current-{expected}.json"
            result = read_recovery_file(marker, "stale_hold")
            return bool(result.verified and result.value["original_sha256"] == expected)

        approval = self._admin_pin_approval_for("CA.TRAY_HOLD", expected, source, (), effect)
        if approval is None or not self._preserve_paired_stale_current(approval):
            return False
        if not self._blocked_work_identity_matches(approval):
            return False
        source = Path(self._paired_stale_current_path)
        preserved = Path(self._paired_stale_current_preserved_path)
        detail = {
            "reason": "paired_stale_current_preserved",
            "source_file": source.name,
            "preserved_file": preserved.name,
            "original_sha256": self._paired_stale_current_original_hash,
            "changed_file": Path(str(getattr(self, "_paired_stale_current_changed_path", "") or "")).name,
            **self._blocked_work_audit_identity(approval),
        }
        try:
            audited = bool(self._log_event(
                "PHS2_PAIRED_STALE_CURRENT_DEFERRED", detail=detail,
                synchronous=True,
                idempotency_key=(
                    f"paired-stale-current:{self._paired_stale_current_original_hash}:"
                    f"{uuid.uuid4().hex}"
                ),
                deduplicate=True,
            ))
        except Exception:
            audited = False
        if not audited:
            messagebox.showerror(
                "현재 현품표 보류 기록 대기",
                "원본 사본은 보존했지만 관리자 보류 기록을 남기지 못했습니다. "
                "기록 상태를 확인하고 같은 보류 동작을 다시 시도하세요.",
                parent=getattr(self, "root", None),
            )
            return False
        if not self._blocked_work_identity_matches(approval):
            return False
        try:
            changed = Path(str(getattr(self, "_paired_stale_current_changed_path", "") or ""))
            self._paired_preflight_store().hold_stale_current(
                preserved, changed if changed.is_file() else preserved,
            )
        except Exception:
            messagebox.showerror(
                "현재 현품표 보류 기록 대기",
                "두 사본의 현품표 보류를 저장하지 못했습니다. 다른 작업은 계속 대기합니다.",
                parent=getattr(self, "root", None),
            )
            return False
        self._paired_stale_current_blocked = False
        if not self._admin_pin_complete(approval, effect):
            return False
        self._set_preflight_scan_input_locked(False)
        self._update_action_button_states()
        self.show_status_message(
            "원 현품표는 관리자 보류 상태입니다. 다른 현품표 작업을 계속하세요.",
            self.COLOR_PRIMARY, duration=0,
        )
        return True

    def _log_current_tray_discarded(self, *, reason: str, synchronous: bool = False) -> bool:
        if not self.current_tray.master_label_code:
            return False
        return self._log_event(
            'TRAY_DISCARDED_BY_OPERATOR',
            detail={
                'reason': reason,
                'master_label_code': self.current_tray.master_label_code,
                'item_code': self.current_tray.item_code,
                'item_name': self.current_tray.item_name,
                'scan_count': len(self.current_tray.scanned_barcodes),
                'is_partial_submission': self.current_tray.is_partial_submission,
            },
            synchronous=synchronous,
        )

    def _log_saved_tray_discarded(
        self,
        saved_state: Dict[str, Any],
        *,
        reason: str,
        discarded_worker_name: str,
    ) -> bool:
        return self._log_event(
            'TRAY_DISCARDED_BY_OPERATOR',
            detail={
                'reason': reason,
                'master_label_code': saved_state.get('master_label_code'),
                'item_code': saved_state.get('item_code'),
                'item_name': saved_state.get('item_name'),
                'scan_count': len(saved_state.get('scanned_barcodes') or []),
                'discarded_worker_name': discarded_worker_name,
            },
            synchronous=True,
        )

    @writer_sink("gui_tray_state_delete")
    def _delete_current_tray_state(self) -> bool:
        state_path = os.path.join(self.save_folder, self.CURRENT_TRAY_STATE_FILE)
        if os.path.exists(state_path):
            try:
                os.remove(state_path)
            except Exception as e:
                print(f"임시 트레이 상태 파일 삭제 실패: {e}")
                return False
        return True

    def show_validation_screen(self):
        self._clear_main_frames()
        self.paned_window.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        for pane in [self.left_pane, self.center_pane, self.right_pane]:
            for widget in pane.winfo_children(): widget.destroy()
        self._create_left_sidebar_content(self._large_text_pane(self.left_pane))
        self._create_center_content(self._large_text_pane(self.center_pane))
        self._create_right_sidebar_content(self._large_text_pane(self.right_pane))
        self.root.after(50, self._set_initial_sash_positions)
        self._start_clock()
        self._start_idle_checker()
        self._update_all_summaries()
        self._update_parked_trays_list()
        if self.current_tray.master_label_code:
            self._reconcile_pending_local_member_exchanges()
            self._update_current_item_label()
            self.scanned_listbox.delete(0, tk.END)
            for i, barcode in enumerate(self.current_tray.scanned_barcodes, start=1):
                self.scanned_listbox.insert(0, self._format_scanned_list_row(i, barcode))
            if self.current_tray.scanned_barcodes:
                self.undo_button['state'] = tk.NORMAL
            self._sync_last_normal_scan_from_active_tray()
            self._update_center_display()
            self._start_stopwatch(resume=True)
            self.root.after_idle(self._update_tray_image_display)
        else:
            self._reset_ui_to_waiting_state()
        self.scan_entry.focus()
        self.root.after(100, self._schedule_phs_label_exchange_recovery)

    def show_logistics_progress(self):
        if getattr(self, "_scan_callback_pending", False) or self.scan_entry.get().strip():
            return
        if getattr(self, "_progress_visible", False):
            self._schedule_focus_return()
            return
        panel = ttk.Frame(self.root, padding=16)
        panel.grid_columnconfigure(0, weight=1)
        panel.grid_rowconfigure(2, weight=1)
        ttk.Label(panel, text="출고 계획 대비 진행 현황 · 이적", style='Card.Value.TLabel').grid(
            row=0, column=0, sticky='w')
        ttk.Button(panel, text="작업 화면", command=self._hide_logistics_progress,
                   style='Secondary.TButton').grid(row=0, column=1, padx=8)
        self._progress_status_label = ttk.Label(panel, style='Card.Subtle.TLabel')
        self._progress_status_label.grid(row=1, column=0, columnspan=2, sticky='w', pady=8)
        table = ttk.Frame(panel)
        table.grid(row=2, column=0, columnspan=2, sticky='nsew')
        table.grid_columnconfigure(0, weight=1)
        table.grid_rowconfigure(0, weight=1)
        self._progress_tree = ttk.Treeview(table, columns=('name','plan','done','remaining','boxes'),
            show='headings', takefocus=False)
        for column, title in zip(('name','plan','done','remaining','boxes'),
                ('품목','출고 계획','이적 준비','남은 수량','남은 상자')):
            self._progress_tree.heading(column, text=title)
            self._progress_tree.column(column, width=240 if column == 'name' else 120, minwidth=80)
        scroll = ttk.Scrollbar(table, orient='vertical', command=self._progress_tree.yview)
        self._progress_tree.configure(yscrollcommand=scroll.set)
        self._progress_tree.grid(row=0, column=0, sticky='nsew')
        scroll.grid(row=0, column=1, sticky='ns')
        self._progress_tree.bind('<ButtonRelease-1>', lambda _event: self._schedule_focus_return())
        ttk.Label(panel, text="스캔하면 작업 화면으로 돌아가 그대로 처리합니다.").grid(
            row=3, column=0, columnspan=2, pady=8)
        self._progress_work_scan_entry = self.scan_entry
        self.scan_entry = tk.Entry(panel, font=(self.DEFAULT_FONT, int(18*self.scale_factor)), justify='center')
        self.scan_entry.grid(row=4, column=0, columnspan=2, sticky='ew')
        self.scan_entry.bind('<Return>', self.process_barcode)
        self._progress_panel = panel
        self._progress_visible = True
        panel.place(x=0, y=0, relwidth=1, relheight=1)
        self._render_logistics_progress()
        self._refresh_logistics_progress()
        self._schedule_focus_return()

    def _hide_logistics_progress(self, raw_barcode=""):
        if not getattr(self, "_progress_visible", False):
            return
        self._progress_visible = False
        panel = getattr(self, "_progress_panel", None)
        if panel is not None:
            panel.place_forget()
            if hasattr(panel, 'destroy'):
                panel.destroy()
            self._progress_panel = None
        entry = getattr(self, "_progress_work_scan_entry", None)
        if entry is not None:
            self.scan_entry = entry
            self._progress_work_scan_entry = None
            if raw_barcode:
                entry.delete(0, tk.END)
                entry.insert(0, raw_barcode)
        job = getattr(self, "_progress_refresh_job", None)
        if job:
            self.root.after_cancel(job)
            self._progress_refresh_job = None
        self._schedule_focus_return()

    def _refresh_logistics_progress(self):
        self._progress_refresh_job = None
        if not getattr(self, "_progress_visible", False) or getattr(self, "_ui_close_requested", False):
            return
        if getattr(self, "_progress_pending", False):
            return
        self._progress_pending = True
        results = self._progress_results = queue.Queue(maxsize=1)
        worker = persistent_operator_name(self.worker_name)
        client = getattr(getattr(self, "transfer_seal_coordinator", None), "client", None)
        today = datetime.date.today().isoformat()
        def read():
            try:
                data = client.get_progress(date=today) if client is not None else None
            except Exception:
                data = None
            results.put((data, worker))
        thread = threading.Thread(target=read, name='container-audit-progress', daemon=True)
        self._progress_thread = thread
        thread.start()
        self._poll_logistics_progress_result()

    def _poll_logistics_progress_result(self):
        self._progress_poll_job = None
        try:
            data, worker = self._progress_results.get_nowait()
        except queue.Empty:
            self._progress_poll_job = self.root.after(50, self._poll_logistics_progress_result)
            return
        self._progress_pending = False
        if worker == persistent_operator_name(self.worker_name):
            self._progress_disconnected = data is None
            if data is not None:
                self._progress_data = data
                self._progress_last_success = datetime.datetime.now().strftime('%m-%d %H:%M:%S')
            if getattr(self, "_progress_visible", False):
                self._render_logistics_progress()
        if getattr(self, "_progress_visible", False) and not getattr(self, "_ui_close_requested", False):
            self._progress_refresh_job = self.root.after(60000, self._refresh_logistics_progress)

    def _render_logistics_progress(self):
        data = getattr(self, "_progress_data", None) or {}
        status = "연결 끊김" if getattr(self, "_progress_disconnected", False) else "서버 연결: 정상" if data else "현황 확인 중"
        self._progress_status_label.configure(text=f"{data.get('date', datetime.date.today().isoformat())} · {status} · 마지막 성공 수신 {getattr(self, '_progress_last_success', '없음')}")
        tree = self._progress_tree
        for row in tree.get_children():
            tree.delete(row)
        for item in data.get('items', []):
            tree.insert('', 'end', values=(item.get('name') or item.get('item_id'), item['plan_qty'],
                item['transferred_qty'], item['remaining_qty'], item['remaining_boxes']))

    def _large_text_pane(self, parent, *, force=False):
        # The existing 2x+ tier deliberately keeps enlarged text. Give its
        # overflowing content a viewport instead of reducing that preference.
        if not force and getattr(self, "scale_factor", 1.0) < 2.0:
            return parent
        pane_style = parent.cget('style')
        viewport = ttk.Frame(parent, style=pane_style)
        viewport.pack(fill=tk.BOTH, expand=True)
        background = self.COLOR_SIDEBAR_BG if pane_style == 'Sidebar.TFrame' else self.COLOR_BG
        canvas = tk.Canvas(viewport, highlightthickness=0, background=background)
        scrollbar = ttk.Scrollbar(viewport, orient='vertical', command=canvas.yview)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        canvas.configure(yscrollcommand=scrollbar.set)
        content = ttk.Frame(canvas, style=pane_style)
        content._layout_viewport = canvas
        window = canvas.create_window(0, 0, window=content, anchor='nw')
        pending = None
        pending_focus = None
        event_root = parent.winfo_toplevel()

        def resize():
            nonlocal pending
            pending = None
            width = max(1, canvas.winfo_width())
            height = max(canvas.winfo_height(), content.winfo_reqheight())
            canvas.itemconfigure(window, width=width, height=height)
            canvas.configure(scrollregion=(0, 0, width, height))

        def belongs(widget):
            return widget is canvas or str(widget).startswith(str(content) + '.') or widget is content

        def schedule(event):
            nonlocal pending
            if belongs(event.widget) and pending is None:
                pending = self.root.after_idle(resize)

        def reveal(widget):
            nonlocal pending_focus
            pending_focus = None
            if not belongs(widget) or widget is canvas:
                return
            try:
                top = widget.winfo_rooty() - content.winfo_rooty()
                bottom = top + widget.winfo_height()
            except tk.TclError:
                return  # A focused child can be removed while this pane survives.
            visible_top = canvas.canvasy(0)
            height = canvas.winfo_height()
            if top < visible_top or bottom > visible_top + height:
                target = top if top < visible_top else bottom - height
                canvas.yview_moveto(max(0, target) / max(1, content.winfo_height()))

        def schedule_reveal(event):
            nonlocal pending_focus
            if belongs(event.widget):
                if pending_focus is not None:
                    self.root.after_cancel(pending_focus)
                pending_focus = self.root.after_idle(reveal, event.widget)

        def wheel(event):
            if (not belongs(event.widget) or not event.delta or event.state & 4
                    or event.widget.winfo_class() in {'Listbox', 'TSpinbox'}):
                return
            if event.widget.winfo_class() == 'Treeview':
                if not force:
                    return
                first, last = event.widget.yview()
                if (event.delta > 0 and first > 0) or (event.delta < 0 and last < 1):
                    return
            canvas.yview_scroll(-3 if event.delta > 0 else 3, 'units')
            return 'break'

        def page(event):
            if force and belongs(event.widget):
                canvas.yview_scroll(-1 if event.keysym == 'Prior' else 1, 'pages')
                return 'break'

        bindings = [
            (sequence, event_root.bind(sequence, callback, add='+'))
            for sequence, callback in (
                ('<Configure>', schedule), ('<FocusIn>', schedule_reveal), ('<MouseWheel>', wheel),
                ('<Prior>', page), ('<Next>', page),
            )
        ]

        def dispose(event):
            if event.widget is content:
                if pending is not None:
                    self.root.after_cancel(pending)
                if pending_focus is not None:
                    self.root.after_cancel(pending_focus)
                for sequence, binding in bindings:
                    event_root.unbind(sequence, binding)

        content.bind('<Destroy>', dispose, add='+')
        content._reveal_widget = reveal
        pending = self.root.after_idle(resize)
        return content

    @staticmethod
    def _pane_viewport_height(frame):
        return getattr(frame, '_layout_viewport', frame).winfo_height()

    def _get_pane_layout_metrics(self, total_width: int) -> Dict[str, int]:
        total_height = 768
        for widget in (getattr(self, "paned_window", None), getattr(self, "root", None)):
            try:
                candidate = int(widget.winfo_height())
            except (AttributeError, TypeError, ValueError, tk.TclError):
                continue
            if candidate > 1:
                total_height = candidate
                break
        metrics = calculate_pane_layout_metrics(
            total_width,
            total_height,
            getattr(self, "scale_factor", 1.0),
        )
        return {
            "profile": metrics.profile,
            "left_width": metrics.left_width,
            "center_width": metrics.center_width,
            "right_width": metrics.right_width,
            "left_min": metrics.left_min,
            "center_min": metrics.center_min,
            "right_min": metrics.right_min,
            "compressed": metrics.compressed,
        }

    def _set_initial_sash_positions(self):
        self.paned_window.update_idletasks()
        try:
            total_width = self.paned_window.winfo_width()
            if total_width <= 1:
                self.root.after(50, self._set_initial_sash_positions)
                return
            metrics = self._get_pane_layout_metrics(total_width)
            sash_0_pos = metrics["left_width"]
            sash_1_pos = metrics["left_width"] + metrics["center_width"]
            self.paned_window.sashpos(0, sash_0_pos)
            self.paned_window.sashpos(1, sash_1_pos)
            self._paned_layout_signature = (
                total_width,
                metrics["profile"],
                sash_0_pos,
                sash_1_pos,
            )
        except tk.TclError as e:
            print(f"Could not set initial sash position (ignorable): {e}")

    def _clamp_paned_sashes_to_width(self, event=None):
        if not (hasattr(self, 'paned_window') and self.paned_window.winfo_ismapped()):
            return
        try:
            total_width = self.paned_window.winfo_width()
            if total_width <= 1:
                return
            metrics = self._get_pane_layout_metrics(total_width)
            left_min = metrics["left_min"]
            center_min = metrics["center_min"]
            right_min = metrics["right_min"]
            desired_sash_0 = metrics["left_width"]
            desired_sash_1 = metrics["left_width"] + metrics["center_width"]
            layout_signature = (
                total_width,
                metrics["profile"],
                desired_sash_0,
                desired_sash_1,
            )
            layout_changed = layout_signature != getattr(self, "_paned_layout_signature", None)
            if metrics["compressed"] or layout_changed:
                # Reapply the pure profile widths whenever the actual content
                # size/scale changes. This makes compact -> wide -> compact
                # deterministic and keeps the calculated center allocation in
                # compressed large-text layouts instead of replacing it with
                # the legacy 28/72 percentages.
                sash_0_pos = desired_sash_0
                sash_1_pos = desired_sash_1
            else:
                sash_0_pos = self.paned_window.sashpos(0)
                sash_1_pos = self.paned_window.sashpos(1)
                max_sash_0 = max(1, total_width - right_min - center_min)
                sash_0_pos = max(left_min, min(sash_0_pos, max_sash_0))
                min_sash_1 = sash_0_pos + center_min
                max_sash_1 = max(min_sash_1 + 1, total_width - right_min)
                sash_1_pos = max(min_sash_1, min(sash_1_pos, max_sash_1))
            self._paned_layout_signature = layout_signature
            if self.paned_window.sashpos(0) != sash_0_pos:
                self.paned_window.sashpos(0, sash_0_pos)
            if self.paned_window.sashpos(1) != sash_1_pos:
                self.paned_window.sashpos(1, sash_1_pos)
        except tk.TclError:
            return

    def _bind_label_to_container_width(
        self,
        label: ttk.Label,
        container: ttk.Widget,
        *,
        padding: int = 0,
        min_wraplength: int = 80,
    ) -> None:
        def update_wraplength(event=None):
            try:
                width = container.winfo_width()
                if width <= 1:
                    return
                label.configure(wraplength=max(min_wraplength, width - padding))
            except tk.TclError:
                return

        container.bind("<Configure>", update_wraplength, add="+")
        self.root.after(0, update_wraplength)

    def _schedule_notice_message_wrap_refresh(self, event=None, *, generation=None) -> None:
        current_generation = getattr(self, "_center_widget_generation", 0)
        if generation is not None and generation != current_generation:
            return
        label = getattr(self, "notice_message_label", None)
        if label is None:
            return
        event_widget = getattr(event, "widget", None)
        if event_widget is not None and event_widget is not label:
            return
        if getattr(self, "_notice_message_wrap_job", None):
            return
        root = getattr(self, "root", None)
        if root is None:
            self._apply_notice_message_wraplength(current_generation)
            return
        try:
            self._notice_message_wrap_job = root.after_idle(
                self._apply_notice_message_wraplength,
                current_generation,
            )
        except AttributeError:
            try:
                self._notice_message_wrap_job = root.after(
                    0,
                    self._apply_notice_message_wraplength,
                    current_generation,
                )
            except AttributeError:
                self._apply_notice_message_wraplength(current_generation)
        except tk.TclError:
            return

    def _apply_notice_message_wraplength(self, generation=None) -> None:
        self._notice_message_wrap_job = None
        current_generation = getattr(self, "_center_widget_generation", 0)
        if generation is not None and generation != current_generation:
            return
        generation = current_generation
        label = getattr(self, "notice_message_label", None)
        if label is None:
            return
        try:
            if hasattr(label, "winfo_exists") and not label.winfo_exists():
                return
            label_width = int(label.winfo_width())
        except (AttributeError, TypeError, ValueError, tk.TclError):
            return
        if label_width <= 1:
            return
        # The label's own allocation is the only reliable width after the
        # title and acknowledgement columns take their state-dependent space.
        # Keep a border/glyph gutter so requested width never exceeds the live
        # column viewport.  Tk's requested label width can be a few pixels
        # wider than wraplength across Windows DPI/font-rendering variants, so
        # four pixels was not sufficient on the GitHub Windows runner.
        wraplength = max(80, label_width - 8)
        metrics_key = (generation, label_width, wraplength)
        if metrics_key == getattr(self, "_notice_message_wrap_metrics", None):
            return
        try:
            label.configure(wraplength=wraplength)
            self._notice_message_wrap_metrics = metrics_key
        except (AttributeError, tk.TclError):
            return

    @staticmethod
    def _clamped_int(value: float, minimum: int, maximum: int) -> int:
        return max(minimum, min(maximum, int(round(value))))

    def _center_vertical_scale(self, center_height: int) -> float:
        scale = max(0.7, min(2.5, float(getattr(self, "scale_factor", 1.0) or 1.0)))
        if scale >= 1.2 and center_height / scale < 620:
            return min(scale, 1.2)
        return scale

    def _get_scanned_listbox_metrics(
        self,
        center_width: int,
        center_height: int,
        list_height: int = 0,
    ) -> Dict[str, int]:
        metrics = calculate_scanned_list_metrics(
            center_width,
            center_height,
            list_height,
            getattr(self, "scale_factor", 1.0),
        )
        return {
            "font_size": metrics.font_size,
            "header_font_size": metrics.header_font_size,
            "horizontal_pad": metrics.horizontal_pad,
            "top_pady": metrics.top_pady,
            "header_bottom_pady": metrics.header_bottom_pady,
            "visible_rows": metrics.visible_rows,
        }

    def _schedule_scanned_listbox_layout_refresh(self, event=None, *, generation=None) -> None:
        current_generation = getattr(self, "_center_widget_generation", 0)
        if generation is not None and generation != current_generation:
            return
        if getattr(self, "_scanned_listbox_layout_job", None):
            return
        root = getattr(self, "root", None)
        if root is None:
            self._apply_scanned_listbox_layout()
            return
        try:
            self._scanned_listbox_layout_job = root.after_idle(
                self._apply_scanned_listbox_layout,
                current_generation,
            )
        except AttributeError:
            try:
                self._scanned_listbox_layout_job = root.after(
                    0,
                    self._apply_scanned_listbox_layout,
                    current_generation,
                )
            except AttributeError:
                self._apply_scanned_listbox_layout(current_generation)
        except tk.TclError:
            return

    def _apply_scanned_listbox_layout(self, generation=None) -> None:
        self._scanned_listbox_layout_job = None
        current_generation = getattr(self, "_center_widget_generation", 0)
        if generation is not None and generation != current_generation:
            return
        generation = current_generation
        listbox = getattr(self, "scanned_listbox", None)
        if listbox is None:
            return
        try:
            if hasattr(listbox, "winfo_exists") and not listbox.winfo_exists():
                return
            parent_frame = getattr(self, "_scanned_listbox_parent_frame", None) or getattr(listbox, "master", None)
            if parent_frame is None:
                return
            center_width = parent_frame.winfo_width()
            center_height = self._pane_viewport_height(parent_frame)
            list_height = listbox.winfo_height()
        except (tk.TclError, AttributeError, TypeError):
            return
        if center_width <= 1 or center_height <= 1:
            return

        self._apply_center_layout(
            parent_frame,
            center_width,
            center_height,
            generation=generation,
        )
        metrics = self._get_scanned_listbox_metrics(center_width, center_height, list_height)
        metrics_key = (
            generation,
            metrics["font_size"],
            metrics["header_font_size"],
            metrics["horizontal_pad"],
            metrics["top_pady"],
            metrics["header_bottom_pady"],
            metrics["visible_rows"],
        )
        if metrics_key == getattr(self, "_scanned_listbox_layout_metrics", None):
            return

        try:
            listbox.configure(
                font=(self.DEFAULT_FONT, metrics["font_size"]),
                height=metrics["visible_rows"],
                justify='center',
            )
            listbox.grid_configure(
                padx=metrics["horizontal_pad"],
                pady=(0, 0),
            )
            header = getattr(self, "scanned_list_header_label", None)
            if header is not None:
                header.configure(
                    font=(self.DEFAULT_FONT, metrics["header_font_size"], 'bold')
                )
                header.grid_configure(
                    padx=metrics["horizontal_pad"],
                    pady=(metrics["top_pady"], metrics["header_bottom_pady"]),
                )
            scrollbar = getattr(self, "scanned_list_scrollbar", None)
            if scrollbar is not None:
                scrollbar.grid_configure(padx=(0, metrics["horizontal_pad"]))
            self._scanned_listbox_layout_metrics = metrics_key
        except (tk.TclError, AttributeError):
            return

    def _format_scanned_list_row(self, position: int, raw_barcode: str) -> str:
        """Return a compact display row while retaining the raw tray value."""

        tray = getattr(self, "current_tray", None)
        item_code = getattr(tray, "item_code", "") if tray is not None else ""
        return format_scan_list_row(position, raw_barcode, item_code=item_code)

    def _format_last_normal_scan_value(self, raw_barcode: str) -> str:
        """Compact the visible value while the presenter retains its raw scan."""

        if not raw_barcode:
            return "-"
        tray = getattr(self, "current_tray", None)
        active_item_code = getattr(tray, "item_code", "") if tray is not None else ""
        item_code = active_item_code or getattr(self, "_last_normal_scan_display_item_code", "")
        return compact_scan_value(raw_barcode, item_code=item_code)

    def _get_center_layout_metrics(self, center_width: int, center_height: int) -> Dict[str, int]:
        metrics = calculate_center_layout_metrics(
            center_width,
            center_height,
            getattr(self, "scale_factor", 1.0),
        )
        return {
            "profile": metrics.profile,
            "horizontal_pad": metrics.horizontal_pad,
            "item_top": metrics.item_top,
            "item_bottom": metrics.item_bottom,
            "count_top": metrics.count_top,
            "count_bottom": metrics.count_bottom,
            "progress_bottom": metrics.progress_bottom,
            "entry_ipady": metrics.entry_ipady,
            "warning_band_height": metrics.warning_band_height,
            "button_top": metrics.button_top,
            "button_pad_x": metrics.button_pad_x,
            "list_minsize": metrics.list_minsize,
            "entry_font": metrics.entry_font,
            "count_font": metrics.count_font,
            "notice_title_font": metrics.notice_title_font,
            "notice_message_font": metrics.notice_message_font,
            "action_columns": metrics.action_columns,
        }

    def _apply_center_layout(
        self,
        parent_frame=None,
        center_width: int = 0,
        center_height: int = 0,
        *,
        generation=None,
    ) -> None:
        parent_frame = parent_frame or getattr(self, "_center_content_frame", None)
        if parent_frame is None:
            return
        current_generation = getattr(self, "_center_widget_generation", 0)
        if generation is not None and generation != current_generation:
            return
        generation = current_generation
        try:
            center_width = center_width or parent_frame.winfo_width()
            center_height = center_height or self._pane_viewport_height(parent_frame)
        except (tk.TclError, AttributeError):
            return
        if center_width <= 1 or center_height <= 1:
            return
        metrics = self._get_center_layout_metrics(center_width, center_height)
        self._layout_center_action_buttons(center_width, metrics["button_pad_x"])
        # Action wording changes at 960 px even when all geometry metrics stay
        # identical.  Include that derived state so a slow sash drag cannot
        # leave compact/full labels cached on the wrong side of the boundary.
        compact_action_labels = 1 < int(center_width) < 960
        scale = max(0.7, min(2.5, float(getattr(self, "scale_factor", 1.0) or 1.0)))
        compact_notice_message = scale >= 1.2 and center_height / scale < 620
        metrics_key = (
            generation,
            compact_action_labels,
            compact_notice_message,
            *metrics.values(),
        )
        if metrics_key == getattr(self, "_center_layout_metrics", None):
            return
        try:
            parent_frame.grid_rowconfigure(4, weight=0, minsize=metrics["warning_band_height"])
            parent_frame.grid_rowconfigure(5, weight=3, minsize=metrics["list_minsize"])
            hero_frame = getattr(self, "_center_hero_frame", None)
            if hero_frame is not None:
                hero_frame.grid_configure(pady=(metrics["item_top"], metrics["item_bottom"]))
            if hasattr(self, "main_count_label"):
                self.main_count_label.configure(font=(self.DEFAULT_FONT, metrics["count_font"], 'bold'))
                self.main_count_label.grid_configure(pady=(metrics["count_top"], metrics["count_bottom"]))
            if hasattr(self, "main_progress_bar"):
                self.main_progress_bar.grid_configure(
                    pady=(0, metrics["progress_bottom"]),
                    padx=max(12, metrics["horizontal_pad"] - 8),
                )
            if hasattr(self, "scan_entry"):
                self.scan_entry.configure(font=(self.DEFAULT_FONT, metrics["entry_font"], 'bold'))
                self.scan_entry.grid_configure(ipady=metrics["entry_ipady"], padx=metrics["horizontal_pad"])
            if hasattr(self, "notice_frame"):
                self.notice_frame.grid_configure(padx=metrics["horizontal_pad"])
            if hasattr(self, "notice_title_label"):
                self.notice_title_label.configure(
                    font=(self.DEFAULT_FONT, metrics["notice_title_font"], 'bold')
                )
            if hasattr(self, "notice_message_label"):
                self.notice_message_label.configure(
                    font=(self.DEFAULT_FONT, metrics["notice_message_font"])
                )
                self.notice_message_label.grid_configure(
                    padx=4 if compact_notice_message else 8
                )
            button_frame = getattr(self, "_center_button_frame", None)
            if button_frame is not None:
                button_frame.grid_configure(pady=(metrics["button_top"], 0))
            self._center_layout_metrics = metrics_key
            self._apply_notice_visibility()
        except (tk.TclError, AttributeError):
            return

    def _layout_center_action_buttons(self, center_width: int = 0, pad_x: int = 8) -> None:
        button_frame = getattr(self, "_center_button_frame", None)
        buttons = getattr(self, "_center_action_buttons", [])
        if button_frame is None or not buttons:
            return
        try:
            if center_width <= 0:
                center_width = button_frame.winfo_width()
            center_frame = getattr(self, "_center_content_frame", None)
            center_height = self._pane_viewport_height(center_frame) if center_frame is not None else 1080
            vertical_scale = self._center_vertical_scale(center_height)
            self._refresh_action_button_labels(center_width)
            required_width = max(button.winfo_reqwidth() for button in buttons) + 2 * pad_x
            columns = max(1, min(len(buttons), (int(center_width) - 40) // max(1, required_width)))
            signature = (tuple(buttons), columns, pad_x, vertical_scale)
            if signature == getattr(self, '_center_action_layout_signature', None):
                return
            for index, button in enumerate(buttons):
                button.grid_forget()
                button.grid(
                    row=index // columns,
                    column=index % columns,
                    sticky='ew',
                    padx=pad_x,
                    pady=(0, max(4, int(6 * vertical_scale))),
                )
            for column in range(len(buttons)):
                button_frame.grid_columnconfigure(
                    column,
                    weight=1 if column < columns else 0,
                    uniform="center_actions" if column < columns else "",
                )
            self._center_action_layout_signature = signature
        except (tk.TclError, AttributeError):
            return

    def _configure_widget_options(self, widget, **kwargs) -> None:
        if widget is None:
            return
        try:
            widget.configure(**kwargs)
            return
        except AttributeError:
            pass
        except tk.TclError:
            return
        try:
            widget.config(**kwargs)
            return
        except AttributeError:
            pass
        except tk.TclError:
            return
        try:
            for key, value in kwargs.items():
                widget[key] = value
        except (TypeError, KeyError, tk.TclError):
            return

    def _widget_exists(self, widget) -> bool:
        if widget is None:
            return False
        try:
            return bool(widget.winfo_exists())
        except (AttributeError, tk.TclError):
            return True

    def _use_compact_action_labels(self) -> bool:
        frame = getattr(self, "_center_content_frame", None)
        if frame is None:
            return False
        try:
            width = int(frame.winfo_width())
        except (tk.TclError, AttributeError, TypeError, ValueError):
            return False
        return 1 < width < 960

    def _action_button_labels(
        self,
        *,
        compact: bool,
        operator_review: bool,
        precommand_retry: bool = False,
    ) -> Dict[str, str]:
        if compact:
            return {
                "undo": "스캔 취소",
                "park": "보류",
                "submit": (
                    "재시도"
                    if precommand_retry
                    else "조치"
                    if operator_review
                    else "제출"
                ),
                "operations": "운영 작업",
            }
        return {
            "undo": "스캔 취소",
            "park": "트레이 보류",
            "submit": (
                "사전검증 재시도"
                if precommand_retry
                else "운영 작업"
                if operator_review
                else "트레이 제출"
            ),
            "operations": "운영 작업 ▾",
        }

    def _refresh_action_button_labels(self, center_width: int) -> None:
        completion = self._warning_state_presenter().state.completion
        operator_review = bool(
            completion is not None and completion.outcome is CompletionOutcome.OPERATOR_REVIEW
        )
        precommand_retry = (
            self._precommand_operator_review_retry_context() is not None
        )
        labels = self._action_button_labels(
            compact=1 < int(center_width or 0) < 960,
            operator_review=operator_review,
            precommand_retry=precommand_retry,
        )
        for key, widget_name in (
            ("undo", "undo_button"),
            ("park", "park_button"),
            ("submit", "submit_tray_button"),
            ("operations", "operations_button"),
        ):
            self._configure_widget_options(getattr(self, widget_name, None), text=labels[key])

    def _update_action_button_states(self) -> None:
        active_tray = bool(getattr(getattr(self, "current_tray", None), "master_label_code", ""))
        scanned_count = len(getattr(getattr(self, "current_tray", None), "scanned_barcodes", []) or [])
        parked_undo = getattr(self, "_parked_tray_undo", None)
        waiting_undo = not active_tray and bool(
            getattr(self, "_short_confirmation_undo", None)
            or (parked_undo and parked_undo["worker"] == persistent_operator_name(self.worker_name))
        )
        blocking_completion = self._active_blocking_completion_snapshot()
        operator_review = blocking_completion is not None
        retryable_completion = bool(
            blocking_completion is not None
            and blocking_completion.operator_retryable
        )
        precommand_retry = (
            self._precommand_operator_review_retry_context() is not None
        )
        lane = getattr(self, "_ui_lane", None)
        transfer_lane_busy = bool(lane is not None and lane.is_busy())
        # Preserve the conservative exact-mode latch independently of menu widgets.
        self._exact_transfer_exchange_blocked()
        phs_transition_blocked = self._phs_label_exchange_transition_pending()
        compact_labels = self._use_compact_action_labels()
        labels = self._action_button_labels(
            compact=compact_labels,
            operator_review=operator_review,
            precommand_retry=precommand_retry,
        )
        if retryable_completion:
            if blocking_completion.outcome is CompletionOutcome.LOCAL_EVENT_RETRY:
                labels["submit"] = "완료 기록 재시도" if not compact_labels else "기록 재시도"
            else:
                labels["submit"] = "서버 재확인" if not compact_labels else "재확인"

        if bool(getattr(self, "_completion_lane_busy", False)):
            labels["submit"] = "완료 처리 중"
            for key, widget_name in (
                ("undo", "undo_button"),
                ("park", "park_button"),
                ("submit", "submit_tray_button"),
                ("operations", "operations_button"),
            ):
                self._configure_widget_options(
                    getattr(self, widget_name, None),
                    text=labels[key],
                    state=(tk.NORMAL if key == "operations" and self._admin_pin_has_pending()
                           else tk.DISABLED),
                )
            for widget_name in (
                "change_worker_button",
                "phs_label_exchange_button",
                "phs_label_legacy_fallback_button",
                "phs_label_candidate_load_button",
            ):
                self._configure_widget_options(
                    getattr(self, widget_name, None),
                    state=tk.DISABLED,
                )
            return

        preflight_context_locked = self._preflight_context_blocks_mutation()
        mutation_state = (
            tk.DISABLED
            if operator_review or phs_transition_blocked or preflight_context_locked
            else tk.NORMAL
        )
        self._configure_widget_options(
            getattr(self, "park_button", None),
            text=labels["park"],
            state=mutation_state if active_tray else tk.DISABLED,
        )
        self._configure_widget_options(
            getattr(self, "undo_button", None),
            text=labels["undo"],
            state=mutation_state if scanned_count or waiting_undo else tk.DISABLED,
        )
        self._configure_widget_options(
            getattr(self, "submit_tray_button", None),
            state=(
                tk.NORMAL
                if active_tray
                and scanned_count
                and not phs_transition_blocked
                and not preflight_context_locked
                and (not operator_review or retryable_completion or precommand_retry)
                else tk.DISABLED
            ),
            text=labels["submit"],
            style='Review.TButton' if operator_review else 'Success.TButton',
            command=(
                self._retry_precommand_operator_review_completion
                if precommand_retry
                else self.submit_current_tray
            ),
        )
        self._configure_widget_options(
            getattr(self, "operations_button", None),
            text=labels["operations"],
            state=(
                tk.DISABLED
                if not self._admin_pin_has_pending()
                and (phs_transition_blocked or transfer_lane_busy
                     or (operator_review and not active_tray and not preflight_context_locked))
                else tk.NORMAL
            ),
        )
        self._configure_widget_options(
            getattr(self, "change_worker_button", None),
            state=(
                tk.DISABLED
                if operator_review or phs_transition_blocked or preflight_context_locked
                else tk.NORMAL
            ),
        )

        single_available = self._phs_label_exchange_available_for_tray()
        reconciliation_available = (
            self._phs_reconciliation_exchange_available()
        )
        phs_available = single_available or reconciliation_available
        phs_busy = bool(
            getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_phs_label_candidate_pending", False)
            or getattr(self, "_phs_reconciliation_resolve_pending", False)
            or getattr(self, "_phs_label_refresh_pending", False)
        )
        self._configure_widget_options(
            getattr(self, "phs_label_exchange_button", None),
            text="현품표 교체",
            state=(
                tk.NORMAL
                if phs_available
                and not operator_review
                and not preflight_context_locked
                and not phs_busy
                else tk.DISABLED
            ),
        )
        self._configure_widget_options(
            getattr(self, "phs_label_legacy_fallback_button", None),
            state=(
                tk.NORMAL
                if single_available
                and reconciliation_available
                and not operator_review
                and not preflight_context_locked
                and not phs_busy
                and not phs_transition_blocked
                else tk.DISABLED
            ),
        )
        self._configure_widget_options(
            getattr(self, "phs_label_candidate_load_button", None),
            state=(
                tk.NORMAL
                if phs_available
                and not operator_review
                and not preflight_context_locked
                and not phs_busy
                else tk.DISABLED
            ),
        )
        candidate_selected = bool(
            str(
                getattr(
                    getattr(self, "phs_label_candidate_var", None),
                    "get",
                    lambda: "",
                )()
                or ""
            ).strip()
        )
        recovery_pending = False
        coordinator = getattr(self, "phs_label_exchange_coordinator", None)
        if phs_available and coordinator is not None:
            try:
                recovery = coordinator.journal.load()
                recovery_pending = bool(
                    recovery
                    and str(recovery.get("status") or "").strip().upper()
                    not in {"COMMITTED", "CANCELLED"}
                    and (
                        str(recovery.get("workflow_kind") or "")
                        == "RECONCILIATION"
                        or (
                            single_available
                            and str(
                                recovery.get("canonical_input_tag_qr") or ""
                            ).strip()
                            == str(
                                getattr(
                                    self.current_tray,
                                    "master_label_code",
                                    "",
                                )
                                or ""
                            ).strip()
                        )
                    )
                )
            except Exception:
                recovery_pending = True
        self._phs_label_exchange_recovery_visible = recovery_pending
        self._configure_widget_options(
            getattr(self, "phs_label_exchange_execute_button", None),
            state=(
                tk.NORMAL
                if phs_available
                and not operator_review
                and not preflight_context_locked
                and not phs_busy
                and (
                    candidate_selected
                    or recovery_pending
                    or bool(
                        getattr(
                            self,
                            "_phs_reconciliation_context",
                            None,
                        )
                    )
                )
                else tk.DISABLED
            ),
        )
        self._refresh_phs_active_label_info()
        self._apply_notice_visibility()

    def _phs_reconciliation_exchange_available(self) -> bool:
        coordinator = getattr(self, "phs_label_exchange_coordinator", None)
        reconciliation = getattr(coordinator, "reconciliation", None)
        return bool(
            reconciliation is not None and reconciliation.available
        )

    @staticmethod
    def _phs_replacement_notice_pair(
        context: Optional[Mapping[str, Any]],
    ) -> Optional[tuple[str, str]]:
        scan = (
            context.get("scan")
            if isinstance(context, Mapping)
            and isinstance(context.get("scan"), Mapping)
            else {}
        )
        if scan.get("replacement_required") is not True:
            return None
        old_label_id = str(scan.get("scanned_label_id") or "").strip()
        new_label_id = str(scan.get("active_label_id") or "").strip()
        if not old_label_id or not new_label_id or old_label_id == new_label_id:
            return None
        return old_label_id, new_label_id

    def _phs_replacement_waiting_session_id(
        self,
        context: Optional[Mapping[str, Any]],
    ) -> str:
        scan = (
            context.get("scan")
            if isinstance(context, Mapping)
            and isinstance(context.get("scan"), Mapping)
            else {}
        )
        tray = getattr(self, "current_tray", None)
        payloads = (
            scan.get("active_qr_payload"),
            context.get("_scanned_payload")
            if isinstance(context, Mapping)
            else None,
            getattr(tray, "active_label_qr_payload", ""),
            getattr(tray, "canonical_input_tag_qr", ""),
            getattr(tray, "master_label_code", ""),
        )
        for payload in payloads:
            parsed = self._parse_new_format_qr(str(payload or "")) or {}
            try:
                fields = validate_compact_phs2_fields(parsed)
            except TransferSealError:
                continue
            session_id = str(fields["ITG"]).strip()
            if session_id:
                return session_id
        return ""

    @staticmethod
    def _phs_replacement_waiting_locations(
        context: Optional[Mapping[str, Any]],
    ) -> list[str]:
        locations: set[str] = set()
        if isinstance(context, Mapping):
            scan = (
                context.get("scan")
                if isinstance(context.get("scan"), Mapping)
                else {}
            )
            for value in (
                context.get("location_code"),
                context.get("current_location"),
                scan.get("location_code"),
                scan.get("current_location"),
            ):
                normalized = str(value or "").strip()
                if normalized:
                    locations.add(normalized)
            for action in list(context.get("actions") or []):
                if not isinstance(action, Mapping):
                    continue
                for member in list(action.get("process_membership") or []):
                    if not isinstance(member, Mapping):
                        continue
                    normalized = str(
                        member.get("location_code") or ""
                    ).strip()
                    if normalized:
                        locations.add(normalized)
        return sorted(locations or {"PHS_GOOD"})

    def _mark_phs_replacement_waiting(
        self,
        context: Optional[Mapping[str, Any]],
        pair: tuple[str, str],
        *,
        master_label: str = "",
        operator: Optional[str] = None,
        projection_log_file_path: Optional[str] = None,
    ) -> Dict[str, Any]:
        session_id = self._phs_replacement_waiting_session_id(context)
        if not session_id:
            raise ValueError("PHS replacement waiting session is unavailable")
        process_context = (
            str(context.get("process_context") or "transfer").strip()
            if isinstance(context, Mapping)
            else "transfer"
        )
        tray = getattr(self, "current_tray", None)
        normalized_projection_path = str(
            projection_log_file_path
            if projection_log_file_path is not None
            else getattr(self, "log_file_path", "")
            or ""
        ).strip()
        if not normalized_projection_path:
            raise OSError("replacement waiting event log is unavailable")
        row = self._transfer_seal_runtime().store.mark_phs_replacement_waiting(
            session_id=session_id,
            old_label_id=pair[0],
            new_label_id=pair[1],
            process_context=process_context,
            location_codes=self._phs_replacement_waiting_locations(context),
            operator=persistent_operator_name(
                operator
                if operator is not None
                else getattr(self, "worker_name", "")
            ),
            master_label=str(
                master_label
                or getattr(tray, "master_label_code", "")
                or ""
            ),
            projection_log_file_path=normalized_projection_path,
        )
        result = dict(row)
        self._project_phs_replacement_waiting_row(result)
        return result

    def _project_phs_replacement_waiting_row(
        self,
        row: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Idempotently project one SQLite marker to its append-only CSV log."""

        result = dict(row)
        try:
            event_detail = json.loads(
                str(
                    result.get("outbox_payload_json")
                    or result.get("evidence_json")
                    or ""
                )
            )
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise ValueError(
                "durable replacement waiting evidence is invalid"
            ) from exc
        if not isinstance(event_detail, dict):
            raise ValueError("durable replacement waiting evidence is invalid")
        event_type = str(event_detail.get("event_type") or "").strip()
        idempotency_key = str(
            event_detail.get("idempotency_key") or ""
        ).strip()
        projection_log_file_path = str(
            result.get("projection_log_file_path") or ""
        ).strip()
        if (
            event_type != "PHS_REPLACEMENT_WAITING_MARKED"
            or not idempotency_key
            or not projection_log_file_path
        ):
            raise ValueError("durable replacement waiting projection is incomplete")
        enriched_detail = self._plan_b_event_detail(event_type, event_detail)
        log_entry = {
            "timestamp": str(
                event_detail.get("observed_at")
                or datetime.datetime.now().isoformat()
            ),
            "worker_name": persistent_operator_name(
                event_detail.get("operator")
                or getattr(self, "worker_name", "")
                or ""
            ),
            "event": event_type,
            "details": json.dumps(
                sanitize_persistent_value(enriched_detail),
                ensure_ascii=False,
                allow_nan=False,
            ),
        }
        append_event_log_entry_idempotent(
            projection_log_file_path,
            log_entry,
            event_type=event_type,
            idempotency_key=idempotency_key,
            durable=True,
        )
        store = self._transfer_seal_runtime().store
        receipt = store.record_replacement_waiting_projection(
            str(result.get("intent_id") or ""),
            projection_log_file_path=projection_log_file_path,
        )
        self._trigger_session_direct_sync(event_type)
        result["projection_id"] = str(receipt["projection_id"])
        return result

    def _drain_phs_replacement_waiting_projections(self) -> int:
        store = self._transfer_seal_runtime().store
        pending = store.pending_replacement_waiting_projections()
        for row in pending:
            self._project_phs_replacement_waiting_row(dict(row))
        return len(pending)

    def _work_phs_replacement_waiting_marker(
        self,
        context: Optional[Mapping[str, Any]],
        *,
        master_label: str = "",
        operator: str = "",
        projection_log_file_path: str = "",
    ) -> Dict[str, Any]:
        """Persist one marker on the shared lane without touching Tk state."""

        pair = self._phs_replacement_notice_pair(context)
        if pair is None:
            return {
                "ready": True,
                "notice_key": None,
                "context": dict(context) if isinstance(context, Mapping) else None,
            }
        session_id = self._phs_replacement_waiting_session_id(context)
        notice_key = (session_id, pair[0], pair[1])
        try:
            self._mark_phs_replacement_waiting(
                context,
                pair,
                master_label=master_label,
                operator=operator,
                projection_log_file_path=projection_log_file_path,
            )
        except Exception as exc:
            return {
                "ready": False,
                "notice_key": notice_key,
                "context": dict(context) if isinstance(context, Mapping) else None,
                "pair": pair,
                "error": exc,
            }
        return {
            "ready": True,
            "notice_key": notice_key,
            "context": dict(context) if isinstance(context, Mapping) else None,
        }

    def _finish_phs_replacement_waiting_marker(
        self,
        outcome: Optional[Mapping[str, Any]],
    ) -> tuple[bool, bool]:
        """Publish a lane marker result and show any Tk-only failure notice."""

        if not isinstance(outcome, Mapping):
            return False, False
        if not bool(outcome.get("ready")):
            pair = outcome.get("pair")
            error = outcome.get("error")
            if (
                isinstance(pair, tuple)
                and len(pair) == 2
                and isinstance(error, Exception)
            ):
                self._log_phs_replacement_waiting_failure(
                    context=(
                        outcome.get("context")
                        if isinstance(outcome.get("context"), Mapping)
                        else None
                    ),
                    pair=(str(pair[0]), str(pair[1])),
                    error=error,
                )
            self._show_phs_replacement_waiting_storage_block()
            return False, False
        notice_key = outcome.get("notice_key")
        if notice_key is None:
            return True, False
        if not isinstance(notice_key, tuple) or len(notice_key) != 3:
            return False, False
        seen = getattr(self, "_phs_replacement_notice_pairs", None)
        if not isinstance(seen, set):
            seen = set()
            self._phs_replacement_notice_pairs = seen
        newly_marked = notice_key not in seen
        seen.add(notice_key)
        return True, newly_marked

    def _show_phs_replacement_waiting_storage_block(self) -> None:
        self.show_fullscreen_warning(
            "현품표 교체 대기 저장 실패",
            "현품표 교체 대기 기록을 안전하게 저장하지 못했습니다. "
            "현재 현품표 상태를 변경하지 않았습니다. 작업을 계속하지 말고 "
            "저장 장치 상태를 확인한 뒤 다시 시도하세요.",
            self.COLOR_DANGER,
        )

    def _ensure_phs_replacement_waiting_marked(
        self,
        context: Optional[Mapping[str, Any]],
        *,
        master_label: str = "",
    ) -> tuple[bool, bool]:
        """Return ``(ready, newly_marked)`` without mutating workflow state."""

        pair = self._phs_replacement_notice_pair(context)
        if pair is not None:
            notice_key = (
                self._phs_replacement_waiting_session_id(context),
                pair[0],
                pair[1],
            )
            seen = getattr(self, "_phs_replacement_notice_pairs", None)
            if isinstance(seen, set) and notice_key in seen:
                return True, False
        outcome = self._work_phs_replacement_waiting_marker(
            context,
            master_label=master_label,
            operator=str(getattr(self, "worker_name", "") or ""),
            projection_log_file_path=str(
                getattr(self, "log_file_path", "") or ""
            ),
        )
        return self._finish_phs_replacement_waiting_marker(outcome)

    def _show_phs_replacement_required_notice(self) -> None:
        self.show_status_message(
            PHS_REPLACEMENT_REQUIRED_NOTICE,
            self.COLOR_IDLE,
            duration=10000,
        )

    def _log_phs_replacement_waiting_failure(
        self,
        *,
        context: Optional[Mapping[str, Any]],
        pair: tuple[str, str],
        error: Exception,
    ) -> None:
        session_id = self._phs_replacement_waiting_session_id(context)
        detail = {
            "contract_version": (
                "container-audit-phs-replacement-waiting-v1"
            ),
            "event_type": "PHS_REPLACEMENT_WAITING_MARK_FAILED",
            "session_id": session_id or None,
            "old_label_hash": hashlib.sha256(
                pair[0].encode("utf-8")
            ).hexdigest(),
            "new_label_hash": hashlib.sha256(
                pair[1].encode("utf-8")
            ).hexdigest(),
            "process_context": (
                str(context.get("process_context") or "transfer").strip()
                if isinstance(context, Mapping)
                else "transfer"
            ),
            "location_codes": self._phs_replacement_waiting_locations(
                context
            ),
            "exception_type": error.__class__.__name__,
        }
        logger = getattr(self, "_log_event", None)
        logged = False
        if callable(logger):
            try:
                logged = bool(
                    logger(
                        "PHS_REPLACEMENT_WAITING_MARK_FAILED",
                        detail=detail,
                        synchronous=True,
                    )
                )
            except Exception:
                logged = False
        if not logged:
            print(
                "PHS replacement waiting evidence write failed: "
                f"{error.__class__.__name__}"
            )

    def _show_phs_replacement_required_notice_once(
        self,
        context: Optional[Mapping[str, Any]],
    ) -> bool:
        ready, newly_marked = self._ensure_phs_replacement_waiting_marked(
            context
        )
        if not ready or not newly_marked:
            return False
        self._show_phs_replacement_required_notice()
        return True

    def _capture_phs_reconciliation_progress(self) -> Dict[str, Any]:
        tray = self.current_tray
        scans_object = getattr(tray, "scanned_barcodes", None)
        return {
            "tray": tray,
            "master_label_code": str(
                getattr(tray, "master_label_code", "") or ""
            ),
            "scans_object": scans_object,
            "scans": (
                tuple(scans_object)
                if isinstance(scans_object, list)
                else None
            ),
            "tray_size": int(getattr(tray, "tray_size", 0) or 0),
            "resolve_pending": bool(
                getattr(self, "_phs_reconciliation_resolve_pending", False)
            ),
            "refresh_pending": bool(
                getattr(self, "_phs_label_refresh_pending", False)
            ),
            "preflight_pending": bool(
                getattr(self, "_master_preflight_pending", False)
            ),
            "hold_pending": bool(self._preflight_context_blocks_mutation()),
        }

    def _phs_reconciliation_progress_unchanged(
        self,
        captured: Optional[Mapping[str, Any]],
    ) -> bool:
        if not isinstance(captured, Mapping):
            return False
        current = self.current_tray
        scans_before = captured.get("scans")
        return bool(
            current is captured.get("tray")
            and str(getattr(current, "master_label_code", "") or "")
            == str(captured.get("master_label_code") or "")
            and getattr(current, "scanned_barcodes", None)
            is captured.get("scans_object")
            and int(getattr(current, "tray_size", 0) or 0)
            == int(captured.get("tray_size") or 0)
            and bool(
                getattr(self, "_phs_reconciliation_resolve_pending", False)
            )
            == bool(captured.get("resolve_pending"))
            and bool(getattr(self, "_phs_label_refresh_pending", False))
            == bool(captured.get("refresh_pending"))
            and bool(getattr(self, "_master_preflight_pending", False))
            == bool(captured.get("preflight_pending"))
            and bool(self._preflight_context_blocks_mutation())
            == bool(captured.get("hold_pending"))
            and (
                scans_before is None
                or tuple(getattr(current, "scanned_barcodes", []))
                == tuple(scans_before)
            )
        )

    def _apply_phs_label_exchange_snapshot(
        self,
        *,
        captured_tray: TraySession,
        captured_master_label: str,
        updated_tray: TraySession,
        force_persist: bool,
    ) -> bool:
        current = getattr(self, "current_tray", None)
        if (
            current is not captured_tray
            or str(getattr(current, "master_label_code", "") or "")
            != captured_master_label
        ):
            return False
        field_names = (
            "canonical_input_tag_qr",
            "active_label_qr_payload",
            "active_label_id",
            "active_label_business_date",
            "active_label_worker_code",
        )
        before = {
            field_name: getattr(current, field_name, "")
            for field_name in field_names
        }
        after = {
            field_name: getattr(updated_tray, field_name, "")
            for field_name in field_names
        }
        changed = before != after
        if changed:
            for field_name, value in after.items():
                setattr(current, field_name, value)
        if not changed and not force_persist:
            return True
        try:
            persisted = bool(self._save_current_tray_state())
        except Exception as exc:
            print(
                "현품표 교체 current state 저장 실패: "
                f"{exc.__class__.__name__}"
            )
            persisted = False
        if persisted:
            return True
        for field_name, value in before.items():
            setattr(current, field_name, value)
        return False

    def _phs_label_exchange_available_for_tray(self) -> bool:
        tray = getattr(self, "current_tray", None)
        if tray is None or not getattr(tray, "master_label_code", ""):
            return False
        fields = self._parse_new_format_qr(
            str(
                getattr(tray, "active_label_qr_payload", "")
                or tray.master_label_code
            )
        )
        coordinator = getattr(self, "phs_label_exchange_coordinator", None)
        return bool(
            isinstance(fields, dict)
            and str(fields.get("PHS") or "").strip() == "2"
            and str(fields.get("ITG") or "").strip()
            and str(fields.get("LBL") or "").strip()
            and str(fields.get("HSH") or "").strip()
            and coordinator is not None
            and coordinator.available
        )

    def _phs_label_exchange_transition_pending(self) -> bool:
        if (
            getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_phs_label_candidate_pending", False)
            or getattr(self, "_phs_reconciliation_resolve_pending", False)
            or getattr(self, "_phs_label_refresh_pending", False)
        ):
            return True
        coordinator = getattr(self, "phs_label_exchange_coordinator", None)
        if coordinator is None:
            return False
        try:
            recovery = coordinator.journal.load()
        except Exception:
            return True
        if (
            recovery
            and str(recovery.get("status") or "").strip().upper()
            not in {"COMMITTED", "CANCELLED"}
            and str(recovery.get("workflow_kind") or "")
            == "RECONCILIATION"
        ):
            return True
        tray = getattr(self, "current_tray", None)
        if tray is None or not getattr(tray, "master_label_code", ""):
            return False
        return bool(
            recovery
            and str(recovery.get("status") or "").strip().upper()
            not in {"COMMITTED", "CANCELLED"}
            and str(recovery.get("canonical_input_tag_qr") or "").strip()
            == str(tray.master_label_code or "").strip()
        )

    def _phs_label_exchange_blocks_tray_transition(self, action: str) -> bool:
        if not self._phs_label_exchange_transition_pending():
            return False
        self.show_status_message(
            "현품표 날짜 교환의 중앙 ACK/출력/활성화 복구가 끝날 때까지 "
            f"{action} 작업을 진행할 수 없습니다.",
            self.COLOR_DANGER,
            duration=8000,
        )
        self._schedule_focus_return()
        return True

    def _refresh_phs_active_label_info(self) -> None:
        label = getattr(self, "phs_active_label_info_label", None)
        if label is None:
            return
        tray = getattr(self, "current_tray", None)
        reconciliation = getattr(
            self, "_phs_reconciliation_context", None
        )
        if getattr(self, "_phs_label_exchange_recovery_visible", False):
            text = "미완료 현품표 교체 · F8로 복구"
        elif isinstance(reconciliation, Mapping):
            summaries = (
                self.phs_label_exchange_coordinator.reconciliation
                .target_summaries(reconciliation)
            )
            text = (
                f"서버 교체 지시 · {len(summaries)}장 · "
                + " / ".join(summaries[:3])
                + " · F8 실행"
            )
        elif (
            self._phs_reconciliation_exchange_available()
            and not getattr(
                self, "_phs_legacy_single_fallback_mode", False
            )
        ):
            text = "F8 → 현재/완료 이적 현품표 스캔 → F8 실행"
        elif not self._phs_label_exchange_available_for_tray():
            text = "현품표 교체 API 설정이 없습니다."
        else:
            business_date = str(
                getattr(tray, "active_label_business_date", "") or ""
            ).strip()
            worker_code = str(
                getattr(tray, "active_label_worker_code", "") or ""
            ).strip()
            details = " · ".join(
                value
                for value in (
                    business_date,
                    worker_code,
                    f"{int(getattr(tray, 'tray_size', 0) or 0)} Pcs",
                )
                if value
            )
            text = f"현재 사용 중 · {details}" if details else "현재 PHS2"
            text += " · 단축키 F8"
        try:
            label.configure(text=text)
        except (tk.TclError, AttributeError):
            pass

    def _on_phs_label_exchange_shortcut(self, _event=None):
        if self._warning_state_presenter().state.is_blocking:
            self._render_warning_state()
        elif self._reject_mutation_during_preflight_hold():
            pass
        elif any(getattr(self, name, False) for name in (
            "_phs_label_exchange_pending", "_phs_label_candidate_pending",
            "_phs_reconciliation_resolve_pending", "_phs_label_refresh_pending",
        )):
            self._schedule_focus_return()
        elif getattr(self, "_phs_reconciliation_context", None):
            self._execute_selected_phs_label_exchange()
        elif self._phs_label_exchange_transition_pending():
            self._execute_selected_phs_label_exchange()
        elif (
            self._phs_label_exchange_available_for_tray()
            or self._phs_reconciliation_exchange_available()
        ):
            self._toggle_phs_label_exchange_panel()
        else:
            self.show_status_message(
                "중앙 현품표 reconciliation 교체 API 설정이 없습니다.",
                self.COLOR_DANGER,
                duration=6000,
            )
            self._schedule_focus_return()
        return "break"

    def _set_phs_label_exchange_panel_mode(
        self, *, reconciliation_mode: bool
    ) -> None:
        """Keep central reconciliation separate from legacy manual SINGLE input."""

        self._phs_legacy_single_fallback_mode = not reconciliation_mode

        def set_visible(widget, visible: bool) -> None:
            if widget is None:
                return
            try:
                if visible:
                    widget.grid()
                elif hasattr(widget, "grid_remove"):
                    widget.grid_remove()
                else:
                    widget.grid_forget()
            except (tk.TclError, AttributeError):
                return

        set_visible(
            getattr(self, "phs_reconciliation_instruction_label", None),
            reconciliation_mode,
        )
        set_visible(
            getattr(self, "phs_label_legacy_single_controls_frame", None),
            not reconciliation_mode,
        )
        set_visible(
            getattr(self, "phs_label_candidate_combo", None),
            not reconciliation_mode,
        )
        set_visible(
            getattr(self, "phs_label_legacy_fallback_button", None),
            reconciliation_mode
            and self._phs_label_exchange_available_for_tray(),
        )

    def _show_phs_label_legacy_single_fallback(self, _event=None):
        """Expose the legacy SINGLE controls only as an explicit fallback."""

        busy = bool(
            getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_phs_label_candidate_pending", False)
            or getattr(self, "_phs_label_refresh_pending", False)
        )
        operator_review = self._active_blocking_completion_snapshot() is not None
        transition_pending = self._phs_label_exchange_transition_pending()
        if busy or operator_review or transition_pending:
            self.show_status_message(
                "진행 중인 현품표 교체 또는 복구를 먼저 완료하세요.",
                self.COLOR_DANGER,
                duration=6000,
            )
            self._schedule_focus_return()
            return "break"
        if not self._phs_label_exchange_available_for_tray():
            self.show_status_message(
                "현재 사용 중인 현품표에는 보조 날짜 교환을 사용할 수 없습니다.",
                self.COLOR_DANGER,
                duration=6000,
            )
            self._schedule_focus_return()
            return "break"
        panel = getattr(self, "phs_label_exchange_frame", None)
        try:
            if panel is not None:
                panel.grid()
                self._phs_label_exchange_panel_open = True
        except (tk.TclError, AttributeError):
            self.show_status_message(
                "보조 날짜 교환 화면을 열 수 없습니다.",
                self.COLOR_DANGER,
                duration=6000,
            )
            self._schedule_focus_return()
            return "break"
        self._phs_reconciliation_scan_armed = False
        self._phs_reconciliation_context = None
        self._phs_reconciliation_execution_guard = None
        self._set_phs_label_candidates([])
        self._configure_widget_options(
            getattr(self, "phs_label_exchange_execute_button", None),
            text="선택 교환 실행",
        )
        self._set_phs_label_exchange_panel_mode(reconciliation_mode=False)
        self._refresh_phs_active_label_info()
        self._update_action_button_states()
        self.show_status_message(
            "보조 기능입니다. 현재 사용 중인 현품표의 교환 작업일과 "
            "후보를 선택하세요.",
            self.COLOR_PRIMARY,
            duration=8000,
        )

        def focus_target_date() -> None:
            target = getattr(self, "phs_label_target_date_entry", None)
            try:
                if target is not None:
                    target.focus_set()
                    target.selection_range(0, tk.END)
            except (tk.TclError, AttributeError):
                self._schedule_focus_return()

        root = getattr(self, "root", None)
        try:
            if root is not None:
                root.after(0, focus_target_date)
            else:
                focus_target_date()
        except (tk.TclError, AttributeError):
            focus_target_date()
        return "break"

    def _toggle_phs_label_exchange_panel(self) -> None:
        panel = getattr(self, "phs_label_exchange_frame", None)
        if panel is None:
            return
        reconciliation_mode = self._phs_reconciliation_exchange_available()
        legacy_single_available = self._phs_label_exchange_available_for_tray()
        if not (legacy_single_available or reconciliation_mode):
            self.show_status_message(
                "중앙 현품표 교체 API 설정이 없습니다.",
                self.COLOR_DANGER,
                duration=6000,
            )
            self._schedule_focus_return()
            return
        self._set_phs_label_exchange_panel_mode(
            reconciliation_mode=reconciliation_mode
        )
        self._phs_label_exchange_panel_open = True
        try:
            if panel.winfo_ismapped():
                self._phs_reconciliation_scan_armed = reconciliation_mode
            else:
                panel.grid()
                self._phs_reconciliation_scan_armed = reconciliation_mode
                if reconciliation_mode:
                    self.show_status_message(
                        "현재 또는 완료된 이적 현품표를 스캔하면 서버가 적용할 "
                        "교체 지시를 조회합니다.",
                        self.COLOR_PRIMARY,
                        duration=8000,
                    )
                else:
                    self.show_status_message(
                        "현재 사용 중인 현품표의 교환 작업일과 후보를 선택하세요.",
                        self.COLOR_PRIMARY,
                        duration=8000,
                    )
        except (tk.TclError, AttributeError):
            return
        self._schedule_focus_return()

    def _close_phs_label_exchange_panel(self) -> None:
        if (
            self._warning_state_presenter().state.is_blocking
            or getattr(self, "_phs_reconciliation_context", None)
            or self._phs_label_exchange_transition_pending()
            or any(getattr(self, name, False) for name in (
                "_phs_label_exchange_pending", "_phs_label_candidate_pending",
                "_phs_reconciliation_resolve_pending", "_phs_label_refresh_pending",
            ))
        ):
            self.show_status_message(
                "진행 중인 현품표 교체 또는 복구를 먼저 완료하세요.",
                self.COLOR_DANGER,
            )
            return
        self._phs_reconciliation_scan_armed = False
        self._phs_label_exchange_panel_open = False
        self.phs_label_exchange_frame.grid_remove()
        self.show_status_message("현품표 교체 화면을 닫았습니다.", self.COLOR_PRIMARY)
        self._schedule_focus_return()

    def _set_phs_label_candidates(
        self, candidates: Sequence[Mapping[str, Any]]
    ) -> None:
        self._phs_label_candidates = [dict(value) for value in candidates]
        values = [
            (
                f"{value.get('business_date')} · "
                f"{value.get('worker_code')} · "
                f"{int(value.get('target_qty_pcs') or 0)} Pcs"
            )
            for value in self._phs_label_candidates
        ]
        combo = getattr(self, "phs_label_candidate_combo", None)
        variable = getattr(self, "phs_label_candidate_var", None)
        try:
            if combo is not None:
                combo.configure(values=values)
            if variable is not None:
                variable.set(values[0] if values else "")
        except (tk.TclError, AttributeError):
            pass

    def _load_phs_label_exchange_candidates(self) -> None:
        if (
            not self._phs_label_exchange_available_for_tray()
            or getattr(self, "_phs_label_candidate_pending", False)
            or getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_phs_label_refresh_pending", False)
        ):
            self._schedule_focus_return()
            return
        business_date = str(
            getattr(
                getattr(self, "phs_label_target_date_var", None),
                "get",
                lambda: "",
            )()
            or ""
        ).strip()
        self._phs_reconciliation_context = None
        tray = self.current_tray
        self._phs_label_candidate_pending = True
        self._set_phs_label_candidates([])
        self._update_action_button_states()
        self.show_status_message(
            "동일 품목·member-count의 중앙 PLANNED 작업지시를 조회합니다.",
            self.COLOR_PRIMARY,
            duration=0,
        )

        def worker() -> None:
            try:
                candidates = (
                    self.phs_label_exchange_coordinator.list_candidates(
                        tray, business_date
                    )
                )
                error = None
            except Exception as exc:
                candidates = []
                error = exc

            def finish() -> None:
                self._phs_label_candidate_pending = False
                if tray is not self.current_tray:
                    self._update_action_button_states()
                    self._schedule_focus_return()
                    return
                self._set_phs_label_candidates(candidates)
                if error is not None:
                    code = getattr(error, "code", "PHS_TARGET_LOOKUP_FAILED")
                    print(f"현품표 교환 대상 조회 실패: {code}: {error}")
                    self.show_status_message(
                        "교환 가능한 작업지시를 확인하지 못했습니다. "
                        "네트워크를 확인한 뒤 다시 시도하세요.",
                        self.COLOR_DANGER,
                        duration=8000,
                    )
                elif candidates:
                    self.show_status_message(
                        f"교환 가능한 중앙 작업지시 {len(candidates)}건을 "
                        "확인했습니다.",
                        self.COLOR_PRIMARY,
                        duration=6000,
                    )
                else:
                    self.show_status_message(
                        "해당 날짜에 동일 품목·member-count의 PLANNED 후보가 없습니다.",
                        self.COLOR_DANGER,
                        duration=8000,
                    )
                self._update_action_button_states()
                self._schedule_focus_return()

            try:
                self.root.after(0, finish)
            except (tk.TclError, AttributeError):
                self._phs_label_candidate_pending = False

        threading.Thread(
            target=worker,
            name="container-audit-phs-label-candidates",
            daemon=True,
        ).start()

    def _selected_phs_label_candidate(self) -> Optional[Dict[str, Any]]:
        variable = getattr(self, "phs_label_candidate_var", None)
        selected = str(
            getattr(variable, "get", lambda: "")() or ""
        ).strip()
        combo = getattr(self, "phs_label_candidate_combo", None)
        try:
            index = int(combo.current()) if combo is not None else -1
        except (tk.TclError, AttributeError, TypeError, ValueError):
            index = -1
        if 0 <= index < len(getattr(self, "_phs_label_candidates", [])):
            return dict(self._phs_label_candidates[index])
        for index_value, candidate in enumerate(
            getattr(self, "_phs_label_candidates", [])
        ):
            display = (
                f"{candidate.get('business_date')} · "
                f"{candidate.get('worker_code')} · "
                f"{int(candidate.get('target_qty_pcs') or 0)} Pcs"
            )
            if display == selected:
                return dict(candidate)
        return None

    def _set_phs_reconciliation_context(
        self,
        context: Optional[Mapping[str, Any]],
    ) -> None:
        self._phs_reconciliation_context = (
            dict(context) if isinstance(context, Mapping) else None
        )
        if context is None:
            self._phs_reconciliation_execution_guard = None
            self._set_phs_label_candidates([])
            self._configure_widget_options(
                getattr(self, "phs_label_exchange_execute_button", None),
                text="선택 교환 실행",
            )
            self._set_phs_label_exchange_panel_mode(
                reconciliation_mode=self._phs_reconciliation_exchange_available()
            )
            self._refresh_phs_active_label_info()
            self._update_action_button_states()
            return
        summaries = (
            self.phs_label_exchange_coordinator.reconciliation
            .target_summaries(context)
        )
        combo = getattr(self, "phs_label_candidate_combo", None)
        variable = getattr(self, "phs_label_candidate_var", None)
        try:
            if combo is not None:
                combo.configure(values=tuple(summaries))
            if variable is not None:
                variable.set(summaries[0] if summaries else "")
        except (tk.TclError, AttributeError):
            pass
        self._phs_label_candidates = []
        self._configure_widget_options(
            getattr(self, "phs_label_exchange_execute_button", None),
            text="서버 지시 교체 실행",
        )
        self._set_phs_label_exchange_panel_mode(reconciliation_mode=True)
        self._refresh_phs_active_label_info()
        self._update_action_button_states()

    def _intercept_phs_reconciliation_scan(
        self,
        raw_barcode: str,
    ) -> bool:
        if not getattr(self, "_phs_reconciliation_scan_armed", False):
            return False
        payload = normalize_master_label_input(raw_barcode)
        fields = self._parse_new_format_qr(payload)
        if not fields or str(fields.get("PHS") or "").strip() != "2":
            return False
        try:
            validate_compact_phs2_fields(fields)
        except TransferSealError:
            self.show_status_message(
                "현품표 정보를 읽지 못했습니다. 현품표를 확인한 뒤 다시 스캔하세요.",
                self.COLOR_DANGER,
                duration=8000,
            )
            self._schedule_focus_return()
            return True
        if self._reject_mutation_during_preflight_hold():
            return True
        # F8 arms exactly one reconciliation scan.  Leaving this armed after a
        # valid capture would steal later, ordinary PHS2 scans from the normal
        # transfer workflow.
        self._phs_reconciliation_scan_armed = False
        if (
            getattr(self, "_phs_label_candidate_pending", False)
            or getattr(self, "_phs_label_exchange_pending", False)
        ):
            self.show_status_message(
                "현품표 교체 조회 또는 실행이 이미 진행 중입니다.",
                self.COLOR_PRIMARY,
                duration=4000,
            )
            self._schedule_focus_return()
            return True
        reconciliation = getattr(
            getattr(self, "phs_label_exchange_coordinator", None),
            "reconciliation",
            None,
        )
        if reconciliation is None or not reconciliation.available:
            self.show_status_message(
                "중앙 현품표 교체 기능을 사용할 수 없습니다.",
                self.COLOR_DANGER,
                duration=8000,
            )
            self._schedule_focus_return()
            return True

        self._phs_label_candidate_pending = True
        self._phs_reconciliation_resolve_pending = True
        progress_before = self._capture_phs_reconciliation_progress()
        finish_identity = self._capture_mutation_finish_identity()
        payload_snapshot = str(payload)
        marker_master_label = str(
            getattr(self.current_tray, "master_label_code", "") or ""
        )
        marker_operator = str(getattr(self, "worker_name", "") or "")
        marker_log_path = str(getattr(self, "log_file_path", "") or "")
        lane = self._ui_task_lane()
        self._set_phs_reconciliation_context(None)
        self.show_status_message(
            "스캔 현품표의 이적 교체 작업을 중앙에서 조회합니다.",
            self.COLOR_PRIMARY,
            duration=0,
        )
        self._schedule_focus_return()

        def work() -> Dict[str, Any]:
            context = reconciliation.resolve(payload_snapshot)
            marker_outcome = None
            if self._phs_replacement_notice_pair(context) is not None:
                apply_ready = self._call_transfer_ui_sync(
                    lambda: self._mutation_finish_can_apply(
                        finish_identity,
                        operation="phs-reconciliation-resolve",
                    )
                )
                if apply_ready:
                    marker_outcome = (
                        self._work_phs_replacement_waiting_marker(
                            context,
                            master_label=marker_master_label,
                            operator=marker_operator,
                            projection_log_file_path=marker_log_path,
                        )
                    )
            else:
                marker_outcome = {"ready": True, "notice_key": None}
            return {
                "context": context,
                "marker_outcome": marker_outcome,
            }

        def finish(outcome: Dict[str, Any]) -> None:
            context = outcome.get("context")
            if not isinstance(context, dict):
                raise TypeError("reconciliation lane result has no context")
            preserved = self._phs_reconciliation_progress_unchanged(
                progress_before
            )
            apply_ready = self._mutation_finish_can_apply(
                finish_identity,
                operation="phs-reconciliation-resolve",
            )
            self._phs_reconciliation_resolve_pending = False
            self._phs_label_candidate_pending = False
            if not preserved or not apply_ready:
                if not self._preflight_context_blocks_mutation():
                    self.show_status_message(
                        "현품표 조회 중 현재 이적 작업 상태가 변경되어 결과를 "
                        "적용하지 않았습니다.",
                        self.COLOR_DANGER,
                        duration=8000,
                    )
                self._update_action_button_states()
                self._schedule_focus_return()
                return
            marker_ready, marker_new = (
                self._finish_phs_replacement_waiting_marker(
                    outcome.get("marker_outcome")
                )
            )
            if not marker_ready:
                self._set_phs_reconciliation_context(None)
                self._phs_reconciliation_execution_guard = None
                self._update_action_button_states()
                self._schedule_focus_return()
                return
            self._set_phs_reconciliation_context(context)
            self._phs_reconciliation_execution_guard = (
                self._capture_phs_reconciliation_progress()
            )
            summaries = reconciliation.target_summaries(context)
            if marker_new:
                self._show_phs_replacement_required_notice()
            else:
                self.show_status_message(
                    f"서버 교체 지시 {len(summaries)}장을 확인했습니다. "
                    "F8로 출력·교체를 계속하세요.",
                    self.COLOR_PRIMARY,
                    duration=8000,
                )
            try:
                self._log_event(
                    "PHS_RECONCILIATION_ACTION_RESOLVED",
                    detail={
                        "reconciliation_id": context[
                            "reconciliation"
                        ]["reconciliation_id"],
                        "action_ids": list(
                            context["selection"]["action_ids"]
                        ),
                        "exchange_kind": context[
                            "expected_exchange_kind"
                        ],
                        "target_count": len(summaries),
                        "local_progress_preserved": True,
                    },
                )
            except Exception:
                pass
            self._update_action_button_states()
            self._schedule_focus_return()

        def fail(exc: BaseException) -> None:
            print(
                "현품표 reconciliation 조회 lane 실패: "
                f"{exc.__class__.__name__}"
            )
            self._phs_reconciliation_resolve_pending = False
            self._phs_label_candidate_pending = False
            self.show_status_message(
                "현품표 교체 작업을 확인하지 못했습니다. F8로 다시 시도하세요.",
                self.COLOR_DANGER,
                duration=8000,
            )
            self._update_action_button_states()
            self._schedule_focus_return()

        admission = lane.submit(
            LaneTask(
                name="phs-reconciliation-resolve",
                generation=int(getattr(self, "_scan_callback_epoch", 0) or 0),
                work=work,
                finish=finish,
                fail=fail,
                on_idle=(
                    (lambda: lane.close_idle())
                    if not hasattr(self.root, "tk")
                    else None
                ),
            )
        )
        if not admission.accepted:
            self._phs_reconciliation_resolve_pending = False
            self._phs_label_candidate_pending = False
            self._update_action_button_states()
            self.show_status_message(
                "이전 중앙 작업 처리 중입니다. 이번 현품표 입력은 접수되지 않았습니다.",
                self.COLOR_DANGER,
                duration=0,
            )
            self._schedule_focus_return()
            return True
        self._phs_reconciliation_resolve_task_handle = admission.handle
        return True

    def _execute_selected_phs_label_exchange(self) -> None:
        if self._reject_mutation_during_preflight_hold():
            return
        coordinator = getattr(self, "phs_label_exchange_coordinator", None)
        try:
            recovery = (
                coordinator.journal.load()
                if coordinator is not None
                else {}
            )
        except Exception:
            self.show_status_message(
                "이전 현품표 교체 상태를 확인하지 못했습니다. 관리자에게 문의하세요.",
                self.COLOR_DANGER,
                duration=8000,
            )
            self._schedule_focus_return()
            return
        reconciliation_pending = bool(
            recovery
            and str(recovery.get("status") or "").strip().upper()
            not in {"COMMITTED", "CANCELLED"}
            and str(recovery.get("workflow_kind") or "")
            == "RECONCILIATION"
        )
        if (
            getattr(self, "_phs_reconciliation_context", None)
            or reconciliation_pending
        ):
            self._execute_phs_reconciliation_exchange(
                recovery_only=reconciliation_pending
                and not getattr(
                    self, "_phs_reconciliation_context", None
                )
            )
            return
        if (
            not self._phs_label_exchange_available_for_tray()
            or getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_phs_label_refresh_pending", False)
        ):
            self._schedule_focus_return()
            return
        candidate = self._selected_phs_label_candidate()
        coordinator = self.phs_label_exchange_coordinator
        if candidate is None:
            try:
                recovery = coordinator.journal.load()
            except Exception:
                self.show_status_message(
                    "이전 현품표 교체 상태를 확인하지 못했습니다. 관리자에게 문의하세요.",
                    self.COLOR_DANGER,
                    duration=8000,
                )
                self._schedule_focus_return()
                return
            if not recovery or str(recovery.get("status") or "").upper() in {
                "COMMITTED",
                "CANCELLED",
            }:
                self.show_status_message(
                    "먼저 중앙 작업지시 후보를 조회하고 선택하세요.",
                    self.COLOR_DANGER,
                    duration=6000,
                )
                self._schedule_focus_return()
                return
            candidate = (
                dict(recovery.get("target_instruction"))
                if isinstance(recovery.get("target_instruction"), dict)
                else None
            )
        tray = self.current_tray
        captured_master_label = str(tray.master_label_code or "")
        tray_snapshot = copy.deepcopy(tray)
        candidate_snapshot = copy.deepcopy(candidate)
        finish_identity = self._capture_mutation_finish_identity()
        confirm_reprint = bool(
            getattr(
                getattr(self, "phs_label_reprint_confirm_var", None),
                "get",
                lambda: False,
            )()
        )
        lane = self._ui_task_lane()
        self._phs_label_exchange_pending = True
        self._update_action_button_states()
        self.show_status_message(
            "현품표 날짜 교환을 시작했습니다. 스캔 포커스와 현재 트레이 "
            "진행은 유지됩니다.",
            self.COLOR_PRIMARY,
            duration=0,
        )
        self._schedule_focus_return()

        def work() -> tuple[Any, TraySession]:
            result = coordinator.execute_single(
                tray_snapshot,
                candidate_snapshot,
                persist_tray=None,
                defer_local_refresh=True,
                confirm_ambiguous_reprint=confirm_reprint,
                status_callback=None,
            )
            return result, tray_snapshot

        def finish(outcome: tuple[Any, TraySession]) -> None:
            result, updated_tray = outcome
            apply_ready = self._mutation_finish_can_apply(
                finish_identity,
                operation="phs-label-exchange",
            )
            self._phs_label_exchange_pending = False
            if not apply_ready:
                self._update_action_button_states()
                self._schedule_focus_return()
                return
            local_ready = self._apply_phs_label_exchange_snapshot(
                captured_tray=tray,
                captured_master_label=captured_master_label,
                updated_tray=updated_tray,
                force_persist=bool(result.success),
            )
            refresh_confirmed = False
            if result.success and local_ready:
                try:
                    coordinator.confirm_local_refresh_applied(
                        exchange_id=result.exchange_id,
                    )
                    refresh_confirmed = True
                except Exception as exc:
                    print(
                        "현품표 교체 local refresh 완료 기록 실패: "
                        f"{exc.__class__.__name__}"
                    )
            success = bool(
                result.success and local_ready and refresh_confirmed
            )
            if success:
                self._set_phs_label_candidates([])
                try:
                    self.phs_label_reprint_confirm_var.set(False)
                except (tk.TclError, AttributeError):
                    pass
                try:
                    self._log_event(
                        "PHS_LABEL_DATE_EXCHANGED",
                        detail={
                            "exchange_id": result.exchange_id,
                            "canonical_input_tag_qr": (
                                tray.canonical_input_tag_qr
                            ),
                            "active_label_id": tray.active_label_id,
                            "active_label_business_date": (
                                tray.active_label_business_date
                            ),
                            "active_label_worker_code": (
                                tray.active_label_worker_code
                            ),
                            "local_progress_preserved": True,
                        },
                    )
                except Exception:
                    pass
                color = self.COLOR_SUCCESS
            else:
                color = self.COLOR_DANGER
            self.show_status_message(
                (
                    "현품표 날짜 교환을 완료했습니다. 현재 트레이 진행은 유지됩니다."
                    if success
                    else "현품표 날짜 교환을 완료하지 못했습니다. F8로 복구하거나 관리자에게 문의하세요."
                ),
                color,
                duration=10000,
            )
            self._update_current_item_label()
            self._update_center_display()
            self._update_action_button_states()
            self._schedule_focus_return()
            if (
                success
                and tray is self.current_tray
                and not getattr(self, "_ui_close_requested", False)
                and len(tray.scanned_barcodes) >= int(tray.tray_size or 0)
            ):
                self.root.after(0, self.request_complete_tray)

        def fail(exc: BaseException) -> None:
            print(f"현품표 날짜 교환 lane 실패: {exc.__class__.__name__}")
            self._phs_label_exchange_pending = False
            self.show_status_message(
                "현품표 날짜 교환을 완료하지 못했습니다. F8로 복구하거나 관리자에게 문의하세요.",
                self.COLOR_DANGER,
                duration=10000,
            )
            self._update_action_button_states()
            self._schedule_focus_return()

        admission = lane.submit(
            LaneTask(
                name="phs-label-exchange",
                generation=int(getattr(self, "_scan_callback_epoch", 0) or 0),
                work=work,
                finish=finish,
                fail=fail,
                on_idle=(
                    (lambda: lane.close_idle())
                    if not hasattr(self.root, "tk")
                    else None
                ),
            )
        )
        if not admission.accepted:
            self._phs_label_exchange_pending = False
            self._update_action_button_states()
            self.show_status_message(
                "이전 중앙 작업 처리 중입니다. 이번 현품표 입력은 접수되지 않았습니다.",
                self.COLOR_DANGER,
                duration=0,
            )
            self._schedule_focus_return()
            return
        self._phs_label_exchange_task_handle = admission.handle

    def _confirm_phs_reconciliation_ambiguous_reprint(
        self,
        *,
        already_confirmed: bool,
        on_confirm,
    ) -> Optional[bool]:
        if already_confirmed:
            return True
        journal = getattr(
            getattr(self, "phs_label_exchange_coordinator", None),
            "journal",
            None,
        )
        load_recovery = getattr(journal, "load", None)
        if not callable(load_recovery):
            return False
        try:
            recovery = load_recovery()
        except Exception as exc:
            print(
                "현품표 교체 복구 정보 읽기 실패: "
                f"{exc.__class__.__name__}: {exc}"
            )
            self.show_status_message(
                "현품표 교체 복구 정보를 읽지 못했습니다. "
                "F8로 다시 시도하거나 관리자에게 문의하세요.",
                self.COLOR_DANGER,
                duration=10000,
            )
            self._schedule_focus_return()
            return None
        if not isinstance(recovery, Mapping):
            return False
        if (
            str(recovery.get("workflow_kind") or "").strip().upper()
            != "RECONCILIATION"
            or str(recovery.get("status") or "").strip().upper()
            != "LOCAL_PRINT_STARTING"
        ):
            return False
        def keep_pending():
            self.show_status_message(
                "미완료 현품표 교체를 보존했습니다. 실물 라벨을 확인한 뒤 "
                "F8로 다시 복구할 수 있습니다.",
                self.COLOR_DANGER,
                duration=8000,
            )
            self._schedule_focus_return()
            return True

        recovery = copy.deepcopy(recovery)

        def approve_current_reprint():
            try:
                unchanged = (
                    getattr(getattr(self, "phs_label_exchange_coordinator", None), "journal", None) is journal
                    and journal.load() == recovery
                )
            except Exception:
                unchanged = False
            if not unchanged:
                self.show_status_message(
                    "현품표 복구 정보가 바뀌었거나 확인되지 않았습니다. F8로 다시 확인하세요.",
                    self.COLOR_DANGER, duration=8000,
                )
                self._schedule_focus_return()
                return
            on_confirm()

        self._request_inline_choice(
            "실물 현품표 재출력 확인",
            "이전 실행이 프린터 제출 중 종료되어 출력 여부가 불확실합니다. "
            "실물 라벨을 확인한 뒤 '실물 확인 후 재출력'을 누르세요. "
            "다음 스캔은 재출력하지 않고 계속합니다.",
            [("실물 확인 후 재출력", approve_current_reprint), ("작업 계속", keep_pending)],
            on_scan=keep_pending,
        )
        return None

    def _execute_phs_reconciliation_exchange(
        self,
        *,
        recovery_only: bool = False,
        _confirmed_reprint: bool = False,
    ) -> None:
        if self._reject_mutation_during_preflight_hold():
            return
        coordinator = getattr(
            getattr(self, "phs_label_exchange_coordinator", None),
            "reconciliation",
            None,
        )
        if (
            coordinator is None
            or not coordinator.available
            or getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_phs_label_refresh_pending", False)
        ):
            self._schedule_focus_return()
            return
        context = (
            None
            if recovery_only
            else getattr(self, "_phs_reconciliation_context", None)
        )
        if context is None and not recovery_only:
            self.show_status_message(
                "먼저 F8을 누르고 현재 또는 완료된 이적 현품표를 스캔하세요.",
                self.COLOR_DANGER,
                duration=7000,
            )
            self._schedule_focus_return()
            return
        confirm_reprint = _confirmed_reprint or bool(
            getattr(
                getattr(self, "phs_label_reprint_confirm_var", None),
                "get",
                lambda: False,
            )()
        )
        confirm_reprint_result = (
            self._confirm_phs_reconciliation_ambiguous_reprint(
                already_confirmed=confirm_reprint,
                on_confirm=lambda: self._execute_phs_reconciliation_exchange(
                    recovery_only=recovery_only, _confirmed_reprint=True),
            )
        )
        if confirm_reprint_result is None:
            return
        confirm_reprint = confirm_reprint_result
        execution_guard = getattr(
            self,
            "_phs_reconciliation_execution_guard",
            None,
        )
        if (
            context is not None
            and execution_guard is not None
            and not self._phs_reconciliation_progress_unchanged(
                execution_guard
            )
        ):
            self._set_phs_reconciliation_context(None)
            self.show_status_message(
                "조회 후 현재 이적 작업이 바뀌어 교체 실행을 취소했습니다. "
                "F8로 현품표를 다시 스캔하세요.",
                self.COLOR_IDLE,
                duration=8000,
            )
            self._schedule_focus_return()
            return
        snapshot = self._capture_phs_reconciliation_progress()
        finish_identity = self._capture_mutation_finish_identity()
        context_snapshot = copy.deepcopy(context)
        lane = self._ui_task_lane()
        self._phs_label_exchange_pending = True
        self._update_action_button_states()
        self.show_status_message(
            "서버 지시에 따라 새 현품표 출력·교체를 진행합니다. "
            "현재 이적 작업은 그대로 유지됩니다.",
            self.COLOR_PRIMARY,
            duration=0,
        )
        self._schedule_focus_return()

        def work() -> Any:
            return coordinator.execute(
                context_snapshot,
                confirm_ambiguous_reprint=confirm_reprint,
                status_callback=None,
            )

        def finish(result: Any) -> None:
            apply_ready = self._mutation_finish_can_apply(
                finish_identity,
                operation="phs-reconciliation-exchange",
            )
            self._phs_label_exchange_pending = False
            if not apply_ready:
                self._update_action_button_states()
                self._schedule_focus_return()
                return
            preserved = self._phs_reconciliation_progress_unchanged(
                snapshot
            )
            if not preserved:
                self.show_status_message(
                    "현품표 교체 중 현재 이적 작업 상태가 변경됐습니다. "
                    "추가 교체를 중지하고 관리자에게 문의하세요.",
                    self.COLOR_DANGER,
                    duration=10000,
                )
            elif result.success:
                self._set_phs_reconciliation_context(None)
                try:
                    self.phs_label_reprint_confirm_var.set(False)
                except (tk.TclError, AttributeError):
                    pass
                try:
                    self._log_event(
                        "PHS_RECONCILIATION_LABEL_EXCHANGED",
                        detail={
                            "exchange_id": result.exchange_id,
                            "status": result.status,
                            "local_progress_preserved": True,
                        },
                    )
                except Exception:
                    pass
                self.show_status_message(
                    "현품표 교체를 완료했습니다. 현재 이적 작업은 유지됩니다.",
                    self.COLOR_SUCCESS,
                    duration=10000,
                )
            else:
                journal_context = (
                    result.journal_state.get(
                        "reconciliation_context"
                    )
                    if isinstance(result.journal_state, Mapping)
                    else None
                )
                if isinstance(journal_context, Mapping):
                    self._set_phs_reconciliation_context(
                        journal_context
                    )
                self.show_status_message(
                    "현품표 교체를 완료하지 못했습니다. F8로 복구하거나 관리자에게 문의하세요.",
                    self.COLOR_DANGER,
                    duration=10000,
                )
            self._update_current_item_label()
            self._update_center_display()
            self._update_action_button_states()
            self._schedule_focus_return()

        def fail(exc: BaseException) -> None:
            print(f"현품표 reconciliation lane 실패: {exc.__class__.__name__}")
            self._phs_label_exchange_pending = False
            self.show_status_message(
                "현품표 교체를 완료하지 못했습니다. F8로 복구하거나 관리자에게 문의하세요.",
                self.COLOR_DANGER,
                duration=10000,
            )
            self._update_action_button_states()
            self._schedule_focus_return()

        admission = lane.submit(
            LaneTask(
                name="phs-reconciliation-exchange",
                generation=int(getattr(self, "_scan_callback_epoch", 0) or 0),
                work=work,
                finish=finish,
                fail=fail,
                on_idle=(
                    (lambda: lane.close_idle())
                    if not hasattr(self.root, "tk")
                    else None
                ),
            )
        )
        if not admission.accepted:
            self._phs_label_exchange_pending = False
            self._update_action_button_states()
            self.show_status_message(
                "이전 중앙 작업 처리 중입니다. 이번 현품표 입력은 접수되지 않았습니다.",
                self.COLOR_DANGER,
                duration=0,
            )
            self._schedule_focus_return()
            return
        self._phs_label_exchange_task_handle = admission.handle

    def _schedule_phs_label_exchange_recovery(self) -> None:
        if (
            getattr(self, "_phs_label_exchange_pending", False)
            or getattr(self, "_ui_close_requested", False)
        ):
            return
        coordinator = getattr(self, "phs_label_exchange_coordinator", None)
        if coordinator is None:
            self._phs_label_recovery_deferred = False
            return
        try:
            recovery = coordinator.journal.load()
        except Exception as exc:
            print(
                "현품표 교환 복구 정보 읽기 실패: "
                f"{exc.__class__.__name__}: {exc}"
            )
            self.show_status_message(
                "현품표 교환 복구 정보를 읽지 못했습니다. "
                "F8로 다시 시도하거나 관리자에게 문의하세요.",
                self.COLOR_DANGER,
                duration=10000,
            )
            self._phs_label_recovery_deferred = False
            return
        if (
            recovery
            and str(recovery.get("status") or "").strip().upper()
            not in {"COMMITTED", "CANCELLED"}
            and str(recovery.get("workflow_kind") or "")
            == "RECONCILIATION"
        ):
            self._phs_label_recovery_deferred = False
            context = recovery.get("reconciliation_context")
            if isinstance(context, Mapping):
                self._set_phs_reconciliation_context(context)
            self._execute_phs_reconciliation_exchange(
                recovery_only=True
            )
            return
        if not self._phs_label_exchange_available_for_tray():
            self._phs_label_recovery_deferred = False
            return
        if (
            not recovery
            or str(recovery.get("status") or "").strip().upper()
            in {"COMMITTED", "CANCELLED"}
            or str(recovery.get("canonical_input_tag_qr") or "").strip()
            != str(self.current_tray.master_label_code or "").strip()
        ):
            self._phs_label_recovery_deferred = False
            return
        if self._preflight_context_blocks_mutation():
            if not getattr(self, "_phs_label_recovery_deferred", False):
                self._reject_mutation_during_preflight_hold()
            self._phs_label_recovery_deferred = True
            try:
                self.root.after(100, self._schedule_phs_label_exchange_recovery)
            except (tk.TclError, AttributeError):
                pass
            return
        self._phs_label_recovery_deferred = False
        tray = self.current_tray
        captured_master_label = str(tray.master_label_code or "")
        tray_snapshot = copy.deepcopy(tray)
        finish_identity = self._capture_mutation_finish_identity()
        lane = self._ui_task_lane()
        self._phs_label_exchange_pending = True
        self._update_action_button_states()
        self.show_status_message(
            "미완료 현품표 날짜 교환을 중앙 ACK에서 복구하고 있습니다.",
            self.COLOR_PRIMARY,
            duration=0,
        )

        def work() -> tuple[Any, TraySession]:
            result = coordinator.recover_for_tray(
                tray_snapshot,
                persist_tray=None,
                defer_local_refresh=True,
                status_callback=None,
            )
            return result, tray_snapshot

        def finish(outcome: tuple[Any, TraySession]) -> None:
            result, updated_tray = outcome
            apply_ready = self._mutation_finish_can_apply(
                finish_identity,
                operation="phs-label-recovery",
            )
            self._phs_label_exchange_pending = False
            if not apply_ready:
                self._update_action_button_states()
                self._schedule_focus_return()
                return
            local_ready = False
            refresh_confirmed = False
            if result is not None:
                local_ready = self._apply_phs_label_exchange_snapshot(
                    captured_tray=tray,
                    captured_master_label=captured_master_label,
                    updated_tray=updated_tray,
                    force_persist=bool(result.success),
                )
                if result.success and local_ready:
                    try:
                        coordinator.confirm_local_refresh_applied(
                            exchange_id=result.exchange_id,
                        )
                        refresh_confirmed = True
                    except Exception as exc:
                        print(
                            "현품표 교체 복구 local refresh 완료 기록 실패: "
                            f"{exc.__class__.__name__}"
                        )
                success = bool(
                    result.success and local_ready and refresh_confirmed
                )
                self.show_status_message(
                    (
                        "이전 현품표 교체를 복구했습니다. 현재 트레이 진행은 유지됩니다."
                        if success
                        else "이전 현품표 교체를 복구하지 못했습니다. 관리자에게 문의하세요."
                    ),
                    self.COLOR_SUCCESS if success else self.COLOR_DANGER,
                    duration=10000,
                )
            else:
                success = False
            self._update_current_item_label()
            self._update_center_display()
            self._update_action_button_states()
            self._schedule_focus_return()
            if (
                success
                and tray is self.current_tray
                and not getattr(self, "_ui_close_requested", False)
                and len(tray.scanned_barcodes) >= int(tray.tray_size or 0)
            ):
                self.root.after(0, self.request_complete_tray)

        def fail(exc: BaseException) -> None:
            print(f"현품표 교체 복구 lane 실패: {exc.__class__.__name__}")
            self._phs_label_exchange_pending = False
            self.show_status_message(
                "이전 현품표 교체를 복구하지 못했습니다. 관리자에게 문의하세요.",
                self.COLOR_DANGER,
                duration=10000,
            )
            self._update_action_button_states()
            self._schedule_focus_return()

        admission = lane.submit(
            LaneTask(
                name="phs-label-recovery",
                generation=int(getattr(self, "_scan_callback_epoch", 0) or 0),
                work=work,
                finish=finish,
                fail=fail,
                on_idle=(
                    (lambda: lane.close_idle())
                    if not hasattr(self.root, "tk")
                    else None
                ),
            )
        )
        if not admission.accepted:
            self._phs_label_exchange_pending = False
            self._update_action_button_states()
            self.show_status_message(
                "이전 중앙 작업 처리 중입니다. 이번 현품표 입력은 접수되지 않았습니다.",
                self.COLOR_DANGER,
                duration=0,
            )
            self._schedule_focus_return()
            if (
                admission.reason == "busy"
                and not getattr(self, "_ui_close_requested", False)
            ):
                self._phs_label_recovery_deferred = True
                try:
                    self.root.after(
                        100,
                        self._schedule_phs_label_exchange_recovery,
                    )
                except (tk.TclError, AttributeError):
                    pass
            return
        self._phs_label_exchange_task_handle = admission.handle

    def _show_operations_menu(self) -> None:
        """Show secondary and destructive actions without growing the center pane."""

        hold_blocked = self._preflight_context_blocks_mutation()
        offline_hold = hold_blocked and self._offline_preflight_quarantine_blocked()
        active_tray = bool(getattr(getattr(self, "current_tray", None), "master_label_code", ""))
        completion_blocked = bool(
            active_tray and self._active_blocking_completion_snapshot() is not None
        )
        exchange = self._current_transfer_member_exchange_attempt()
        exchange_blocked = bool(
            exchange is not None
            and (exchange.status != "ACKED" or exchange.local_apply_status != "APPLIED")
        )
        if (
            self._warning_state_presenter().state.is_blocking
            and not (hold_blocked or completion_blocked or exchange_blocked)
        ):
            if not self._admin_pin_has_pending():
                self._render_warning_state()
                return
            menu = tk.Menu(self.root, tearoff=False)
            menu.add_command(label="관리자 확인 다시 조회",
                             command=self._recheck_admin_pin_intents)
            button = getattr(self, "operations_button", None)
            try:
                menu.tk_popup(button.winfo_rootx(), button.winfo_rooty() + button.winfo_height())
            except (tk.TclError, AttributeError):
                return
            finally:
                try:
                    menu.grab_release()
                except tk.TclError:
                    pass
            return
        replacement_active = bool(getattr(self, "master_label_replace_state", None))
        exchange_dialog_open = self._widget_exists(getattr(self, "exchange_dialog", None))
        lane = getattr(self, "_ui_lane", None)
        transfer_lane_busy = bool(lane is not None and lane.is_busy())
        exact_exchange_blocked = self._exact_transfer_exchange_blocked()
        scanned_count = len(
            getattr(getattr(self, "current_tray", None), "scanned_barcodes", []) or []
        )
        active_transfer_exchange_available = bool(
            exact_exchange_blocked
            and active_tray
            and scanned_count
            and not transfer_lane_busy
        )

        menu = tk.Menu(self.root, tearoff=False)
        menu.add_command(
            label="전송 상태 상세",
            command=self._show_direct_sync_status_details,
        )
        menu.add_command(
            label="관리자 확인 다시 조회",
            command=self._recheck_admin_pin_intents,
            state=tk.NORMAL if self._admin_pin_has_pending() else tk.DISABLED,
        )
        menu.add_command(
            label="원 요청 결과 다시 확인",
            command=self._recheck_unsettled_current_work,
            state=(
                tk.NORMAL if (hold_blocked or completion_blocked or exchange_blocked)
                and not transfer_lane_busy else tk.DISABLED
            ),
        )
        menu.add_command(
            label="관리자 인계 내용 보기",
            command=self._show_blocked_work_handoff,
            state=(
                tk.NORMAL if hold_blocked or completion_blocked or exchange_blocked
                else tk.DISABLED
            ),
        )
        menu.add_command(
            label="보류 묶음 격리 후 다른 작업 계속 (관리자)",
            command=self._quarantine_preflight_hold_from_operations,
            state=tk.NORMAL if hold_blocked and not active_tray and not transfer_lane_busy
            and not offline_hold
            else tk.DISABLED,
        )
        if offline_hold:
            menu.add_command(label="연결 끊김: PIN 격리 불가 · 다음 현품표를 스캔하세요", state=tk.DISABLED)
        menu.add_command(
            label="두 원본 함께 보류 후 계속 (관리자)",
            command=self._defer_paired_preflight_from_operations,
            state=tk.NORMAL if hold_blocked and not transfer_lane_busy else tk.DISABLED,
        )
        menu.add_command(
            label="관리자 짝 원본 보류 목록",
            command=self._show_paired_preflight_handoffs,
        )
        if getattr(self, "_paired_stale_current_blocked", False):
            menu.add_command(
                label="현재 현품표 보존 재확인 (관리자)",
                command=self._recheck_paired_stale_current,
            )
            menu.add_command(
                label="현재 현품표 보존 다시 시도 (관리자)",
                command=self._retry_paired_stale_current_preservation,
            )
            menu.add_command(
                label="보류 후 다른 현품표 계속 (관리자)",
                command=self._continue_after_paired_stale_current,
            )
        menu.add_command(
            label="미확정 묶음 보류 후 다른 작업 계속 (관리자)",
            command=self._defer_blocked_current_tray_for_supervisor,
            state=(
                tk.NORMAL if active_tray and not hold_blocked
                and (completion_blocked or exchange_blocked)
                and not transfer_lane_busy else tk.DISABLED
            ),
        )
        menu.add_command(
            label="품목 목록 새로 고침",
            command=self._refresh_item_catalog,
        )
        menu.add_command(
            label="현품표 교체 (F8)",
            command=self._on_phs_label_exchange_shortcut,
        )
        menu.add_command(
            label="완료 작업 중앙 반영 재시도 (관리자)",
            command=self._retry_transfer_post_review,
            state=(
                tk.NORMAL
                if self._is_preflight_hold_supervisor()
                and not active_tray
                and not transfer_lane_busy
                and not replacement_active
                else tk.DISABLED
            ),
        )
        menu.add_separator()
        menu.add_command(
            label="현재 작업 리셋",
            command=self.reset_current_work,
            state=tk.NORMAL if active_tray else tk.DISABLED,
        )
        menu.add_separator()
        menu.add_command(
            label=(
                "현품표 교체 취소"
                if replacement_active
                else (
                    "중앙 교체 절차 필요"
                    if exact_exchange_blocked
                    else "완료 현품표 교체"
                )
            ),
            command=self.initiate_master_label_replacement,
            state=(
                tk.NORMAL
                if replacement_active
                or (
                    not exact_exchange_blocked
                    and not transfer_lane_busy
                    and not active_tray
                    and not exchange_dialog_open
                )
                else tk.DISABLED
            ),
        )
        menu.add_command(
            label=(
                "현재 이적 제품 교체"
                if active_transfer_exchange_available
                else "중앙 교환 절차 필요"
                if exact_exchange_blocked
                else "개별 제품 교환"
            ),
            command=self.show_exchange_dialog,
            state=(
                tk.NORMAL
                if active_transfer_exchange_available and not replacement_active
                else tk.DISABLED
                if active_tray
                or replacement_active
                or exact_exchange_blocked
                or transfer_lane_busy
                else tk.NORMAL
            ),
        )
        button = getattr(self, "operations_button", None)
        try:
            x = button.winfo_rootx()
            y = button.winfo_rooty() + button.winfo_height()
            menu.tk_popup(x, y)
        except (tk.TclError, AttributeError):
            try:
                menu.tk_popup(self.root.winfo_pointerx(), self.root.winfo_pointery())
            except (tk.TclError, AttributeError):
                return
        finally:
            try:
                menu.grab_release()
            except tk.TclError:
                pass

    def _authorize_blocked_work_supervisor(self) -> Optional[Dict[str, str]]:
        operator = str(getattr(self, "worker_name", "") or "").strip()
        role = str(getattr(self, "worker_role", "") or "").upper()
        if operator == PROTECTED_ADMIN_OPERATOR_ID and role == "ADMIN" and getattr(
            self, "_authenticated_protected_admin", False
        ):
            return {"operator": operator, "role": role, "supervisor": "",
                    "login_epoch": getattr(self, "_admin_pin_login_epoch", "")}
        if not operator or role != "WORKER" or operator == PROTECTED_ADMIN_OPERATOR_ID:
            messagebox.showwarning(
                "관리자 신원 확인 필요",
                "현재 로그인 작업자와 역할을 확인할 수 없습니다. 다시 로그인한 뒤 관리자 확인을 받으세요.",
                parent=getattr(self, "root", None),
            )
            return None
        return {"operator": operator, "role": role, "supervisor": "",
                "login_epoch": getattr(self, "_admin_pin_login_epoch", "")}

    def _prompt_blocked_work_admin_pin(
        self, *, action: str = "", target_id: str = "", labels: tuple[str, ...] = (),
    ) -> Optional[tuple[str, str]]:
        """Show the original request beside its administrator ID and masked PIN."""
        dialog = tk.Toplevel(self.root)
        dialog.title("관리자 PIN 확인")
        dialog.transient(self.root)
        dialog.resizable(False, False)
        frame = ttk.Frame(dialog, padding=16)
        frame.pack(fill="both", expand=True)
        caption = {
            "CA.PRECHECK_HOLD": "검사 대기 보류 처리", "CA.PAIR_RETRY": "보류 다시 확인",
            "CA.PAIR_HANDOFF": "접수 보류 인계", "CA.TRAY_HOLD": "트레이 보류 처리",
        }.get(action, "보류 처리")
        detail = (f"처리: {caption}\n대상: {target_id}\n"
                  f"원 현품표: {', '.join(labels) or '대상 원본 기록 참조'}")
        ttk.Label(frame, text=detail, wraplength=420, justify="left").grid(
            row=0, column=0, columnspan=2, sticky="w", pady=(0, 8))
        ttk.Label(frame, text="관리자 ID").grid(row=1, column=0, sticky="w", pady=4)
        admin_entry = ttk.Entry(frame, width=26)
        admin_entry.grid(row=1, column=1, pady=4)
        ttk.Label(frame, text="6자리 PIN").grid(row=2, column=0, sticky="w", pady=4)
        pin_entry = ttk.Entry(frame, width=26, show="●")
        pin_entry.grid(row=2, column=1, pady=4)
        result = []

        def submit(_event=None):
            result.append((admin_entry.get().strip(), pin_entry.get()))
            pin_entry.delete(0, "end")
            dialog.destroy()

        ttk.Button(frame, text="확인", command=submit).grid(row=3, column=1, sticky="e", pady=8)
        dialog.bind("<Return>", submit)
        dialog.grab_set()
        admin_entry.focus_set()
        self.root.wait_window(dialog)
        return result[0] if result else None

    def _admin_pin_store(self) -> AdminPinIntentStore:
        return AdminPinIntentStore(Path(self.parked_trays_dir) / "admin_pin_intents")

    def _admin_pin_has_pending(self) -> bool:
        if not str(getattr(self, "parked_trays_dir", "") or ""):
            return False
        try:
            return bool(self._admin_pin_store().list_pending())
        except (OSError, ValueError, TypeError):
            return True  # Keep administrator requery available when listing fails.

    def _admin_pin_client_for_work(self) -> AdminPinClient:
        injected = getattr(self, "_admin_pin_client", None)
        if injected is not None:
            return injected
        if self.storage_paths.credential_path.is_file():
            from direct_sync_runtime import prepare_credential_config
            with writer_admission("gui_constructor"):
                startup_prepared = getattr(self, "_prepared_admin_pin_credential", None)
                if startup_prepared is not None:
                    startup_prepared.admit_security_inputs()
                prepared = prepare_credential_config(self.storage_paths.credential_path,
                                                     data_root=self.storage_paths.data_root)
            return AdminPinClient(self.storage_paths.credential_path, prepared_config=prepared)
        return AdminPinClient(self.storage_paths.credential_path, data_root=self.storage_paths.data_root)

    def _admin_pin_audit(self, event: str, intent: Mapping[str, Any]) -> bool:
        resume_epoch = (str((intent.get("resuming_operator") or {}).get("login_epoch") or "")
                        if event == "ADMIN_PIN_RESUMED" else "")
        source = intent.get("source_snapshot") or {}
        audit_path = (str(Path(self.save_folder) /
                          f"admin-pin-{uuid.UUID(intent['operation_key']).hex}.csv")
                      if source.get("source_audit_id") else "")
        return bool(self._log_event(
            event,
            detail={"action": intent["action"], "target": intent["target"],
                     "operator": intent["operator"],
                     "operator_raw": intent.get("operator_raw") or "",
                     "resuming_operator": intent.get("resuming_operator") or {},
                     "resuming_operator_raw": intent.get("resuming_operator_raw") or "",
                    "verification_id": intent.get("verification_id") or "",
                    "operation_key": intent["operation_key"],
                    "reason": intent.get("reason") or ""},
            synchronous=True,
            idempotency_key=f"admin-pin:{event}:{intent['operation_key']}:{resume_epoch}",
            deduplicate=True,
            log_file_path_override=audit_path,
        ))

    def _admin_pin_record_resumer(self, intent: Mapping[str, Any]) -> Dict[str, Any]:
        base = self._authorize_blocked_work_supervisor()
        if base is None:
            raise AdminPinError("OPERATOR_MISSING", unknown=True)
        operator = {"local_id": operator_local_id(base["operator"]),
                    "login_epoch": base["login_epoch"]}
        if operator == intent["operator"] or operator == intent.get("resuming_operator"):
            return dict(intent)
        resumed = dict(intent, resuming_operator=operator,
                       resuming_operator_raw=base["operator"])
        if not self._admin_pin_audit("ADMIN_PIN_RESUMED", resumed):
            raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
        return self._admin_pin_store().write(resumed)

    def _admin_pin_handoff_unknown(self, intent: Mapping[str, Any], reason: str) -> None:
        handoff = dict(intent, reason=reason)
        if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", handoff):
            raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
        self._admin_pin_store().transition(handoff, "HANDED_OFF_UNKNOWN", reason=reason)
        messagebox.showwarning(
            "PIN 지원 인계", "소비된 요청의 원본 효과를 증명할 수 없습니다. "
            "원 operation key와 원본을 보존하고 지원 인계하세요.",
            parent=getattr(self, "root", None),
        )

    def _admin_pin_target_changed(self, intent: Mapping[str, Any]) -> None:
        changed = dict(intent, reason="TARGET_CHANGED")
        if not self._admin_pin_audit("ADMIN_PIN_SUPERSEDED", changed):
            raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
        self._admin_pin_store().transition(changed, "TARGET_CHANGED", reason="TARGET_CHANGED")
        messagebox.showwarning(
            "관리자 확인 다시 조회",
            "원본이 바뀌었습니다. 변경 바이트를 보존했습니다. 관리자 목록에서 다시 조회한 뒤 "
            "이 동작을 새 PIN으로 다시 실행하세요.",
            parent=getattr(self, "root", None),
        )

    def _admin_pin_journal_move(self, approval: Mapping[str, str], source: Path,
                                target: Path, expected_sha256: str) -> None:
        store = self._admin_pin_store()
        intent = store.read(approval["operation_key"])
        if intent.get("state") not in {"CONSUMED", "UNVERIFIED_DETACHING"}:
            raise PinnedMoveError("PIN move has no active intent")
        snapshot = intent.get("source_snapshot") or {}
        if expected_sha256 not in (value for name, value in snapshot.items()
                                   if name.endswith("sha256")):
            raise PinnedMoveError("PIN move differs from bound source")
        move = {"source": str(source.resolve()), "target": str(target.resolve()),
                "sha256": expected_sha256}
        moves = list(intent.get("moving") or ())
        if any(row["source"] == move["source"] and row != move for row in moves):
            raise PinnedMoveError("PIN move target changed")
        if move not in moves:
            store.write(dict(intent, move_state="MOVING", moving=[*moves, move]))

    def _admin_pin_move(self, approval: Mapping[str, str], source: Path,
                        target: Path, expected_sha256: str) -> Path:
        try:
            intent = self._admin_pin_store().read(approval["operation_key"])
            for move in intent.get("moving") or ():
                if move["source"] == str(source.resolve()):
                    if move["sha256"] != expected_sha256:
                        raise PinnedMoveError("PIN move source hash changed")
                    source, target = Path(move["source"]), Path(move["target"])
                    break
            return pinned_move(
                source, target, expected_sha256,
                lambda original, held, digest: self._admin_pin_journal_move(
                    approval, original, held, digest),
            )
        except PinnedTargetChanged:
            intent = self._admin_pin_store().read(approval["operation_key"])
            if intent.get("state") == "CONSUMED" and self._admin_pin_restore_moves(intent):
                self._admin_pin_target_changed(intent)
            raise

    def _admin_pin_check_moves(self, intent: Mapping[str, Any]) -> bool:
        for move in intent.get("moving") or ():
            try:
                if intent.get("state") == "APPLIED":
                    # Completed effects are read-only; changed evidence stays put.
                    if (Path(move["source"]).exists()
                            or file_sha256(Path(move["target"])) != move["sha256"]):
                        return False
                    continue
                status = recover_pinned_move(
                    Path(move["source"]), Path(move["target"]), move["sha256"])
                if status == "SOURCE_UNMOVED":
                    self._admin_pin_move(
                        intent, Path(move["source"]), Path(move["target"]), move["sha256"])
            except PinnedTargetChanged:
                if intent.get("state") == "CONSUMED" and self._admin_pin_restore_moves(intent):
                    self._admin_pin_target_changed(intent)
                return False
            except (OSError, KeyError, TypeError, ValueError):
                return False
        return True

    def _admin_pin_restore_moves(self, intent: Mapping[str, Any]) -> bool:
        for move in reversed(intent.get("moving") or ()):
            source, target = Path(move["source"]), Path(move["target"])
            if target.exists():
                if source.exists():
                    return False
                target.rename(source)
        return True

    @contextmanager
    def _admin_pin_locked_sources(self, approval: Mapping[str, str],
                                  sources: Sequence[tuple[Path, str]]):
        intent = self._admin_pin_store().read(approval["operation_key"])
        pinned = {value for name, value in (intent.get("source_snapshot") or {}).items()
                  if name.endswith("sha256")}
        try:
            with ExitStack() as stack:
                for path, digest in sorted(sources, key=lambda item: str(item[0])):
                    if digest not in pinned:
                        raise PinnedTargetChanged("source differs from PIN intent")
                    stack.enter_context(locked_pinned_source(path, digest))
                yield
        except PinnedTargetChanged:
            if intent.get("state") == "CONSUMED":
                self._admin_pin_target_changed(intent)
            raise

    @contextmanager
    def _admin_pin_locked_evidence(self, approval: Mapping[str, str],
                                   path: Path, read_source):
        intent = self._admin_pin_store().read(approval["operation_key"])
        with locked_pinned_source(path, None):
            try:
                if admin_pin_fingerprint(read_source()) != intent["target"]["state_fingerprint"]:
                    raise PinnedTargetChanged("evidence differs from PIN source")
                yield
            except PinnedTargetChanged:
                self._admin_pin_target_changed(intent)
                raise

    def _admin_pin_effect_audited(self, event: str, operation_key: str) -> bool:
        folders = (getattr(self, "local_events_folder", ""), getattr(self, "save_folder", ""))
        for folder_name in folders:
            folder = Path(folder_name) if folder_name else None
            for path in folder.glob("*.csv") if folder and folder.is_dir() else ():
                try:
                    with path.open("r", encoding="utf-8-sig", newline="") as stream:
                        for row in csv.DictReader(stream):
                            if row.get("event") != event:
                                continue
                            try:
                                detail = json.loads(row.get("details") or "{}")
                            except (ValueError, TypeError):
                                continue
                            if isinstance(detail, dict) and detail.get("operation_key") == operation_key:
                                return True
                except (OSError, UnicodeError, csv.Error):
                    continue
        return False

    def _admin_pin_preflight_hold_store(self, intent: Mapping[str, Any]) -> PreflightScanHoldStore:
        """A moved hold still belongs to the source slot recorded before rename."""
        source = intent.get("source_snapshot") or {}
        base = self._preflight_hold_base_path().resolve()
        store = self._preflight_hold_store(preflight_id=source.get("preflight_id", ""))
        pattern = rf"{re.escape(base.stem)}(?:_[0-9a-f]{{16}})?{re.escape(base.suffix)}"
        for move in intent.get("moving") or ():
            original = Path(move["source"])
            target = Path(move["target"])
            if (original.parent == base.parent and re.fullmatch(pattern, original.name)
                    and target.parent == self._preflight_hold_quarantine_directory().resolve()
                    and target.name.startswith(f"preflight_hold_{source.get('preflight_id', '')}_")
                    and move.get("sha256") == source.get("hold_sha256")):
                return PreflightScanHoldStore(original, capacity=store.capacity)
        return store

    def _admin_pin_detach_unverified(self, intent: Mapping[str, Any]) -> bool:
        """Park active original bytes as an unapproved hold so another key can start."""
        source = intent.get("source_snapshot")
        if not isinstance(source, dict):
            raise ValueError("관리자 보류 원본 형식을 확인할 수 없습니다.")
        action = intent.get("action")
        startup = bool(getattr(self, "_admin_pin_detach_startup", False))
        clear_active = False
        if action == "CA.PRECHECK_HOLD" and source.get("hold_sha256"):
            hold = self._admin_pin_preflight_hold_store(intent)
            if hold.path.is_file():
                if hashlib.sha256(hold.path.read_bytes()).hexdigest() != source["hold_sha256"]:
                    return False
                hold.quarantine(self._preflight_hold_quarantine_directory(),
                                reason="admin_pin_unverified_operator_hold",
                                expected_sha256=source["hold_sha256"],
                                move=lambda original, held, digest: self._admin_pin_move(
                                    intent, original, held, digest))
            copies = self._preflight_hold_quarantine_directory().glob(
                f"preflight_hold_{source.get('preflight_id', '')}_*.json")
            if hold.path.exists() or not any(
                    hashlib.sha256(path.read_bytes()).hexdigest() == source["hold_sha256"]
                    for path in copies):
                return False
            self._preflight_hold_snapshot = None
            self._preflight_hold_draining = False
            self._master_preflight_pending = False
            self._set_preflight_scan_input_locked(False)
            if not startup and hasattr(self, "_update_parked_trays_list"):
                self._update_parked_trays_list()
            return not self._preflight_context_blocks_mutation()
        if action in {"CA.PAIR_HANDOFF", "CA.TRAY_HOLD"} and source.get("handoff_id"):
            store = self._paired_preflight_store()
            path = store.directory / str(source["handoff_id"]) / "record.json"
            if not path.is_file():
                return False
            if source.get("record_sha256") and hashlib.sha256(path.read_bytes()).hexdigest() != source["record_sha256"]:
                return False
            record = store.read(path)
            if action == "CA.PAIR_HANDOFF" and any(
                    record[name]["sha256"] != source.get(name + "_sha256")
                    for name in ("hold", "current")):
                return False
            for name in ("hold", "current"):
                store.move_original(
                    path, name, expected_sha256=source[name + "_sha256"],
                    move=lambda original, held, digest: self._admin_pin_move(
                        intent, original, held, digest),
                )
            store.release(path)
            if store.inspect(path).unidentified:
                labels = tuple(intent.get("labels") or ())
                if len(labels) != 2:
                    return False
                store.bind_unidentified(path, labels)
            if not store.originals_match(path) or not store.is_released(path):
                return False
            self._preflight_hold_snapshot = None
            self._preflight_hold_draining = False
            self._master_preflight_pending = False
            self.current_tray = TraySession()
            self._invalidate_pending_scan_callbacks()
            self._set_preflight_scan_input_locked(False)
            if not startup:
                self._reset_ui_to_waiting_state()
                self._update_all_summaries()
                self._update_parked_trays_list()
            return not self._preflight_context_blocks_mutation()
        if action == "CA.TRAY_HOLD" and isinstance(source.get("tray"), dict):
            current = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
            state = source["tray"]
            validate_tray_state(state, default_tray_size=self.TRAY_SIZE)
            expected = source.get("current_sha256")
            if not isinstance(expected, str) or not re.fullmatch(r"[0-9a-f]{64}", expected):
                return False
            archived = current.with_name(f"{current.name}.bad-{expected}")
            if current.is_file():
                if hashlib.sha256(current.read_bytes()).hexdigest() != expected:
                    return False
            elif not archived.is_file() or hashlib.sha256(archived.read_bytes()).hexdigest() != expected:
                return False
            parked = self._parked_store().defer_recovery_state(
                state, worker_name=self.worker_name,
                computer_id=str(getattr(self, "computer_id", "") or ""))
            if ParkedTrayStore.load(parked.path) != state:
                return False
            if current.is_file():
                raw = current.read_bytes()
                if hashlib.sha256(raw).hexdigest() != expected:
                    return False
                preserve_stale_bytes(current, raw)
                moved = self._quarantine_current_tray_state(
                    "admin PIN unverified tray hold", approval=intent,
                    expected_sha256=expected)
                if not moved or hashlib.sha256(Path(moved).read_bytes()).hexdigest() != expected:
                    return False
            if current.exists() or not archived.is_file() or hashlib.sha256(archived.read_bytes()).hexdigest() != expected:
                return False
            clear_active = True
        elif action in {"CA.PAIR_RETRY", "CA.TRAY_HOLD"} and source.get("original_sha256"):
            name = str(source.get("source_file") or self.CURRENT_TRAY_STATE_FILE)
            if Path(name).name != name:
                return False
            current = Path(self.save_folder) / name
            original_sha = str(source["original_sha256"])
            observed_sha = str(source.get("current_sha256") if action == "CA.PAIR_RETRY"
                               else source.get("current_observed_sha256"))
            if not re.fullmatch(r"[0-9a-f]{64}", original_sha) or not re.fullmatch(r"[0-9a-f]{64}", observed_sha):
                return False
            if current.is_file() and hashlib.sha256(current.read_bytes()).hexdigest() != observed_sha:
                return False
            original = current.with_name(f"{current.name}.bad-{original_sha}")
            if not original.is_file():
                original_bytes = getattr(self, "_paired_stale_current_original_bytes", None)
                if original_bytes is not None and hashlib.sha256(original_bytes).hexdigest() == original_sha:
                    preserve_stale_bytes(current, original_bytes)
                elif current.is_file() and hashlib.sha256(current.read_bytes()).hexdigest() == original_sha:
                    preserve_stale_bytes(current, current.read_bytes())
            if not original.is_file() or hashlib.sha256(original.read_bytes()).hexdigest() != original_sha:
                return False
            if current.is_file():
                raw = current.read_bytes()
                if hashlib.sha256(raw).hexdigest() != observed_sha:
                    return False
                preserve_stale_bytes(current, raw)
            changed = current.with_name(f"{current.name}.bad-{observed_sha}")
            if not changed.is_file() or hashlib.sha256(changed.read_bytes()).hexdigest() != observed_sha:
                return False
            self._paired_preflight_store().hold_stale_current(original, changed)
            if current.is_file():
                moved = self._quarantine_current_tray_state(
                    "admin PIN unverified stale current", approval=intent,
                    expected_sha256=observed_sha)
                if not moved or hashlib.sha256(Path(moved).read_bytes()).hexdigest() != observed_sha:
                    return False
            if current.exists():
                return False
            clear_active = True
        elif action == "CA.PAIR_RETRY" and source.get("marker_sha256"):
            store = self._paired_preflight_store()
            marker = store.directory / (str(intent["target"]["id"]) + ".json")
            if not marker.is_file() or hashlib.sha256(marker.read_bytes()).hexdigest() != source["marker_sha256"]:
                return False
            if not read_recovery_file(marker, "stale_hold").verified:
                labels = tuple(intent.get("labels") or ())
                if len(labels) != 2:
                    return False
                store.bind_unidentified_stale(marker, labels)
            return not self._preflight_context_blocks_mutation()
        elif action == "CA.PAIR_RETRY" and source.get("state_sha256"):
            master = str(source.get("master_label_code") or "")
            rows = self._parked_store().enumerate_key_evidence(pair_store=self._paired_preflight_store())
            return bool(master and isinstance(source.get("current"), dict)
                        and source.get("state_sha256") == admin_pin_fingerprint(source["current"])
                        and any(row.kind == "pair" and row.binds(master) for row in rows)
                        and not self._preflight_context_blocks_mutation())
        elif action in {"CA.PAIR_HANDOFF", "CA.TRAY_HOLD"} and source.get("source_audit_id"):
            rows = self._parked_store().enumerate_key_evidence(pair_store=self._paired_preflight_store())
            if not any(row.evidence_id == source["source_audit_id"]
                       and row.content_sha256 == source.get("source_sha256") for row in rows):
                return False
            labels = tuple(intent.get("labels") or ())
            if not labels or not self._log_event(
                    "PHS2_AUDIT_EVIDENCE_UNVERIFIED_HOLD",
                    detail={"source_audit_id": source["source_audit_id"],
                            "source_sha256": source["source_sha256"],
                            "labels": list(labels), "operation_key": intent["operation_key"]},
                    synchronous=True,
                    idempotency_key=f"admin-pin-unverified-evidence:{intent['operation_key']}",
                    deduplicate=True):
                return False
            rows = self._parked_store().enumerate_key_evidence(pair_store=self._paired_preflight_store())
            expected = {canonical_master_label_key(label) for label in labels}
            return bool(any(row.evidence_id == source["source_audit_id"]
                            and row.content_sha256 == source["source_sha256"]
                            and not row.unidentified
                            and {canonical_master_label_key(label) for label in row.labels} == expected
                            for row in rows) and not self._preflight_context_blocks_mutation())
        elif action == "CA.TRAY_HOLD" and source.get("source_file") and source.get("source_sha256"):
            name = str(source["source_file"])
            if Path(name).name != name:
                return False
            path = Path(self.parked_trays_dir) / name
            if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != source["source_sha256"]:
                return False
            label = str(source.get("label") or "")
            if not label or not any(canonical_master_label_key(value) == canonical_master_label_key(label)
                                    for value in intent.get("labels") or ()):
                return False
            rows = self._parked_store().enumerate_key_evidence()
            if any(row.path == path and row.unidentified for row in rows):
                base = path.with_name(name.removesuffix(".manager-hold.json"))
                self._parked_store().bind_invalid_label(base, label)
            rows = self._parked_store().enumerate_key_evidence()
            return bool(any(row.path == path and not row.unidentified and row.binds(label)
                            for row in rows) and not self._preflight_context_blocks_mutation())
        else:
            raise ValueError(f"지원하지 않는 관리자 보류 원본 형식입니다: {action}")
        if clear_active:
            self.current_tray = TraySession()
            self._paired_stale_current_blocked = False
            self._master_preflight_pending = False
            self._preflight_hold_snapshot = None
            self._preflight_hold_draining = False
            self._pending_operator_review_snapshot = None
            self._pending_completion_event_contract = None
            presenter = self._warning_state_presenter()
            completion = presenter.state.completion
            if completion is not None and completion.blocks_completion:
                presenter.resolve_blocking_completion(completion)
            else:
                presenter.clear_completion()
            presenter.acknowledge()
            self._stop_warning_beep()
            self._invalidate_pending_scan_callbacks()
            self._set_preflight_scan_input_locked(False)
            if not startup:
                self.scanned_listbox.delete(0, tk.END)
                self._reset_ui_to_waiting_state()
                self._update_all_summaries()
                self._update_parked_trays_list()
                self._render_warning_state()
                self._update_action_button_states()
            return not self._preflight_context_blocks_mutation()
        return False

    def _admin_pin_finish_unverified_detachment(self, intent: Mapping[str, Any], *, startup: bool = False) -> bool:
        self._admin_pin_detach_startup = startup
        try:
            if not self._admin_pin_check_moves(intent):
                raise OSError("unverified moved original differs")
            if not self._admin_pin_detach_unverified(intent):
                raise OSError("원본 readback 또는 활성 슬롯 해제에 실패했습니다.")
            if intent.get("state") == "UNVERIFIED_DETACHING":
                if not self._admin_pin_audit("ADMIN_PIN_UNVERIFIED_HOLD", intent):
                    raise OSError("관리자 보류 완료 감사를 저장하지 못했습니다.")
                self._admin_pin_store().transition(intent, "UNVERIFIED_OPERATOR_HOLD",
                                                   reason=str(intent.get("reason") or ""))
            return True
        except (OSError, ValueError, TypeError, KeyError, PreflightHoldError,
                PairedHandoffError, TrayStateValidationError) as exc:
            reason = ("관리자 보류 원본 형식을 확인할 수 없습니다."
                      if isinstance(exc, (ValueError, TypeError, KeyError))
                      else "원본 readback 또는 활성 슬롯 해제에 실패했습니다.")
            messagebox.showerror("원본 보류 대기", f"이 건의 보류가 아직 끝나지 않았습니다. {reason}",
                                 parent=getattr(self, "root", None))
            return False
        finally:
            self._admin_pin_detach_startup = False

    def _admin_pin_resume_unverified_detachments(self, *, startup: bool = False) -> None:
        if not getattr(self, "parked_trays_dir", None):
            return
        try:
            intents = self._admin_pin_store().list_pending()
        except (OSError, ValueError, TypeError):
            return
        for intent in intents:
            if intent.get("state") == "APPLIED":
                if self._admin_pin_complete(
                        {"operation_key": intent["operation_key"]},
                        self._admin_pin_recovered_effect):
                    self._admin_pin_release_completed_work(intent, startup=startup)
            elif intent.get("state") in {"UNVERIFIED_DETACHING", "UNVERIFIED_OPERATOR_HOLD"}:
                self._admin_pin_finish_unverified_detachment(intent, startup=startup)

    def _admin_pin_failed(self, intent: Mapping[str, Any], code: str, *, unknown: bool) -> None:
        store = self._admin_pin_store()
        failed = dict(intent, reason=code)
        hold = bool(unknown and messagebox.askyesno(
            "관리자 확인 대기",
            admin_pin_message(code) + "\n\n이 건만 보류하고 다른 작업을 계속하시겠습니까? "
            "아니요를 누르면 같은 건을 다시 확인할 수 있습니다.",
            parent=getattr(self, "root", None),
        ))
        event = "ADMIN_PIN_UNVERIFIED" if unknown else "ADMIN_PIN_REJECTED"
        try:
            if not self._admin_pin_audit(event, failed):
                raise OSError("admin PIN audit unavailable")
            failed = store.transition(failed, "UNVERIFIED_DETACHING" if hold else
                                      "UNKNOWN" if unknown else "REJECTED",
                                      reason=code)
        except (OSError, ValueError):
            messagebox.showerror("관리자 기록 대기", "관리자 확인 기록을 남기지 못했습니다. 원본을 유지합니다.",
                                 parent=getattr(self, "root", None))
            return
        if hold:
            if not self._admin_pin_finish_unverified_detachment(failed):
                return
        messagebox.showwarning("관리자 확인 대기", admin_pin_message(code),
                               parent=getattr(self, "root", None))

    def _admin_pin_approval_for(self, action: str, target_id: str,
                                read_source, labels: tuple[str, ...],
                                effect_readback) -> Optional[Dict[str, str]]:
        """Reserve and consume one PIN for one item before its existing writer."""
        base = self._authorize_blocked_work_supervisor()
        if base is None:
            return None
        active_intent = None
        try:
            operator = {"local_id": operator_local_id(base["operator"]),
                        "login_epoch": base["login_epoch"]}
            store = self._admin_pin_store()
            pending = store.pending(action, target_id)
            retry_intent = None
            retire_intent = None
            retire_reason = ""
            if pending:
                intent = pending[0]
                active_intent = intent
                if intent.get("state") == "TARGET_CHANGED":
                    retire_intent = intent
                    retire_reason = "TARGET_CHANGED"
                    pending = []
            if pending:
                intent = pending[0]
                if intent.get("state") in {"UNVERIFIED_DETACHING", "UNVERIFIED_OPERATOR_HOLD"}:
                    self._admin_pin_finish_unverified_detachment(intent)
                    return None
                if intent.get("state") == "HANDED_OFF_UNKNOWN":
                    messagebox.showwarning("PIN 지원 인계",
                                           "이 건은 원본 효과를 증명할 수 없어 지원 인계 보류 중입니다.",
                                           parent=getattr(self, "root", None))
                    return None
                verification_id = intent.get("verification_id") or ""
                if not verification_id:
                    if self._admin_pin_target_missing(intent):
                        if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", intent):
                            raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
                        store.transition(intent, "HANDED_OFF_UNKNOWN",
                                         reason="UNVERIFIED_DETACHED")
                        return None
                    if intent["operator"] == operator:
                        retry_intent = intent
                    elif intent["operator"].get("local_id") == operator["local_id"]:
                        try:
                            same_source = (admin_pin_fingerprint(read_source()) ==
                                           intent["target"]["state_fingerprint"])
                        except (OSError, ValueError, KeyError, TypeError):
                            same_source = False
                        if not same_source:
                            if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", intent):
                                raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
                            store.transition(intent, "HANDED_OFF_UNKNOWN",
                                             reason="UNVERIFIED_DETACHED")
                            return None
                        retire_intent = intent
                        retire_reason = "LOGIN_EPOCH_CHANGED"
                    else:
                        raise AdminPinError("TARGET_CHANGED", unknown=True)
                else:
                    status = self._admin_pin_client_for_work().status(
                        verification_id, intent["operation_key"])
                    if status == "CONSUMED":
                        intent = self._admin_pin_record_resumer(intent)
                        if not self._admin_pin_check_moves(intent):
                            return None
                        try:
                            effect_complete = effect_readback(intent)
                        except (OSError, ValueError, KeyError, TypeError):
                            effect_complete = False
                        if not effect_complete:
                            try:
                                effect_complete = self._admin_pin_resume_intermediate(intent)
                            except (OSError, ValueError, KeyError, TypeError,
                                    PreflightHoldError, PairedHandoffError):
                                effect_complete = False
                        if effect_complete:
                            intent = store.read(intent["operation_key"])
                            if intent.get("state") != "CONSUMED" or not self._admin_pin_check_moves(intent):
                                return None
                            recovery_approval = {"operation_key": intent["operation_key"]}
                            if not self._admin_pin_complete(recovery_approval, effect_readback):
                                return None
                            self._admin_pin_release_completed_work(intent)
                            messagebox.showinfo("관리자 확인", "같은 요청의 완료 상태를 확인했습니다.",
                                                parent=getattr(self, "root", None))
                            return None
                        if store.read(intent["operation_key"]).get("state") != "CONSUMED":
                            return None
                        try:
                            original = read_source()
                        except (OSError, ValueError, KeyError, TypeError):
                            if self._admin_pin_target_missing(intent):
                                if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", intent):
                                    raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
                                store.transition(intent, "HANDED_OFF_UNKNOWN",
                                                 reason="EFFECT_UNVERIFIED")
                                return None
                            raise
                        source_hash = admin_pin_fingerprint(original)
                        if intent["target"]["state_fingerprint"] != source_hash:
                            self._admin_pin_target_changed(intent)
                            return None
                        if not self._admin_pin_audit(
                                "ADMIN_PIN_CONSUMED", dict(intent, resuming_operator={})):
                            raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
                        return {**base, "supervisor": intent["admin_id"],
                                "verification_id": verification_id,
                                "operation_key": intent["operation_key"], "action": action,
                                "target": target_id}
                    retire_intent = intent
                    retire_reason = status
            original = read_source()
            source_hash = admin_pin_fingerprint(original)
            target = {"kind": action.split(".", 1)[1].lower(),
                      "id": target_id, "state_fingerprint": source_hash}
            credentials = self._prompt_blocked_work_admin_pin(
                action=action, target_id=target_id, labels=tuple(labels))
            if credentials is None:
                return None
            admin_id, pin = credentials
            if retry_intent is not None:
                if (retry_intent["admin_id"] != admin_id or retry_intent["target"] != target
                        or retry_intent["operator"] != operator):
                    raise AdminPinError("TARGET_CHANGED", unknown=True)
                intent = retry_intent
            else:
                if retire_intent is not None:
                    if not self._admin_pin_audit("ADMIN_PIN_SUPERSEDED",
                                                 dict(retire_intent, reason=retire_reason)):
                        raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
                    store.transition(retire_intent, "SUPERSEDED", reason=retire_reason)
                intent = store.write({
                    "schema": "container-admin-pin-intent-v1", "state": "PREPARED",
                    "operation_key": str(uuid.uuid4()), "request_id": str(uuid.uuid4()),
                    "verification_id": "", "admin_id": admin_id, "action": action,
                    "target": target, "operator": operator, "operator_raw": base["operator"],
                    "source_evidence_sha256": source_hash,
                    "source_snapshot": original,
                    "labels": list(labels), "reason": "",
                })
                active_intent = intent
            try:
                if not admin_id or not re.fullmatch(r"[0-9]{6}", pin):
                    raise AdminPinError("PIN_FORMAT_INVALID")
                client = self._admin_pin_client_for_work()
                verified = client.verify(request_id=intent["request_id"], admin_id=admin_id,
                                         pin=pin, action=action, target=target, operator=operator)
                intent = store.write(dict(intent, verification_id=verified["verification_id"],
                                          state="VERIFIED"))
                client.redeem(verification_id=verified["verification_id"],
                              proof=verified["proof"], operation_key=intent["operation_key"],
                              action=action, target=target, operator=operator)
                intent = store.transition(intent, "CONSUMED")
                if read_source() != original:
                    self._admin_pin_target_changed(intent)
                    return None
                if not self._blocked_work_identity_is_current(base):
                    messagebox.showwarning(
                        "관리자 확인 다시 조회", "로그인이 바뀌었습니다. 소비된 원 operation key를 "
                        "보존하고 현재 로그인으로 같은 건을 다시 조회하세요.",
                        parent=getattr(self, "root", None),
                    )
                    return None
                if not self._admin_pin_audit("ADMIN_PIN_CONSUMED", intent):
                    raise AdminPinError("AUDIT_UNAVAILABLE", unknown=True)
                return {**base, "supervisor": admin_id,
                        "verification_id": verified["verification_id"],
                        "operation_key": intent["operation_key"], "action": action,
                        "target": target_id}
            except AdminPinError as exc:
                self._admin_pin_failed(
                    intent, exc.code,
                    unknown=(exc.unknown or exc.code in {
                        "PIN_BUSY", "PIN_RATE_LIMITED", "CENTRAL_ACTION_UNAVAILABLE"}),
                )
                return None
        except (OSError, ValueError, KeyError, TypeError, AdminPinError) as exc:
            code = exc.code if isinstance(exc, AdminPinError) else "VERIFY_UNAVAILABLE"
            if active_intent is not None and isinstance(exc, AdminPinError) and exc.unknown:
                self._admin_pin_failed(active_intent, code, unknown=True)
                return None
            messagebox.showwarning("관리자 확인 대기", admin_pin_message(code),
                                   parent=getattr(self, "root", None))
            return None

    def _admin_pin_complete(self, approval: Mapping[str, str], effect_readback) -> bool:
        intent = None
        try:
            store = self._admin_pin_store()
            intent = store.read(approval["operation_key"])
            if intent.get("state") not in {"CONSUMED", "APPLIED"}:
                raise OSError("admin PIN intent is no longer consumable")
            if not self._admin_pin_check_moves(intent):
                raise OSError("admin PIN moved original differs")
            source = intent.get("source_snapshot") or {}
            held = [(Path(move["target"]), move["sha256"])
                    for move in intent.get("moving") or () if Path(move["target"]).is_file()]
            if source.get("handoff_id") and source.get("record_sha256"):
                held.append((self._paired_preflight_store().directory
                             / str(source["handoff_id"]) / "record.json",
                             source["record_sha256"]))
            if source.get("marker_sha256"):
                held.append((self._paired_preflight_store().directory
                             / (str(intent["target"]["id"]) + ".json"),
                             source["marker_sha256"]))
            if (intent.get("action") == "CA.TRAY_HOLD" and source.get("source_file")
                    and source.get("source_sha256")):
                held.append((Path(self.parked_trays_dir) / str(source["source_file"]),
                             source["source_sha256"]))
            with ExitStack() as stack:
                for path, digest in sorted(set(held), key=lambda item: str(item[0])):
                    stack.enter_context(locked_pinned_source(path, digest))
                if not self._admin_pin_check_moves(intent) or not effect_readback(intent):
                    raise OSError("admin PIN effect readback incomplete")
                if intent.get("state") == "APPLIED":
                    # Only finish cleanup; never replay an already completed effect.
                    if not self._admin_pin_effect_audited("ADMIN_PIN_APPLIED", intent["operation_key"]):
                        raise OSError("admin PIN completion audit unavailable")
                    return True
                if not self._admin_pin_audit("ADMIN_PIN_APPLIED", intent):
                    raise OSError("admin PIN success audit unavailable")
                if not self._admin_pin_check_moves(intent) or not effect_readback(intent):
                    raise OSError("admin PIN effect changed during success audit")
                store.transition(intent, "APPLIED")
            return True
        except (OSError, ValueError, KeyError, TypeError) as exc:
            if isinstance(exc, PinnedTargetChanged) and intent is not None:
                self._admin_pin_check_moves(intent)
            messagebox.showwarning("관리자 확인 대기", "로컬 효과 확인이 불완전합니다. 같은 건을 다시 확인하세요.",
                                   parent=getattr(self, "root", None))
            return False

    def _admin_pin_recovered_effect(self, intent: Mapping[str, Any]) -> bool:
        source = intent.get("source_snapshot")
        if not isinstance(source, dict):
            return False
        action = intent.get("action")
        key = intent.get("operation_key")
        if action == "CA.PRECHECK_HOLD":
            hold = self._admin_pin_preflight_hold_store(intent)
            if hold.path.exists():
                return False
            for path in self._preflight_hold_quarantine_directory().glob(
                    f"preflight_hold_{source.get('preflight_id', '')}_*.json"):
                if (hashlib.sha256(path.read_bytes()).hexdigest() == source.get("hold_sha256")
                        and self._admin_pin_effect_audited("PHS2_PREFLIGHT_HOLD_QUARANTINED", key)):
                    return True
            return False
        if action == "CA.PAIR_HANDOFF" and source.get("handoff_id"):
            path = self._paired_preflight_store().directory / str(source["handoff_id"]) / "record.json"
            store = self._paired_preflight_store()
            if (path.is_file() and (not source.get("record_sha256")
                                    or file_sha256(path) == source["record_sha256"])
                    and store.is_released(path) and store.originals_match(path)
                    and self._admin_pin_effect_audited("PHS2_PAIRED_PREFLIGHT_DEFERRED", key)):
                return True
            marker = read_recovery_file(path.parent / "manager-hold.json", "manager_hold")
            return bool(path.is_file()
                        and (not source.get("record_sha256")
                             or file_sha256(path) == source["record_sha256"])
                        and all((not source.get(name + "_sha256")
                                 or read_recovery_file(path.parent / f"{name}.original", name).sha256
                                 == source[name + "_sha256"])
                                for name in ("hold", "current"))
                        and marker.verified and marker.value["labels"] == intent.get("labels")
                        and self._admin_pin_effect_audited("PHS2_PAIRED_MANUAL_HOLD", key))
        if action == "CA.TRAY_HOLD" and source.get("handoff_id"):
            path = self._paired_preflight_store().directory / str(source["handoff_id"]) / "record.json"
            return bool(path.is_file() and file_sha256(path) == source.get("record_sha256")
                        and self._admin_pin_effect_audited("PHS2_PAIRED_RECOVERY_DEFERRED", key))
        if action == "CA.TRAY_HOLD" and isinstance(source.get("tray"), dict):
            labels = intent.get("labels") or ()
            parked = self._parked_store().existing_label_path_any_worker(
                master_label=str(labels[0])) if labels else None
            current = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
            return bool(parked and not current.exists()
                        and ParkedTrayStore.load(parked) == source["tray"]
                        and self._admin_pin_effect_audited("TRAY_PARKED", key))
        if action == "CA.TRAY_HOLD" and source.get("original_sha256"):
            marker = self._paired_preflight_store().directory / (
                f"stale-current-{source['original_sha256']}.json")
            result = read_recovery_file(marker, "stale_hold")
            return bool(result.verified
                        and result.value["original_sha256"] == source["original_sha256"]
                        and result.value["changed_sha256"] == source.get("current_observed_sha256")
                        and self._admin_pin_effect_audited(
                            "PHS2_PAIRED_STALE_CURRENT_DEFERRED", key))
        if source.get("source_audit_id"):
            event = "PHS2_AUDIT_EVIDENCE_BOUND"
            if not self._admin_pin_effect_audited(event, key):
                return False
            rows = self._parked_store().enumerate_key_evidence(
                pair_store=self._paired_preflight_store())
            expected = {canonical_master_label_key(value) for value in intent.get("labels", ())}
            return any(row.evidence_id == source["source_audit_id"]
                       and row.content_sha256 == source.get("source_sha256")
                       and not row.unidentified
                       and {canonical_master_label_key(value) for value in row.labels} == expected
                       for row in rows)
        if source.get("source_file") and action == "CA.TRAY_HOLD":
            if not self._admin_pin_effect_audited("PHS2_DAMAGED_PARKED_DEFERRED", key):
                return False
            path = Path(self.parked_trays_dir) / str(source["source_file"])
            if not path.is_file() or file_sha256(path) != source.get("source_sha256"):
                return False
            rows = self._parked_store().enumerate_key_evidence()
            return any(row.kind in {"parked_marker", "parked_identified"}
                       and row.content_sha256 == source.get("source_sha256")
                       and row.binds(source.get("label", "")) for row in rows)
        if source.get("marker_sha256") and action == "CA.PAIR_RETRY":
            marker = self._paired_preflight_store().directory / (
                str(intent["target"]["id"]) + ".json")
            if (not marker.is_file() or hashlib.sha256(marker.read_bytes()).hexdigest()
                    != source["marker_sha256"]):
                return False
            first = read_recovery_file(marker, "stale_hold")
            bound = first.verified or read_recovery_file(
                self._paired_preflight_store().stale_manager_path(marker), "manager_hold").verified
            return bool(bound and self._admin_pin_effect_audited(
                "PHS2_STALE_HOLD_RECHECKED", key))
        if source.get("original_sha256") and action == "CA.PAIR_RETRY":
            current = Path(self.save_folder) / str(source.get("source_file") or self.CURRENT_TRAY_STATE_FILE)
            copies = list(current.parent.glob(current.name + ".bad-*"))
            if source.get("preserved_file"):
                copies.append(current.with_name(source["preserved_file"]))
            return bool(not current.exists()
                        and any(path.is_file() and read_recovery_file(path, "stale").sha256
                                == source["original_sha256"] for path in copies)
                        and self._admin_pin_effect_audited(
                            "PHS2_PAIRED_STALE_CURRENT_PRESERVATION_REQUESTED", key))
        for event in ("PHS2_PAIRED_RECEIPT_RECHECK_REQUESTED",
                      "PHS2_PAIRED_RECOVERY_DEFERRED"):
            if self._admin_pin_effect_audited(event, key):
                return True
        return False

    def _finish_preflight_handoff(self, *, paired: bool = False, startup: bool = False) -> None:
        self._preflight_hold_snapshot = None
        self._preflight_hold_draining = False
        self._master_preflight_pending = False
        if paired:
            self.current_tray = TraySession()
            self._invalidate_pending_scan_callbacks()
        self._set_preflight_scan_input_locked(False)
        if paired and not startup:
            self._reset_ui_to_waiting_state()
            self._update_all_summaries()
            self._update_parked_trays_list()
            self._update_action_button_states()

    def _admin_pin_release_completed_work(self, intent: Mapping[str, Any], *, startup: bool = False) -> None:
        """Apply normal completion cleanup only to this recovered active owner."""
        source = intent.get("source_snapshot") or {}
        action = intent.get("action")
        if not ((action == "CA.PRECHECK_HOLD" and source.get("hold_sha256"))
                or (action == "CA.PAIR_HANDOFF" and source.get("handoff_id"))
                or (action == "CA.TRAY_HOLD" and isinstance(source.get("tray"), dict))):
            return
        current = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
        hold = (self._admin_pin_preflight_hold_store(intent)
                if action == "CA.PRECHECK_HOLD" else self._preflight_hold_store())
        if hold.path.exists() or current.exists():
            return
        snapshot = getattr(self, "_preflight_hold_snapshot", None)
        master = str(getattr(getattr(self, "current_tray", None), "master_label_code", "") or "")
        labels = {canonical_master_label_key(label) for label in intent.get("labels") or ()}
        if master and canonical_master_label_key(master) not in labels:
            return
        if snapshot is not None:
            if action == "CA.PRECHECK_HOLD":
                if snapshot.preflight_id != source.get("preflight_id"):
                    return
            elif canonical_master_label_key(snapshot.master_raw) not in labels:
                return
        if action == "CA.PRECHECK_HOLD" and source.get("hold_sha256"):
            self._finish_preflight_handoff(startup=startup)
            if not startup:
                self._update_parked_trays_list()
                self._schedule_startup_transfer_recovery()
        elif action == "CA.PAIR_HANDOFF" and source.get("handoff_id"):
            self._finish_preflight_handoff(paired=True, startup=startup)
        elif action == "CA.TRAY_HOLD" and isinstance(source.get("tray"), dict):
            self.current_tray = TraySession()
            self._finish_blocked_current_tray_handoff(startup=startup)

    def _admin_pin_resume_intermediate(self, intent: Mapping[str, Any]) -> bool:
        """Finish only an original-byte-preserving, consumed local write."""
        source = intent.get("source_snapshot") or {}
        if not isinstance(source, dict):
            return False
        action = intent.get("action")
        if action not in {"CA.PRECHECK_HOLD", "CA.PAIR_HANDOFF", "CA.TRAY_HOLD"}:
            return False
        base = self._authorize_blocked_work_supervisor()
        if base is None:
            return False
        intent = self._admin_pin_record_resumer(intent)
        approval = {**base, "supervisor": intent["admin_id"],
                    "verification_id": intent["verification_id"],
                    "operation_key": intent["operation_key"], "action": action,
                    "target": intent["target"]["id"]}
        if action == "CA.PAIR_HANDOFF" and source.get("handoff_id"):
            store = self._paired_preflight_store()
            path = store.directory / str(source["handoff_id"]) / "record.json"
            if (not path.is_file() or (source.get("record_sha256")
                                      and file_sha256(path) != source["record_sha256"])):
                if self._admin_pin_restore_moves(intent):
                    self._admin_pin_target_changed(intent)
                return False
            for name in ("hold", "current"):
                store.move_original(
                    path, name, expected_sha256=source[name + "_sha256"],
                    move=lambda original, held, digest: self._admin_pin_move(
                        approval, original, held, digest),
                )
            store.release(path)
            return self._admin_pin_recovered_effect(intent)
        if action == "CA.TRAY_HOLD" and isinstance(source.get("tray"), dict):
            current = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
            archived = next((Path(move["target"]) for move in intent.get("moving") or ()
                             if move.get("source") == str(current.resolve())), None)
            if (current.exists() or archived is None or not archived.is_file()
                    or file_sha256(archived) != source.get("current_sha256")):
                return False
            if not self._defer_saved_recovery_state(
                    source["tray"], reason="supervisor_unsettled_tray_handoff",
                    approval=approval, already_moved=True):
                return False
            return self._admin_pin_recovered_effect(intent)
        if action == "CA.PRECHECK_HOLD" and source.get("hold_sha256"):
            hold = self._admin_pin_preflight_hold_store(intent)
            if hold.path.exists():
                return False
            for path in self._preflight_hold_quarantine_directory().glob(
                    f"preflight_hold_{source.get('preflight_id', '')}_*.json"):
                if hashlib.sha256(path.read_bytes()).hexdigest() != source["hold_sha256"]:
                    continue
                snapshot = hold.load_path(path)
                snapshot_hash = hold.snapshot_hash(snapshot)
                detail = self._preflight_hold_ownership_detail(
                    snapshot, snapshot_hash=snapshot_hash,
                    reason="admin_pin_consumed_recovery", quarantine_path=path)
                detail.update(self._blocked_work_audit_identity(approval))
                if not self._admin_pin_effect_audited("PHS2_PREFLIGHT_HOLD_QUARANTINED",
                                                     intent["operation_key"]):
                    if not self._log_event(
                            "PHS2_PREFLIGHT_HOLD_QUARANTINED", detail=detail,
                            synchronous=True,
                            idempotency_key=(f"preflight-hold-quarantine:"
                                             f"{snapshot.preflight_id}:{snapshot_hash}"),
                            deduplicate=True):
                        return False
                if not self._admin_pin_recovered_effect(intent):
                    return False
                return True
            return False
        if action == "CA.TRAY_HOLD" and source.get("original_sha256"):
            current = Path(self.save_folder) / str(source.get("source_file") or self.CURRENT_TRAY_STATE_FILE)
            if current.exists():
                return False
            copies = [path for path in current.parent.glob(current.name + ".bad-*") if path.is_file()]
            first = next((path for path in copies if read_recovery_file(path, "stale").sha256
                          == source["original_sha256"]), None)
            second = next((path for path in copies if read_recovery_file(path, "stale").sha256
                           == source.get("current_observed_sha256")), None)
            if first is None or second is None:
                return False
            if not self._admin_pin_effect_audited("PHS2_PAIRED_STALE_CURRENT_DEFERRED",
                                                 intent["operation_key"]):
                if not self._log_event(
                        "PHS2_PAIRED_STALE_CURRENT_DEFERRED",
                        detail={"reason": "admin_pin_consumed_recovery",
                                "source_file": current.name,
                                "preserved_file": first.name,
                                "changed_file": second.name,
                                "original_sha256": source["original_sha256"],
                                **self._blocked_work_audit_identity(approval)},
                        synchronous=True,
                        idempotency_key=f"paired-stale-current:{source['original_sha256']}:{intent['operation_key']}",
                        deduplicate=True):
                    return False
            self._paired_preflight_store().hold_stale_current(first, second)
            if not self._admin_pin_recovered_effect(intent):
                return False
            self._paired_stale_current_blocked = False
            self._set_preflight_scan_input_locked(False)
            return True
        return False

    def _admin_pin_target_missing(self, intent: Mapping[str, Any]) -> bool:
        source = intent.get("source_snapshot")
        if not isinstance(source, dict):
            return True
        action = intent.get("action")
        if action == "CA.PRECHECK_HOLD":
            return not self._admin_pin_preflight_hold_store(intent).path.is_file()
        if source.get("handoff_id"):
            return not (self._paired_preflight_store().directory
                        / str(source["handoff_id"]) / "record.json").is_file()
        if source.get("source_file"):
            base = (Path(self.parked_trays_dir) if action == "CA.TRAY_HOLD"
                    and source.get("source_sha256") else Path(self.save_folder))
            return not (base / str(source["source_file"])).is_file()
        if source.get("marker_sha256"):
            return not (self._paired_preflight_store().directory
                        / (str(intent["target"]["id"]) + ".json")).is_file()
        if source.get("source_audit_id"):
            rows = self._parked_store().enumerate_key_evidence(
                pair_store=self._paired_preflight_store())
            return not any(row.evidence_id == source["source_audit_id"] for row in rows)
        if action == "CA.TRAY_HOLD" and "tray" in source:
            return not (Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE).is_file()
        return False

    def _recheck_admin_pin_intents(self) -> None:
        store = self._admin_pin_store()
        try:
            intents = store.list_pending()
        except (OSError, ValueError, TypeError):
            messagebox.showerror("관리자 확인 다시 조회", "PIN 보류 기록을 읽지 못했습니다. 원본을 보존하고 지원 인계하세요.",
                                 parent=getattr(self, "root", None))
            return
        if not intents:
            messagebox.showinfo("관리자 확인 다시 조회", "다시 확인할 관리자 PIN 요청이 없습니다.",
                                parent=getattr(self, "root", None))
            return
        for intent in intents:
            action = intent.get("action")
            if (action == "CA.PRECHECK_HOLD" and intent.get("state") == "APPLIED"
                    and (intent.get("restoration") or {}).get("state") == "RESTORING"):
                self.restore_quarantined_preflight_hold(intent["restoration"]["source"])
                continue
            if intent.get("state") == "APPLIED":
                if self._admin_pin_complete(
                        {"operation_key": intent["operation_key"]},
                        self._admin_pin_recovered_effect):
                    self._admin_pin_release_completed_work(intent)
                    messagebox.showinfo("관리자 확인 완료", "같은 key의 완료 효과와 입력 정리를 확인했습니다.",
                                        parent=getattr(self, "root", None))
                continue
            if intent.get("state") == "HANDED_OFF_UNKNOWN":
                messagebox.showwarning("PIN 지원 인계",
                                       "이 건의 원 key와 원본은 지원 인계 보류 중입니다.",
                                       parent=getattr(self, "root", None))
                continue
            if intent.get("state") == "TARGET_CHANGED":
                messagebox.showinfo(
                    "관리자 확인 다시 조회",
                    "원본 변경을 확인했습니다. 같은 동작을 다시 선택해 바뀐 원본으로 새 PIN을 받으세요.",
                    parent=getattr(self, "root", None),
                )
                continue
            if intent.get("state") in {"UNVERIFIED_DETACHING", "UNVERIFIED_OPERATOR_HOLD"}:
                if not self._admin_pin_finish_unverified_detachment(intent):
                    continue
                intent = store.read(intent["operation_key"])
            labels = intent.get("labels") or ()
            detail = (f"동작: {action}\n현품표: {', '.join(labels) or '확인 필요'}\n"
                      f"상태: {intent.get('state')} · 원인: {intent.get('reason') or '확인 대기'}")
            if not messagebox.askyesno(
                    "관리자 확인 다시 조회", detail + "\n\n이 요청의 서버 상태를 다시 확인할까요?",
                    parent=getattr(self, "root", None)):
                continue
            try:
                verification_id = intent.get("verification_id") or ""
                if not verification_id:
                    if self._admin_pin_target_missing(intent):
                        if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", intent):
                            raise OSError("admin PIN handoff audit failed")
                        store.transition(intent, "HANDED_OFF_UNKNOWN",
                                         reason="UNVERIFIED_DETACHED")
                        continue
                    current = self._authorize_blocked_work_supervisor()
                    current_operator = ({"local_id": operator_local_id(current["operator"]),
                                         "login_epoch": current["login_epoch"]}
                                        if current else None)
                    if current_operator != intent["operator"]:
                        if self._admin_pin_target_missing(intent):
                            if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", intent):
                                raise OSError("admin PIN handoff audit failed")
                            store.transition(intent, "HANDED_OFF_UNKNOWN",
                                             reason="UNVERIFIED_DETACHED")
                        else:
                            if not self._admin_pin_audit("ADMIN_PIN_SUPERSEDED",
                                                         dict(intent, reason="LOGIN_EPOCH_CHANGED")):
                                raise OSError("admin PIN supersession audit failed")
                            store.transition(intent, "SUPERSEDED",
                                             reason="LOGIN_EPOCH_CHANGED")
                        continue
                    credentials = self._prompt_blocked_work_admin_pin(
                        action=action, target_id=intent["target"]["id"], labels=tuple(labels))
                    if credentials is None:
                        continue
                    admin_id, secret = credentials
                    if admin_id != intent["admin_id"]:
                        raise AdminPinError("TARGET_CHANGED")
                    verified = self._admin_pin_client_for_work().verify(
                        request_id=intent["request_id"], admin_id=admin_id, pin=secret,
                        action=action, target=intent["target"], operator=intent["operator"])
                    intent = store.write(dict(intent, verification_id=verified["verification_id"],
                                              state="VERIFIED"))
                    verification_id = verified["verification_id"]
                status = self._admin_pin_client_for_work().status(
                    verification_id, intent["operation_key"])
                if status == "CONSUMED":
                    intent = self._admin_pin_record_resumer(intent)
                    if not self._admin_pin_check_moves(intent):
                        continue
                    if (self._admin_pin_recovered_effect(intent)
                            or self._admin_pin_resume_intermediate(intent)):
                        intent = store.read(intent["operation_key"])
                        if intent.get("state") != "CONSUMED" or not self._admin_pin_check_moves(intent):
                            continue
                        if not self._admin_pin_complete(
                                {"operation_key": intent["operation_key"]},
                                self._admin_pin_recovered_effect):
                            continue
                        self._admin_pin_release_completed_work(intent)
                        messagebox.showinfo("관리자 확인 완료", "같은 key의 로컬 효과 전체를 확인했습니다.",
                                            parent=getattr(self, "root", None))
                    else:
                        if self._admin_pin_target_missing(intent):
                            if not self._admin_pin_audit("ADMIN_PIN_HANDOFF_UNKNOWN", intent):
                                raise OSError("admin PIN handoff audit failed")
                            store.transition(intent, "HANDED_OFF_UNKNOWN", reason="EFFECT_UNVERIFIED")
                        messagebox.showwarning(
                            "관리자 확인 계속 필요",
                            "같은 key의 효과가 확인되지 않았습니다. 원래 동작에서 같은 건을 다시 확인하거나 "
                            "PIN 지원 인계로 보류하고 다른 작업을 계속하세요.",
                            parent=getattr(self, "root", None),
                        )
                else:
                    if not self._admin_pin_audit("ADMIN_PIN_SUPERSEDED",
                                                 dict(intent, reason=status)):
                        raise OSError("admin PIN supersession audit failed")
                    store.transition(intent, "SUPERSEDED", reason=status)
                    messagebox.showinfo("관리자 확인 다시 필요", "기존 요청을 보존했습니다. 원본을 재조회한 뒤 새 PIN 확인을 받으세요.",
                                        parent=getattr(self, "root", None))
            except (AdminPinError, OSError, ValueError, KeyError, TypeError,
                    PreflightHoldError, PairedHandoffError) as exc:
                code = exc.code if isinstance(exc, AdminPinError) else "VERIFY_UNAVAILABLE"
                messagebox.showwarning("관리자 확인 대기", admin_pin_message(code),
                                       parent=getattr(self, "root", None))

    def _blocked_work_identity_is_current(self, approval: Mapping[str, str]) -> bool:
        if not isinstance(approval, Mapping):
            return False
        operator = str(getattr(self, "worker_name", "") or "").strip()
        role = str(getattr(self, "worker_role", "") or "").upper()
        valid = bool(
            approval.get("operator") == operator
            and approval.get("role") == role
            and approval.get("login_epoch", "") == getattr(self, "_admin_pin_login_epoch", "")
            and (
                (role == "ADMIN" and operator == PROTECTED_ADMIN_OPERATOR_ID
                 and getattr(self, "_authenticated_protected_admin", False))
                or (role == "WORKER" and operator != PROTECTED_ADMIN_OPERATOR_ID)
            )
        )
        return valid

    def _blocked_work_identity_matches(self, approval: Mapping[str, str]) -> bool:
        valid = self._blocked_work_identity_is_current(approval)
        if not valid:
            messagebox.showwarning(
                "관리자 확인 다시 필요",
                "로그인 작업자 또는 역할이 바뀌었습니다. 원본은 그대로 두고 다시 관리자 확인을 받으세요.",
                parent=getattr(self, "root", None),
            )
        return valid

    @staticmethod
    def _blocked_work_audit_identity(approval: Mapping[str, str]) -> Dict[str, str]:
        detail = {
            "acting_worker": persistent_operator_name(approval["operator"]),
            "acting_role": approval["role"],
            "approving_supervisor": persistent_operator_name(approval["supervisor"]),
            "approving_role": "ADMIN",
        }
        if approval.get("verification_id"):
            detail.update({"verification_id": approval["verification_id"],
                           "operation_key": approval["operation_key"],
                           "action": approval["action"], "target": approval["target"]})
        return detail

    def _quarantine_preflight_hold_from_operations(self) -> bool:
        if self._offline_preflight_quarantine_blocked():
            self._show_preflight_offline_notice()
            return False
        approval = self._authorize_blocked_work_supervisor()
        if approval is None:
            return False
        return self._quarantine_preflight_hold_for_supervisor(
            reason="supervisor_new_work_required", approval=approval,
        )

    @_recovery_item_firewall
    def _defer_paired_preflight_from_operations(self) -> bool:
        approval = self._authorize_blocked_work_supervisor()
        if approval is None or not self._blocked_work_identity_matches(approval):
            return False
        store = self._paired_preflight_store()
        try:
            path = store.pending_path()
            if path is not None:
                changed_intents = self._admin_pin_store().pending("CA.PAIR_HANDOFF", path.parent.name)
                if any(row.get("state") == "TARGET_CHANGED" for row in changed_intents):
                    old = store.read(path)
                    originals = {name: Path(old[name]["path"]) for name in ("hold", "current")}
                    if (all(original.is_file() for original in originals.values())
                            and any(file_sha256(originals[name]) != old[name]["sha256"]
                                    for name in originals)):
                        store.supersede_changed_record(path)
                        for changed_intent in changed_intents:
                            if changed_intent.get("state") == "TARGET_CHANGED":
                                self._admin_pin_store().transition(
                                    changed_intent, "SUPERSEDED", reason="REBOUND_RECORD")
                        path = None
            if path is None:
                hold = self._preflight_hold_store().load()
                current_path = Path(self.save_folder) / self.CURRENT_TRAY_STATE_FILE
                current_read = read_recovery_file(current_path, "current", tray_size=self.TRAY_SIZE)
                if not current_read.verified:
                    raise PairedHandoffError("current original cannot be verified")
                current = current_read.value
                if hold.state != HOLD_DRAINING or not current.get("master_label_code"):
                    raise PairedHandoffError("paired originals are unavailable")
                if self._preflight_hold_matches_current_tray(hold):
                    raise PairedHandoffError("matching draining hold must use normal recovery")
                if not messagebox.askyesno(
                    "두 원본 보류 확인",
                    "제품 반영 중 보류 입력과 현재 트레이가 다릅니다. 두 원본을 함께 "
                    "보류하고 다른 현품표 작업을 계속하시겠습니까? 원 현품표는 계속 잠깁니다.",
                    parent=getattr(self, "root", None),
                ):
                    return False
                if not self._blocked_work_identity_matches(approval):
                    return False
                path = store.prepare(self._preflight_hold_store().path, current_path)
            record = store.read(path)
            held = json.loads(store._bytes(record["hold"]).decode("utf-8"))
            current = json.loads(store._bytes(record["current"]).decode("utf-8"))
            if held.get("state") != HOLD_DRAINING:
                raise PairedHandoffError("paired hold state differs")

            def source():
                saved = store.read(path)
                observed = {}
                for name in ("hold", "current"):
                    original = Path(saved[name]["path"])
                    archived = path.parent / f"{name}.original"
                    candidate = archived if archived.exists() else original
                    observed[name] = hashlib.sha256(candidate.read_bytes()).hexdigest()
                return {"handoff_id": saved["id"],
                        "record_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                        "hold_sha256": observed["hold"],
                        "current_sha256": observed["current"],
                        "labels": [held.get("master_raw"), current.get("master_label_code")]}

            def effect(_intent):
                return bool(file_sha256(path) == _intent["source_snapshot"]["record_sha256"]
                            and store.is_released(path) and store.originals_match(path))

            resuming = self._admin_pin_store().pending("CA.PAIR_HANDOFF", str(record["id"]))
            pin_approval = self._admin_pin_approval_for(
                "CA.PAIR_HANDOFF", str(record["id"]), source,
                tuple(label for label in (held.get("master_raw"), current.get("master_label_code"))
                      if isinstance(label, str) and label), effect,
            )
            if pin_approval is None:
                return any(self._admin_pin_store().read(row["operation_key"])["state"] == "APPLIED"
                           for row in resuming)
            approval = pin_approval
            detail = {
                "contract_version": record["schema"],
                "handoff_id": record["id"],
                "hold_master": held.get("master_raw"),
                "current_master": current.get("master_label_code"),
                "hold_worker": held.get("worker"),
                "current_worker": current.get("worker_name"),
                "hold_state": held.get("state"),
                "current_state": "CURRENT_UNSETTLED",
                "hold_count": len(held.get("items") or []),
                "current_count": len(current.get("scanned_barcodes") or []),
                "hold_sha256": record["hold"]["sha256"],
                "current_sha256": record["current"]["sha256"],
            }
            detail.update(self._blocked_work_audit_identity(approval))
            if not self._blocked_work_identity_matches(approval):
                return False
            if not self._log_event(
                "PHS2_PAIRED_PREFLIGHT_DEFERRED", detail=detail, synchronous=True,
                idempotency_key=f"paired-preflight:{record['id']}", deduplicate=True,
            ):
                raise PairedHandoffError("paired handoff audit failed")
            if not self._blocked_work_identity_matches(approval):
                return False
            pin_intent = self._admin_pin_store().read(approval["operation_key"])
            pin_source = pin_intent["source_snapshot"]
            if file_sha256(path) != pin_source["record_sha256"]:
                self._admin_pin_target_changed(pin_intent)
                return False
            for name in ("hold", "current"):
                store.move_original(
                    path, name, expected_sha256=pin_source[name + "_sha256"],
                    move=lambda original, held, digest: self._admin_pin_move(
                        approval, original, held, digest),
                )
            store.release(path)
            if not self._admin_pin_complete(approval, effect):
                return False
        except (OSError, ValueError, TypeError, PairedHandoffError, PreflightHoldError, TrayStateValidationError) as exc:
            print(f"짝 원본 보류 실패: {exc.__class__.__name__}: {exc}")
            self._set_preflight_scan_input_locked(True)
            messagebox.showerror(
                "두 원본 보류 대기",
                "두 원본을 모두 확인하지 못했습니다. 원래 잠금을 유지합니다. "
                "관리자 인계 목록에서 같은 건을 다시 확인하세요.",
                parent=getattr(self, "root", None),
            )
            return False
        self._finish_preflight_handoff(paired=True)
        self.show_status_message(
            "두 원본을 관리자 보류 목록으로 옮겼습니다. 다른 현품표 작업을 계속하세요.",
            self.COLOR_PRIMARY, duration=0,
        )
        return True

    def _show_blocked_work_handoff(self) -> None:
        tray = getattr(self, "current_tray", None)
        current_master = str(getattr(tray, "master_label_code", "") or "")
        current_worker = persistent_operator_name(str(getattr(self, "worker_name", "") or ""))
        current_count = len(getattr(tray, "scanned_barcodes", []) or [])
        hold_line = "보류 원본: 없음"
        if self._preflight_context_blocks_mutation():
            try:
                held = self._preflight_hold_store().load()
                hold_line = (
                    f"보류 원본: {held.master_raw}\n"
                    f"작업자: {display_operator_name(held.worker)} · 상태: {held.state} · "
                    f"남은 입력: {len(held.items)}건"
                )
            except PreflightHoldError:
                hold_line = "보류 원본: 읽을 수 없음 · 관리자 확인 필요"
        messagebox.showinfo(
            "미확정 작업 인계",
            f"{hold_line}\n\n현재 트레이: {current_master or '없음'}\n"
            f"작업자: {display_operator_name(current_worker)} · 상태: 미확정 · "
            f"스캔 입력: {current_count}건\n\n"
            "관리자에게 이 PC의 보류 파일·현재 트레이 상태·원 중앙 요청/영수증을 "
            "함께 대조해 달라고 알리세요. 원본을 지우거나 새 현품표·요청 키로 "
            "다시 처리하지 마세요.",
            parent=getattr(self, "root", None),
        )

    @_recovery_item_firewall
    def _show_paired_preflight_handoffs(self) -> None:
        approval = self._authorize_blocked_work_supervisor()
        if approval is None or not self._blocked_work_identity_matches(approval):
            return
        store = self._paired_preflight_store()
        evidence = self._parked_store().enumerate_key_evidence(pair_store=store)
        directory_errors = tuple(row for row in evidence if row.kind == "directory_error")
        for row in directory_errors:
            messagebox.showwarning(
                "보류 폴더 다시 확인", f"{row.path.name}: {row.problem}\n"
                "확인된 현품표만 계속 보류합니다. 다른 현품표는 작업할 수 있습니다. "
                "잠시 뒤 이 목록을 다시 열어 확인하세요.", parent=self.root)
        paths = tuple(row.path for row in evidence if row.kind == "pair")
        stale_entries = tuple((row.path, read_recovery_file(row.path, "stale_hold"))
                              for row in evidence if row.kind == "stale")
        stale_current_entries = tuple(row for row in evidence if row.kind == "stale_current")
        physical_keys = {canonical_master_label_key(label)
                         for row in evidence if row.kind != "audit" for label in row.labels}
        audit_entries = tuple(row for row in evidence if row.kind == "audit"
                              and (row.unidentified or any(
                                  canonical_master_label_key(label) not in physical_keys
                                  for label in row.labels)))
        temp_entries = tuple(row for row in evidence if row.kind == "atomic_temp")
        preflight_entries = tuple(row for row in evidence if row.kind in {"preflight_quarantine", "precheck_pin"})
        active_stale = bool(getattr(self, "_paired_stale_current_blocked", False))
        if not paths and not stale_entries and not stale_current_entries and not temp_entries and not audit_entries and not preflight_entries and not active_stale and not directory_errors:
            messagebox.showinfo("두 원본 보류 목록", "인계된 두 원본 묶음이 없습니다.", parent=self.root)
            return
        for row in preflight_entries:
            if not self._blocked_work_identity_matches(approval):
                return
            if row.kind == "precheck_pin":
                # The physical row owns restoration; the intent also survives a missing original.
                if not any(set(row.labels) & set(other.labels) for other in preflight_entries
                           if other.kind == "preflight_quarantine"):
                    messagebox.showwarning("사전조회 격리 원본 확인",
                                           "격리 원본을 찾지 못했습니다. 이 현품표는 계속 보류합니다. "
                                           "원본과 복원 기록을 다시 확인하세요.", parent=self.root)
                continue
            if not row.problem and not row.unidentified:
                self.restore_quarantined_preflight_hold(str(row.path))
            elif row.evidence_id and messagebox.askyesno(
                    "사전조회 격리 원본 확인",
                    f"{row.path.name}: {row.problem or '현품표 확인 필요'}\n"
                    "원 현품표를 중앙에서 확인하고 이 건만 보류할까요?", parent=self.root):
                self._identify_unreadable_audit(row.evidence_id, approval,
                                                label_count=1, known_labels=row.labels)
            else:
                messagebox.showwarning("사전조회 격리 원본 확인",
                                       "원본을 읽지 못했습니다. 원본을 보존하고 다시 확인하세요.", parent=self.root)
        for path in paths:
            if not self._blocked_work_identity_matches(approval):
                return
            try:
                inspection = store.inspect(path)
                record = inspection.record
                held_read = inspection.hold_read
                current_read = inspection.current_read
                held = held_read.value if held_read.verified else None
                current = current_read.value if current_read.verified else None
                if record is not None:
                    held = held or json.loads(store._bytes(record["hold"]).decode("utf-8"))
                    current = current or json.loads(store._bytes(record["current"]).decode("utf-8"))
                problems = list(inspection.problems)
                if not inspection.released:
                    problems.append("인계가 끝나지 않음")
                if inspection.unidentified:
                    problems.append("원 현품표 두 장을 확인할 수 없음")
                if inspection.released and problems:
                    problems.insert(0, "원본 파일 재대조 필요")
                status = " · ".join(problems) if problems else "관리자 보류"
                detail = (
                    f"묶음: {path.parent.name}\n상태: {status}\n"
                    f"보류 원본: {(held or {}).get('master_raw') or '확인 필요'} · 작업자: {(held or {}).get('worker') or '확인 필요'}\n"
                    f"상태: {(held or {}).get('state') or '확인 필요'} · 남은 입력: {len((held or {}).get('items') or [])}건\n"
                    f"현재 원본: {(current or {}).get('master_label_code') or '확인 필요'} · 작업자: {(current or {}).get('worker_name') or '확인 필요'}\n"
                    f"스캔 입력: {len((current or {}).get('scanned_barcodes') or [])}건\n"
                    f"원 현품표 후보: {', '.join(inspection.labels) or '없음'}\n"
                    f"보류 원본 SHA256: {held_read.sha256 or '읽기 실패'}\n"
                    f"현재 원본 SHA256: {current_read.sha256 or '읽기 실패'}"
                )
            except Exception as exc:
                print(f"인계 묶음 목록 확인 실패: {path.parent.name}: {exc.__class__.__name__}")
                continue
            if messagebox.askyesno(
                "두 원본 보류 목록", detail + "\n\n원 요청 결과를 같은 키로 다시 확인할까요?",
                parent=self.root,
            ):
                if self._blocked_work_identity_matches(approval):
                    if current is not None:
                        current_source = path.parent / "current.original"
                        if not current_source.is_file() and record is not None:
                            current_source = Path(record["current"]["path"])
                        self._recheck_paired_preflight_receipt(
                            current, approval=approval, source_path=current_source)
                    else:
                        self._identify_unreadable_pair(path, approval)
            elif problems and messagebox.askyesno(
                "이 묶음만 보류", detail + "\n\n이 묶음만 보류하고 다른 현품표를 계속할까요?",
                parent=self.root,
            ):
                if inspection.unidentified:
                    self._identify_unreadable_pair(path, approval)
                elif self._blocked_work_identity_matches(approval):
                    try:
                        def source():
                            saved = store.read(path)
                            return {"handoff_id": path.parent.name,
                                    "record_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                                    "hold_sha256": saved["hold"]["sha256"],
                                    "current_sha256": saved["current"]["sha256"],
                                    "problems": list(inspection.problems)}

                        def effect(intent):
                            return bool(file_sha256(path) == intent["source_snapshot"]["record_sha256"]
                                        and self._admin_pin_effect_audited(
                                            "PHS2_PAIRED_RECOVERY_DEFERRED", intent["operation_key"]))

                        pin_approval = self._admin_pin_approval_for(
                            "CA.TRAY_HOLD", path.parent.name, source,
                            tuple(inspection.labels), effect)
                        if pin_approval is None:
                            continue
                        with self._admin_pin_locked_sources(pin_approval, [
                                (path, self._admin_pin_store().read(pin_approval["operation_key"])
                                 ["source_snapshot"]["record_sha256"])]):
                            audited = self._log_event(
                                "PHS2_PAIRED_RECOVERY_DEFERRED",
                                detail={"handoff_id": path.parent.name,
                                        "reason": status,
                                        **self._blocked_work_audit_identity(pin_approval)},
                                synchronous=True,
                                idempotency_key=f"paired-recovery-defer:{path.parent.name}:{uuid.uuid4().hex}",
                                deduplicate=True,
                            )
                            if not audited:
                                raise PairedHandoffError("paired recovery defer audit failed")
                            self._admin_pin_complete(pin_approval, effect)
                    except Exception:
                        messagebox.showerror("보류 기록 대기", "감사 기록을 남기지 못했습니다. 이 묶음은 계속 보류합니다.", parent=self.root)
        if active_stale and self._blocked_work_identity_matches(approval):
            source = Path(str(getattr(self, "_paired_stale_current_path", "") or ""))
            latest = read_recovery_file(source, "stale", tray_size=getattr(self, "TRAY_SIZE", 60))
            detail = (
                f"현재 상태 변경 보류 · {source.name}\n"
                f"처음 SHA256: {getattr(self, '_paired_stale_current_original_hash', '')}\n"
                f"지금 SHA256: {latest.sha256 or '읽기 실패'}\n"
                "원본과 바뀐 바이트를 보존하고 이 건만 보류할 수 있습니다."
            )
            if messagebox.askyesno("현재 상태 변경 보류", detail + "\n\n원본 보존 상태를 재확인할까요?", parent=self.root):
                self._recheck_paired_stale_current()
            elif messagebox.askyesno("현재 상태 변경 보류", detail + "\n\n이 건만 보류하고 다른 현품표를 계속할까요?", parent=self.root):
                self._continue_after_paired_stale_current()
        for marker, result in stale_entries:
            if not self._blocked_work_identity_matches(approval):
                return
            detail = (
                f"현재 상태 보존 묶음: {marker.name}\n"
                f"상태: {'원본 해시 변경 보류' if result.verified else '보류 기록 손상 · 원 현품표 확인 필요'}\n"
                f"SHA256: {result.sha256 or '읽기 실패'}\n"
                f"원 현품표: {', '.join(result.value['labels']) if result.verified else '확인 필요'}"
            )
            if messagebox.askyesno("현재 상태 보류 목록", detail + "\n\n원 현품표를 중앙에서 다시 확인할까요?", parent=self.root):
                self._recheck_stale_hold_entry(marker, result, approval)
            elif messagebox.askyesno("현재 상태 보류 목록", detail + "\n\n이 건만 보류하고 다른 현품표를 계속할까요?", parent=self.root):
                self._recheck_stale_hold_entry(marker, result, approval)
        for row in stale_current_entries:
            if not self._blocked_work_identity_matches(approval):
                return
            detail = (f"현재 상태 격리 원본: {row.path.name}\n"
                      f"원인: {row.problem or '원본 보존 중'}\n"
                      f"SHA256: {row.content_sha256 or '읽기 실패'}\n"
                      f"원 현품표: {', '.join(row.labels) or '확인 필요'}")
            if row.unidentified and messagebox.askyesno(
                "현재 상태 격리 원본", detail + "\n\n원 현품표 두 장을 스캔해 중앙에서 확인할까요?",
                parent=self.root,
            ):
                if row.evidence_id:
                    self._identify_unreadable_audit(row.evidence_id, approval)
                else:
                    messagebox.showerror("원본 읽기 대기", "원본 바이트를 읽지 못해 안전한 결속을 할 수 없습니다. 이 건은 보류합니다.", parent=self.root)
            elif not row.unidentified:
                messagebox.showinfo("현재 상태 격리 원본", detail + "\n\n이 현품표는 계속 보류하고 다른 작업을 진행하세요.", parent=self.root)
        for row in temp_entries:
            if not self._blocked_work_identity_matches(approval):
                return
            if not self._audit_recovered_atomic_temps((row,)):
                messagebox.showerror("격리 감사 대기", "임시 원본의 격리 감사 기록에 실패했습니다. 원본을 보존하고 다시 확인하세요.", parent=self.root)
                continue
            detail = (f"원자 저장 중단 파일: {row.path.name}\n"
                      f"원인: {row.problem}\nSHA256: {row.content_sha256 or '읽기 실패'}\n"
                      f"원 현품표: {', '.join(row.labels) or '확인 필요'}\n"
                      "원본과 최종 파일은 바꾸지 않고 이 건을 보류합니다.")
            if row.unidentified and messagebox.askyesno(
                "임시 원본 확인", detail + "\n\n원 현품표를 스캔해 중앙에서 확인할까요?", parent=self.root,
            ):
                if row.evidence_id:
                    self._identify_unreadable_audit(
                        row.evidence_id, approval,
                        label_count=2 if (row.path.is_relative_to(store.directory)
                                          or row.path.parent.name in {"_event_outbox", "phs_label_exchange"}) else 1,
                    )
                else:
                    messagebox.showerror("원본 읽기 대기", "임시 원본을 읽지 못해 이 건을 계속 보류합니다.", parent=self.root)
            elif not row.labels and not row.unidentified:
                messagebox.showinfo("임시 원본 격리", detail + "\n\n현품표 key가 없어 다른 현품표 작업은 계속할 수 있습니다.", parent=self.root)
            elif row.labels and messagebox.askyesno(
                "임시 원본 보류", detail + "\n\n원 현품표를 중앙에서 다시 확인하고 이 건을 보류할까요?",
                parent=self.root,
            ):
                self._identify_unreadable_audit(
                    row.evidence_id, approval, known_labels=row.labels,
                )
        for row in audit_entries:
            if not self._blocked_work_identity_matches(approval):
                return
            detail = (f"감사 근거: {row.path.name}\n"
                      f"원인: {row.problem}\n"
                      f"원 현품표: {', '.join(row.labels) or '확인 필요'}\n"
                      "원본 감사 기록은 보존하고 해당 현품표만 보류합니다.")
            if row.unidentified and messagebox.askyesno(
                "감사 근거 확인", detail + "\n\n원 현품표 두 장을 스캔해 중앙에서 읽기 전용으로 확인할까요?",
                parent=self.root,
            ):
                if row.evidence_id:
                    self._identify_unreadable_audit(row.evidence_id, approval)
                else:
                    messagebox.showerror("감사 읽기 대기", "감사 원본 바이트를 읽지 못해 안전한 결속을 할 수 없습니다. 이 건은 보류합니다.", parent=self.root)
            elif not row.unidentified:
                messagebox.showinfo("감사 근거 보류", detail, parent=self.root)

    @_recovery_item_firewall
    def _identify_unreadable_audit(
        self, evidence_id: str, approval: Mapping[str, str], *,
        label_count: int = 2, known_labels: tuple[str, ...] = (),
    ) -> None:
        if not evidence_id or not self._blocked_work_identity_matches(approval):
            return
        labels = list(known_labels) if len(known_labels) != 1 else []
        names = (("원래",) if len(known_labels) == 1 else
                 () if labels else (("첫 번째", "두 번째") if label_count == 2 else ("원래",)))
        for name in names:
            label = simpledialog.askstring(
                "원 현품표 확인", f"신원 미확인 복구 근거의 {name} 원 현품표를 스캔하세요.",
                parent=self.root,
            )
            if not label or str((self._parse_new_format_qr(label) or {}).get("PHS") or "") != "2":
                messagebox.showwarning("원 현품표 확인 필요", "원래 PHS2 현품표를 확인할 때까지 보류합니다.", parent=self.root)
                return
            if known_labels and canonical_master_label_key(label) != canonical_master_label_key(known_labels[0]):
                messagebox.showwarning("원 현품표 불일치", "보류 근거에 기록된 원 현품표를 스캔하세요.", parent=self.root)
                return
            labels.append(label)
        if len(labels) == 2 and canonical_master_label_key(labels[0]) == canonical_master_label_key(labels[1]):
            messagebox.showwarning("원 현품표 확인 필요", "서로 다른 원 현품표 두 장을 스캔하세요.", parent=self.root)
            return
        lane = self._ui_task_lane()
        if lane.is_busy():
            return

        def work() -> bool:
            if not self._blocked_work_identity_is_current(approval):
                return False
            client = self._transfer_seal_runtime().client
            if client is None:
                return False
            for label in labels:
                found = client.resolve_phs_label(
                    authority_scope_id=client.authority_scope_id, scan_payload=label,
                )
                if not isinstance(found, Mapping) or not found:
                    return False
            return True

        def finish(verified: bool) -> None:
            if not verified or not self._blocked_work_identity_matches(approval):
                messagebox.showerror("중앙 확인 대기", "원 현품표를 확인하지 못했습니다. 감사 사건은 계속 보류합니다.", parent=self.root)
                return
            try:
                def source():
                    rows = self._parked_store().enumerate_key_evidence(
                        pair_store=self._paired_preflight_store())
                    original = next(row for row in rows if row.evidence_id == evidence_id)
                    return {"source_audit_id": evidence_id,
                            "source_sha256": original.content_sha256,
                            "labels": list(labels)}

                def effect(intent):
                    rows = self._parked_store().enumerate_key_evidence(
                        pair_store=self._paired_preflight_store())
                    return bool(self._admin_pin_effect_audited(
                        "PHS2_AUDIT_EVIDENCE_BOUND", intent["operation_key"])
                        and any(row.evidence_id == evidence_id and not row.unidentified
                                and {canonical_master_label_key(value) for value in row.labels}
                                == {canonical_master_label_key(value) for value in labels}
                                for row in rows))

                pin_approval = self._admin_pin_approval_for(
                    "CA.PAIR_HANDOFF" if len(labels) == 2 else "CA.TRAY_HOLD",
                    evidence_id, source, tuple(labels), effect)
                if pin_approval is None:
                    return
                row = next(row for row in self._parked_store().enumerate_key_evidence(
                    pair_store=self._paired_preflight_store()) if row.evidence_id == evidence_id)
                with self._admin_pin_locked_evidence(pin_approval, row.path, source):
                    audited = self._log_event(
                        "PHS2_AUDIT_EVIDENCE_BOUND",
                        detail={"source_audit_id": evidence_id, "labels": labels,
                                **self._blocked_work_audit_identity(pin_approval)},
                        synchronous=True,
                        idempotency_key=f"audit-evidence-bind:{evidence_id}", deduplicate=True,
                        log_file_path_override=str(Path(self.save_folder) / f"audit-binding-{evidence_id}.csv"),
                    )
                    if not audited or not self._blocked_work_identity_matches(pin_approval):
                        raise OSError("audit evidence binding failed")
                    rows = self._parked_store().enumerate_key_evidence(
                        pair_store=self._paired_preflight_store())
                    if not any(row.evidence_id == evidence_id and not row.unidentified
                               and {canonical_master_label_key(value) for value in row.labels}
                               == {canonical_master_label_key(value) for value in labels}
                               for row in rows):
                        raise OSError("audit evidence binding readback failed")
                    if not self._admin_pin_complete(pin_approval, effect):
                        return
            except Exception:
                messagebox.showerror("보류 기록 대기", "감사 기록을 확인하지 못했습니다. 이 건은 계속 보류합니다.", parent=self.root)
                return
            messagebox.showinfo("감사 근거 보류", "확인한 원 현품표만 보류했습니다. 다른 현품표 작업을 계속하세요.", parent=self.root)

        lane.submit(LaneTask(
            name="audit-evidence-identification", generation=getattr(self, "_scan_callback_epoch", 0),
            work=work, finish=finish,
            fail=lambda _exc: messagebox.showerror("중앙 확인 대기", "중앙 조회에 실패했습니다. 감사 사건은 계속 보류합니다.", parent=self.root),
        ))

    @_recovery_item_firewall
    def _recheck_stale_hold_entry(self, marker: Path, result, approval: Mapping[str, str]) -> None:
        if not self._blocked_work_identity_matches(approval):
            return
        labels = list(result.value["labels"]) if result.verified else []
        if not labels:
            for name in ("원래", "바뀐"):
                label = simpledialog.askstring(
                    "원 현품표 확인", f"{marker.name}의 {name} 현품표를 스캔하세요.", parent=self.root,
                )
                if not label or not self._parse_new_format_qr(label):
                    messagebox.showwarning("원 현품표 확인 필요", "현품표를 확인할 때까지 이 건은 보류합니다.", parent=self.root)
                    return
                labels.append(label)
        lane = self._ui_task_lane()
        if lane.is_busy():
            return

        def work() -> bool:
            if not self._blocked_work_identity_is_current(approval):
                return False
            client = self._transfer_seal_runtime().client
            if client is None:
                return False
            for label in labels:
                found = client.resolve_phs_label(
                    authority_scope_id=client.authority_scope_id, scan_payload=label,
                )
                if not isinstance(found, Mapping) or not found:
                    return False
            return True

        def finish(verified: bool) -> None:
            if not verified or not self._blocked_work_identity_matches(approval):
                messagebox.showerror("중앙 확인 대기", "원 현품표를 중앙에서 확인하지 못했습니다. 이 건은 계속 보류합니다.", parent=self.root)
                return
            try:
                def source():
                    return {"marker_sha256": hashlib.sha256(marker.read_bytes()).hexdigest(),
                            "labels": list(labels), "state": result.value if result.verified else {}}

                def effect(intent):
                    bound = (result.verified or read_recovery_file(
                        self._paired_preflight_store().stale_manager_path(marker),
                        "manager_hold").verified)
                    return bool(file_sha256(marker) == intent["source_snapshot"]["marker_sha256"]
                                and bound and self._admin_pin_effect_audited(
                        "PHS2_STALE_HOLD_RECHECKED", intent["operation_key"]))

                pin_approval = self._admin_pin_approval_for(
                    "CA.PAIR_RETRY", marker.stem, source, tuple(labels), effect)
                if pin_approval is None:
                    return
                with self._admin_pin_locked_sources(pin_approval, [
                        (marker, self._admin_pin_store().read(pin_approval["operation_key"])
                         ["source_snapshot"]["marker_sha256"])]):
                    audited = self._log_event(
                        "PHS2_STALE_HOLD_RECHECKED",
                        detail={"marker_file": marker.name, "labels": labels,
                                **self._blocked_work_audit_identity(pin_approval)},
                        synchronous=True,
                        idempotency_key=f"stale-hold-recheck:{uuid.uuid4().hex}",
                    )
                    if not audited or not self._blocked_work_identity_matches(pin_approval):
                        raise OSError("stale hold audit failed")
                    if not result.verified:
                        self._paired_preflight_store().bind_unidentified_stale(marker, tuple(labels))
                    if not self._admin_pin_complete(pin_approval, effect):
                        return
            except Exception:
                messagebox.showerror("보류 기록 대기", "관리자 기록을 확인하지 못했습니다. 이 건은 계속 보류합니다.", parent=self.root)
                return
            self._set_preflight_scan_input_locked(False)
            messagebox.showinfo("현재 상태 보류", "원 현품표를 다시 확인했습니다. 이 건은 계속 보류하고 다른 현품표를 진행하세요.", parent=self.root)

        lane.submit(LaneTask(
            name="stale-hold-readback", generation=getattr(self, "_scan_callback_epoch", 0),
            work=work, finish=finish,
            fail=lambda _exc: messagebox.showerror("중앙 확인 대기", "중앙 조회에 실패했습니다. 이 건은 계속 보류합니다.", parent=self.root),
        ))

    @_recovery_item_firewall
    def _identify_unreadable_pair(self, path: Path, approval: Mapping[str, str]) -> None:
        if not self._blocked_work_identity_matches(approval):
            return
        labels = []
        for name in ("보류 원본", "현재 원본"):
            scanned = simpledialog.askstring(
                "원 현품표 확인", f"{path.parent.name}의 {name} 현품표를 스캔하세요.",
                parent=self.root,
            )
            if not scanned or not self._parse_new_format_qr(scanned):
                messagebox.showwarning("원 현품표 확인 필요", "원래 PHS2 현품표 두 장이 필요합니다. 이 묶음은 보류합니다.", parent=self.root)
                return
            labels.append(scanned)
        if canonical_master_label_key(labels[0]) == canonical_master_label_key(labels[1]):
            messagebox.showwarning("원 현품표 확인 필요", "서로 다른 원 현품표 두 장을 스캔하세요.", parent=self.root)
            return
        store = self._paired_preflight_store()
        known = store.inspect(path).labels
        if any(canonical_master_label_key(value) not in {
            canonical_master_label_key(label) for label in labels
        } for value in known):
            messagebox.showwarning("원 현품표 불일치", "남은 원본과 스캔한 현품표가 다릅니다. 원본은 보류합니다.", parent=self.root)
            return
        lane = self._ui_task_lane()
        if lane.is_busy():
            return

        def work() -> bool:
            if not self._blocked_work_identity_is_current(approval):
                return False
            coordinator = self._transfer_seal_runtime()
            client = coordinator.client
            if client is None:
                return False
            for label in labels:
                result = client.resolve_phs_label(
                    authority_scope_id=client.authority_scope_id,
                    scan_payload=label,
                )
                if not isinstance(result, Mapping) or not result:
                    return False
            return True

        def finish(verified: bool) -> None:
            if not verified or not self._blocked_work_identity_matches(approval):
                messagebox.showerror("원 요청 재확인 대기", "중앙에서 두 원 현품표를 확인하지 못했습니다. 원본은 계속 보류합니다.", parent=self.root)
                return
            try:
                def source():
                    return {"handoff_id": path.parent.name,
                            "record_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                            "hold_sha256": read_recovery_file(path.parent / "hold.original", "hold").sha256,
                            "current_sha256": read_recovery_file(path.parent / "current.original", "current").sha256,
                            "labels": list(labels)}

                def effect(_intent):
                    marker = read_recovery_file(path.parent / "manager-hold.json", "manager_hold")
                    pinned = _intent["source_snapshot"]
                    return bool(file_sha256(path) == pinned["record_sha256"]
                                and read_recovery_file(path.parent / "hold.original", "hold").sha256
                                == pinned["hold_sha256"]
                                and read_recovery_file(path.parent / "current.original", "current").sha256
                                == pinned["current_sha256"]
                                and marker.verified and marker.value["labels"] == labels)

                pin_approval = self._admin_pin_approval_for(
                    "CA.PAIR_HANDOFF", path.parent.name, source, tuple(labels), effect)
                if pin_approval is None:
                    return
                pinned = self._admin_pin_store().read(pin_approval["operation_key"])["source_snapshot"]
                guarded = [(path, pinned["record_sha256"])]
                for name in ("hold", "current"):
                    digest = pinned.get(name + "_sha256")
                    original = path.parent / f"{name}.original"
                    if digest and original.is_file():
                        guarded.append((original, digest))
                with self._admin_pin_locked_sources(pin_approval, guarded):
                    audited = self._log_event(
                        "PHS2_PAIRED_MANUAL_HOLD",
                        detail={"handoff_id": path.parent.name, "labels": labels,
                                **self._blocked_work_audit_identity(pin_approval)},
                        synchronous=True,
                        idempotency_key=f"paired-manual-hold:{path.parent.name}:{uuid.uuid4().hex}",
                        deduplicate=True,
                    )
                    if not audited or not self._blocked_work_identity_matches(pin_approval):
                        raise PairedHandoffError("manager hold audit failed")
                    store.bind_unidentified(path, tuple(labels))
                    if not self._admin_pin_complete(pin_approval, effect):
                        return
            except Exception:
                messagebox.showerror("두 원본 보류 대기", "관리자 보류 기록을 확인하지 못했습니다. 원본은 계속 보류합니다.", parent=self.root)
                return
            self._set_preflight_scan_input_locked(False)
            self._update_action_button_states()
            messagebox.showinfo("두 원본 보류", "두 원 현품표만 보류했습니다. 다른 현품표 작업을 계속하세요.", parent=self.root)

        lane.submit(LaneTask(
            name="paired-original-identification",
            generation=getattr(self, "_scan_callback_epoch", 0),
            work=work,
            finish=finish,
            fail=lambda _exc: messagebox.showerror(
                "원 요청 재확인 대기", "중앙 조회에 실패했습니다. 두 원본은 계속 보류합니다.", parent=self.root,
            ),
        ))

    @_recovery_item_firewall
    def _recheck_paired_preflight_receipt(
        self, current: Mapping[str, Any], *, approval: Optional[Mapping[str, str]] = None,
        source_path: Optional[Path] = None,
    ) -> None:
        master = str(current.get("master_label_code") or "")
        scans = tuple(current.get("scanned_barcodes") or ())
        lane = self._ui_task_lane()
        if lane.is_busy():
            return
        target_id = hashlib.sha256(canonical_master_label_key(master).encode("utf-8")).hexdigest()

        def source():
            observed = (read_recovery_file(source_path, "current").value
                        if source_path is not None else dict(current))
            return {"master_label_code": master, "current": dict(observed),
                    "state_sha256": admin_pin_fingerprint(dict(observed)),
                    **({"current_sha256": file_sha256(source_path)}
                       if source_path is not None else {})}

        def effect(intent):
            return bool((source_path is None or
                         file_sha256(source_path) == intent["source_snapshot"]["current_sha256"])
                        and self._admin_pin_effect_audited(
                "PHS2_PAIRED_RECEIPT_RECHECK_REQUESTED", intent["operation_key"])
                        )

        approval = self._admin_pin_approval_for(
            "CA.PAIR_RETRY", target_id, source, (master,), effect)
        if approval is None:
            return
        if not self._blocked_work_identity_matches(approval):
            return
        try:
            with self._admin_pin_locked_sources(
                    approval, [(source_path, self._admin_pin_store().read(approval["operation_key"])
                                ["source_snapshot"]["current_sha256"])] if source_path else []):
                audited = bool(self._log_event(
                    "PHS2_PAIRED_RECEIPT_RECHECK_REQUESTED",
                    detail={
                        "master_label_code": master,
                        "scan_count": len(scans),
                        **self._blocked_work_audit_identity(approval),
                    },
                    synchronous=True,
                    idempotency_key=f"paired-receipt-recheck:{uuid.uuid4().hex}",
                ))
                if audited and not self._admin_pin_complete(approval, effect):
                    return
        except Exception:
            audited = False
        if not audited:
            messagebox.showerror(
                "원 요청 재확인 기록 대기",
                "관리자 재확인 기록을 남기지 못했습니다. 기록 상태를 확인한 뒤 다시 시도하세요.",
                parent=getattr(self, "root", None),
            )
            return
        def work() -> str:
            if not self._blocked_work_identity_is_current(approval):
                return "로그인 작업자 또는 역할이 바뀌어 원 요청을 조회하지 않았습니다. 관리자 확인을 다시 받으세요."
            coordinator = self._transfer_seal_runtime()
            row = coordinator.store.bound_operator_review_for_tray(
                master_label=master, scanned_barcodes=scans,
            )
            if row is None or not row["command_json"] or coordinator.client is None:
                return "원 요청 키가 없어 중앙 결과를 조회할 수 없습니다. 두 원본은 보류 상태로 둡니다."
            context = json.loads(row["command_json"])
            coordinator._validate_bound_command(row, context)
            receipt = coordinator.client.get_receipt(
                str(context["authority_scope_id"]), str(context["idempotency_key"]),
            )
            if receipt is None:
                return "원 요청의 중앙 영수증이 아직 없습니다. 두 원본은 보류 상태로 둡니다."
            coordinator._validate_receipt(context, receipt)
            return "원 요청의 중앙 영수증을 확인했습니다. 두 원본은 관리자 보류 상태로 유지합니다."

        lane.submit(LaneTask(
            name="paired-preflight-receipt-readback",
            generation=getattr(self, "_scan_callback_epoch", 0),
            work=work,
            finish=lambda result: messagebox.showinfo("원 요청 결과 다시 확인", result, parent=self.root),
            fail=lambda _exc: messagebox.showerror(
                "원 요청 결과 확인 불가", "중앙 결과를 확인하지 못했습니다. 두 원본은 보류 상태로 둡니다.", parent=self.root,
            ),
        ))

    def _recheck_unsettled_current_work(self) -> bool:
        if self._preflight_context_blocks_mutation():
            self._acknowledge_active_notice()
            return True
        snapshot = self._active_blocking_completion_snapshot()
        if snapshot is not None and snapshot.operator_retryable:
            self.submit_current_tray()
            return True
        if self._precommand_operator_review_retry_context() is not None:
            return self._retry_precommand_operator_review_completion()
        exchange = self._current_transfer_member_exchange_attempt()
        master = str(getattr(self.current_tray, "master_label_code", "") or "")
        scans = tuple(getattr(self.current_tray, "scanned_barcodes", ()) or ())
        if not master or (snapshot is None and exchange is None):
            return False
        lane = self._ui_task_lane()
        if lane.is_busy():
            return False

        def work() -> tuple[str, str]:
            if snapshot is not None:
                coordinator = self._transfer_seal_runtime()
                row = coordinator.store.bound_operator_review_for_tray(
                    master_label=master, scanned_barcodes=scans,
                )
                if row is None:
                    return "seal", "unavailable"
                return "seal", coordinator.recheck_operator_review_receipt(
                    str(row["intent_id"])
                ).status
            coordinator = self._transfer_member_exchange_runtime()
            attempted = coordinator.attempt(exchange.intent_id)
            return "exchange", f"{attempted.status}:{attempted.local_apply_status}"

        seal_ack_ready = False

        def finish_acknowledged_seal() -> None:
            try:
                if (
                    lane.is_busy()
                    or str(getattr(self.current_tray, "master_label_code", "") or "") != master
                    or tuple(getattr(self.current_tray, "scanned_barcodes", ()) or ()) != scans
                    or self._active_blocking_completion_snapshot() != snapshot
                ):
                    return
                presenter = self._warning_state_presenter()
                previous = getattr(self, "_pending_operator_review_snapshot", None)
                if snapshot is None or not presenter.resolve_blocking_completion(snapshot):
                    return
                self._pending_operator_review_snapshot = None
                if not self._save_current_tray_state():
                    self._pending_operator_review_snapshot = previous or snapshot
                    presenter.present_completion(snapshot)
                    messagebox.showerror(
                        "중앙 확인 저장 실패",
                        "중앙 영수증은 확인했지만 현재 트레이의 잠금 상태를 "
                        "저장하지 못했습니다. 원래 작업을 유지하고 관리자에게 인계하세요.",
                        parent=getattr(self, "root", None),
                    )
                    return
                presenter.acknowledge()
                self._render_warning_state()
                self.request_complete_tray()
            finally:
                self._schedule_pending_transfer_coordinator_work()

        def finish(result: tuple[str, str]) -> None:
            nonlocal seal_ack_ready
            if str(getattr(self.current_tray, "master_label_code", "") or "") != master:
                return
            kind, status = result
            if kind == "seal" and status == "ACKED":
                seal_ack_ready = True
                return
            if kind == "exchange" and status == "ACKED:PENDING":
                self._reconcile_pending_local_member_exchanges()
                return
            if kind == "exchange" and status.startswith("ACKED:"):
                messagebox.showinfo(
                    "중앙 교체 확인 · 로컬 대조 필요",
                    "중앙 교체 영수증은 확인됐지만 이 PC의 제품 목록 반영은 "
                    "아직 확인되지 않았습니다. 원 묶음을 보존하고 관리자에게 "
                    "중앙 영수증과 현재 트레이 대조를 요청하세요.",
                    parent=getattr(self, "root", None),
                )
                return
            messagebox.showinfo(
                "중앙 결과 확인 대기",
                "원 요청의 확정된 결과를 아직 확인하지 못했습니다. "
                "묶음은 미확정 상태로 남습니다. 관리자 보류 후 다른 작업을 "
                "계속하거나 인계 내용을 확인하세요.",
                parent=getattr(self, "root", None),
            )

        def fail(exc: BaseException) -> None:
            print(f"원 요청 결과 재확인 실패: {exc.__class__.__name__}")
            finish(("seal" if snapshot is not None else "exchange", "failed"))

        def on_idle() -> None:
            if seal_ack_ready:
                self.root.after(0, finish_acknowledged_seal)
            else:
                self._schedule_pending_transfer_coordinator_work()

        admission = lane.submit(LaneTask(
            name="unsettled-work-recheck",
            generation=int(getattr(self, "_scan_callback_epoch", 0) or 0),
            work=work, finish=finish, fail=fail,
            on_idle=on_idle,
        ))
        self._update_action_button_states()
        return bool(admission.accepted)

    def _show_left_sidebar_view(self, view: str) -> None:
        """Switch the compact left context without rebuilding either tree."""

        if view not in {"summary", "parked"}:
            return
        self._left_sidebar_view = view
        self._sync_left_sidebar_switch()
        self._apply_left_sidebar_layout()
        try:
            self._schedule_focus_return()
        except (tk.TclError, AttributeError):
            pass

    def _toggle_left_sidebar_view(self) -> None:
        current = getattr(self, "_left_sidebar_view", "summary")
        self._show_left_sidebar_view("summary" if current == "parked" else "parked")

    def _sync_left_sidebar_switch(self) -> None:
        button = getattr(self, "left_context_switch_button", None)
        if button is None:
            return
        view = getattr(self, "_left_sidebar_view", "summary")
        count = max(0, int(getattr(self, "_parked_tray_count", 0) or 0))
        text = "현재·기록 보기" if view == "parked" else f"보류 {count}건 보기"
        try:
            button.configure(text=text, style="Secondary.TButton")
        except (tk.TclError, AttributeError):
            pass

    def _update_parked_recovery_affordance(self) -> int:
        """Keep the compact recovery entry point truthful after list refreshes."""

        count = 0
        tree = getattr(self, "parked_tree", None)
        if tree is not None:
            try:
                count = len(tree.get_children())
            except (tk.TclError, AttributeError, TypeError):
                count = 0
        title = getattr(self, "parked_title_label", None)
        if title is not None:
            try:
                title.configure(text=f"보류 작업 {count}건 (더블클릭으로 복원)")
            except (tk.TclError, AttributeError):
                pass
        self._parked_tray_count = count
        self._sync_left_sidebar_switch()
        return count

    def _apply_left_sidebar_layout(self) -> None:
        parent_frame = getattr(self, "_left_sidebar_frame", None)
        if parent_frame is None:
            return
        scale = max(0.7, min(2.5, float(getattr(self, "scale_factor", 1.0) or 1.0)))
        previous_compact_height = getattr(self, "_left_sidebar_compact", None)
        try:
            parent_width = int(parent_frame.winfo_width())
            parent_height = int(self._pane_viewport_height(parent_frame))
            compact_large_text = scale >= 1.2 and 1 < parent_width < 420
            compact_height = (
                parent_height > 1
                and parent_height / scale < LEFT_SIDEBAR_SWITCH_LOGICAL_HEIGHT
            )
            tray_image_checkbox = getattr(self, "tray_image_checkbox", None)
            if tray_image_checkbox is not None:
                tray_image_checkbox.configure(
                    text="트레이 이미지" if compact_large_text else "트레이 이미지 보기",
                    wraplength=max(60, parent_width - 50),
                    font=(self.DEFAULT_FONT, self.style_tokens.fonts.body),
                )
            if getattr(self, "show_tray_image_var", None) is not None and self.show_tray_image_var.get():
                parent_frame.grid_rowconfigure(0, weight=3)
                parent_frame.grid_rowconfigure(1, weight=2, minsize=int(180 * scale))
            else:
                parent_frame.grid_rowconfigure(0, weight=1)
                parent_frame.grid_rowconfigure(1, weight=0, minsize=int(42 * scale))

            top_frame = getattr(self, "_left_top_frame", None)
            switch_frame = getattr(self, "_left_view_switch_frame", None)
            summary_title = getattr(self, "summary_title_label", None)
            summary_frame = getattr(self, "_summary_tree_frame", None)
            parked_title = getattr(self, "parked_title_label", None)
            parked_frame = getattr(self, "_parked_tree_frame", None)
            if any(
                value is None
                for value in (
                    top_frame,
                    switch_frame,
                    summary_title,
                    summary_frame,
                    parked_title,
                    parked_frame,
                )
            ):
                return

            for row in (2, 3, 4, 5):
                top_frame.grid_rowconfigure(row, weight=0, minsize=0)
            view = getattr(self, "_left_sidebar_view", "summary")
            if view not in {"summary", "parked"}:
                view = "summary"
                self._left_sidebar_view = view

            header_frame = getattr(self, "_left_header_frame", None)
            worker_info_frame = getattr(self, "_worker_info_frame", None)
            worker_buttons_frame = getattr(self, "_worker_buttons_frame", None)
            current_work_frame = getattr(self, "_current_work_frame", None)
            current_work_title = getattr(self, "current_work_title_label", None)
            fonts = getattr(getattr(self, "style_tokens", None), "fonts", None)
            roomy_sidebar_font = int(
                getattr(fonts, "sidebar", max(12, int(13 * scale)))
            )
            roomy_name_font = int(
                getattr(fonts, "section_title", max(14, int(15 * scale)))
            )
            roomy_detail_font = int(
                getattr(fonts, "caption", max(11, int(12 * scale)))
            )

            if compact_height:
                if header_frame is not None and worker_info_frame is not None and worker_buttons_frame is not None:
                    header_frame.grid_columnconfigure(0, weight=1)
                    header_frame.grid_columnconfigure(1, weight=0)
                    header_frame.grid_configure(pady=(0, 8))
                    worker_info_frame.grid(row=0, column=0, sticky="ew")
                    worker_buttons_frame.grid(row=0, column=1, sticky="e", padx=(8, 0), pady=0)
                    self.worker_info_label.configure(
                        text=display_operator_name(self.worker_name),
                        font=(self.DEFAULT_FONT, max(12, int(11 * scale)), "bold"),
                    )
                    self.change_worker_button.configure(
                        text="변경",
                        style="Secondary.TButton",
                        width=4,
                    )
                if current_work_frame is not None:
                    current_work_frame.configure(padding=8)
                    current_work_frame.grid_configure(pady=(0, 8))
                if current_work_title is not None:
                    current_work_title.grid_remove()
                self.current_work_name_label.configure(
                    font=(self.DEFAULT_FONT, max(15, int(13 * scale)), "bold")
                )
                self.current_work_name_label.grid_configure(pady=(0, 2))
                self.current_work_detail_label.configure(
                    font=(self.DEFAULT_FONT, max(12, int(10 * scale)))
                )
                self.current_work_spec_label.configure(
                    font=(self.DEFAULT_FONT, max(12, int(10 * scale)))
                )
                switch_frame.grid(row=2, column=0, sticky="ew", pady=(0, 8))
                summary_title.grid_remove()
                parked_title.grid_remove()
                if view == "parked":
                    summary_frame.grid_remove()
                    parked_frame.grid(row=3, column=0, sticky="nsew")
                    self.root.after_idle(self._adjust_parked_tree_columns)
                else:
                    parked_frame.grid_remove()
                    summary_frame.grid(row=3, column=0, sticky="nsew")
                    self.root.after_idle(self._adjust_summary_tree_columns)
                top_frame.grid_rowconfigure(
                    3,
                    weight=1,
                    minsize=max(
                        92,
                        int(72 * scale),
                        int(getattr(self, "_left_tree_minimum_one_row_height", 0) or 0),
                    ),
                )
            else:
                if header_frame is not None and worker_info_frame is not None and worker_buttons_frame is not None:
                    header_frame.grid_columnconfigure(0, weight=1)
                    header_frame.grid_columnconfigure(1, weight=0)
                    header_frame.grid_configure(pady=(0, 12))
                    worker_info_frame.grid(row=0, column=0, sticky="ew")
                    worker_buttons_frame.grid(row=1, column=0, sticky="ew", padx=0, pady=(6, 0))
                    self.worker_info_label.configure(
                        text=f"작업자: {display_operator_name(self.worker_name)}",
                        font=(self.DEFAULT_FONT, roomy_sidebar_font),
                    )
                    self.change_worker_button.configure(
                        text="작업자 변경",
                        style="Secondary.TButton",
                        width=0,
                    )
                if current_work_frame is not None:
                    current_work_frame.configure(padding=12)
                    current_work_frame.grid_configure(pady=(0, 14))
                if current_work_title is not None:
                    current_work_title.grid(row=0, column=0, sticky="ew")
                self.current_work_name_label.configure(
                    font=(self.DEFAULT_FONT, roomy_name_font, "bold")
                )
                self.current_work_name_label.grid_configure(pady=(3, 2))
                self.current_work_detail_label.configure(
                    font=(self.DEFAULT_FONT, roomy_detail_font)
                )
                self.current_work_spec_label.configure(
                    font=(self.DEFAULT_FONT, roomy_detail_font)
                )
                switch_frame.grid_remove()
                summary_title.grid(row=2, column=0, sticky="ew", pady=(0, 10))
                summary_frame.grid(row=3, column=0, sticky="nsew")
                parked_title.grid(row=4, column=0, sticky="ew", pady=(20, 10))
                parked_frame.grid(row=5, column=0, sticky="nsew")
                top_frame.grid_rowconfigure(3, weight=2, minsize=0)
                top_frame.grid_rowconfigure(5, weight=1, minsize=0)
                self.root.after_idle(self._adjust_summary_tree_columns)
                self.root.after_idle(self._adjust_parked_tree_columns)
            self._left_sidebar_compact = compact_height
            if (
                previous_compact_height is None
                or bool(previous_compact_height) != compact_height
            ):
                self._update_operator_context()
            self._sync_left_sidebar_switch()
        except (tk.TclError, AttributeError):
            return

    def _get_right_sidebar_layout_metrics(self, sidebar_height: int) -> Dict[str, Any]:
        sidebar_width = 320
        parent_frame = getattr(self, "_right_sidebar_frame", None)
        try:
            candidate = int(parent_frame.winfo_width())
            if candidate > 1:
                sidebar_width = candidate
        except (AttributeError, TypeError, ValueError, tk.TclError):
            pass
        metrics = calculate_right_sidebar_metrics(
            sidebar_width,
            sidebar_height,
            getattr(self, "scale_factor", 1.0),
        )
        context_value_font = metrics.context_value_font
        if context_value_font <= 0:
            try:
                root_width = max(1, int(self.root.winfo_width()))
                root_height = max(1, int(self.root.winfo_height()))
            except (AttributeError, TypeError, ValueError, tk.TclError):
                root_width, root_height = 1440, 900
            root_profile = select_layout_profile(
                root_width,
                root_height,
                getattr(self, "scale_factor", 1.0),
            )
            root_tokens = build_style_tokens(
                StyleProfile(root_profile.name),
                getattr(self, "scale_factor", 1.0),
            )
            context_value_font = int(root_tokens.fonts.section_title)
        return {
            "profile": metrics.profile,
            "short_large_text": metrics.short_large_text,
            "content_sized_cards": metrics.content_sized_cards,
            "outer_padding": metrics.outer_padding,
            "card_gap": metrics.card_gap,
            "card_minsize": metrics.card_minsize,
            "primary_card_minsize": metrics.primary_card_minsize,
            "secondary_card_minsize": metrics.secondary_card_minsize,
            "follow_up_minsize": metrics.follow_up_minsize,
            "legend_pad_y": metrics.legend_pad_y,
            "legend_visible": metrics.legend_visible,
            "date_font": metrics.date_font,
            "clock_font": metrics.clock_font,
            "date_gap": metrics.date_gap,
            "clock_gap": metrics.clock_gap,
            "card_padding": metrics.card_padding,
            "context_padding": metrics.context_padding,
            "secondary_card_padding": metrics.secondary_card_padding,
            "value_font": metrics.value_font,
            "secondary_value_font": metrics.secondary_value_font,
            "context_value_font": context_value_font,
        }

    def _apply_right_sidebar_layout(self, event=None, *, generation=None) -> None:
        parent_frame = getattr(self, "_right_sidebar_frame", None)
        if parent_frame is None:
            return
        current_generation = getattr(self, "_right_widget_generation", 0)
        if generation is not None and generation != current_generation:
            return
        generation = current_generation
        try:
            height = self._pane_viewport_height(parent_frame)
        except (tk.TclError, AttributeError):
            return
        if height <= 1:
            return
        metrics = self._get_right_sidebar_layout_metrics(height)
        metrics_key = (generation, *metrics.values())
        if metrics_key == getattr(self, "_right_sidebar_layout_metrics", None):
            return
        try:
            parent_frame.configure(padding=(metrics["outer_padding"], metrics["outer_padding"]))
            parent_frame.grid_rowconfigure(5, weight=0, minsize=0)
            date_label = getattr(self, "date_label", None)
            if date_label is not None:
                date_label.configure(font=(self.DEFAULT_FONT, metrics["date_font"], 'bold'))
                date_label.grid_configure(pady=(0, metrics["date_gap"]))
            clock_label = getattr(self, "clock_label", None)
            if clock_label is not None:
                clock_label.configure(font=(self.DEFAULT_FONT, metrics["clock_font"], 'bold'))
                clock_label.grid_configure(pady=(0, metrics["clock_gap"]))
            for row in (2, 3, 4):
                parent_frame.grid_rowconfigure(
                    row,
                    weight=1,
                    minsize=metrics["primary_card_minsize"],
                    uniform="" if metrics["content_sized_cards"] else "primary_info_cards",
                )
            parent_frame.grid_rowconfigure(6, weight=0, minsize=0)
            parent_frame.grid_rowconfigure(7, weight=0, minsize=0)
            compact = metrics["content_sized_cards"]
            self.style.configure(
                'SidebarDetail.Secondary.TButton',
                padding=(6, 2),
            )
            for name in ('work_details_button', 'direct_sync_details_button'):
                button = getattr(self, name, None)
                if button is not None:
                    button.configure(style=(
                        'SidebarDetail.Secondary.TButton' if compact else 'Secondary.TButton'
                    ))
            work_details = getattr(self, 'work_details_button', None)
            if work_details is not None:
                work_details.grid_configure(pady=(0, 0 if compact else metrics['card_gap']))
            sync_details = getattr(self, 'direct_sync_details_button', None)
            if sync_details is not None:
                sync_details.pack_configure(pady=(0 if compact else 6, 0))
            for key in ("status", "direct_sync", "stopwatch"):
                card = getattr(self, "info_cards", {}).get(key)
                if card:
                    card["frame"].configure(padding=0 if compact else metrics["card_padding"])
                    card["frame"].grid_configure(pady=(0, 0 if compact else metrics["card_gap"]))
                    caption = card.get("label")
                    if caption is not None:
                        caption.configure(
                            font=(self.DEFAULT_FONT, 10)
                            if metrics["content_sized_cards"] else "",
                        )
                    card["value"].configure(
                        font=(self.DEFAULT_FONT, metrics["value_font"], 'bold'),
                        anchor='center',
                        justify='center',
                    )
            direct_sync_card = getattr(self, "info_cards", {}).get("direct_sync")
            if direct_sync_card:
                direct_sync_card["value"].configure(
                    font=(self.DEFAULT_FONT, metrics["secondary_value_font"], 'bold')
                )
            context_frame = getattr(self, "_right_context_frame", None)
            if context_frame is not None:
                context_frame.configure(padding=0 if compact else metrics["context_padding"])
                context_frame.grid_configure(pady=(0, metrics["card_gap"]))
            for caption in getattr(self, "_right_context_captions", ()):
                caption.configure(
                    font=(self.DEFAULT_FONT, 10)
                    if metrics["content_sized_cards"] else "",
                )
            context_value_font = metrics["context_value_font"]
            if context_value_font <= 0:
                token_fonts = getattr(getattr(self, "style_tokens", None), "fonts", None)
                context_value_font = int(
                    getattr(token_fonts, "section_title", max(13, int(15 * self.scale_factor)))
                )
            last_scan_value = getattr(self, "last_scan_value_label", None)
            if last_scan_value is not None:
                last_scan_value.configure(
                    font=(self.DEFAULT_FONT, context_value_font, 'bold'),
                    anchor='center',
                    justify='center',
                )
                last_scan_value.grid_configure(
                    pady=(0, 2) if metrics["content_sized_cards"] else
                    (3 if metrics["short_large_text"] else 4, 6 if metrics["short_large_text"] else 12)
                )
            context_separator = getattr(self, "_right_context_separator", None)
            if context_separator is not None:
                context_separator.grid_configure(
                    pady=(0, 2 if metrics["content_sized_cards"] else
                          6 if metrics["short_large_text"] else 10)
                )
            follow_up = getattr(self, "follow_up_label", None)
            if follow_up is not None:
                follow_up.configure(
                    font=(self.DEFAULT_FONT, context_value_font, 'bold'),
                    anchor='center',
                    justify='center',
                )
                follow_up.grid_configure(pady=(0 if metrics["content_sized_cards"] else
                                              3 if metrics["short_large_text"] else 4, 0))
            for key in ("avg_time", "best_time"):
                card = getattr(self, "info_cards", {}).get(key)
                if card:
                    card["frame"].configure(padding=0 if compact else metrics["secondary_card_padding"])
                    # Compact cards need compact captions too: the root's
                    # larger caption font wraps the best-time title and pushes
                    # both required values below the short sidebar.
                    caption = card.get("label")
                    if caption is not None:
                        caption.configure(
                            font=(self.DEFAULT_FONT, 10)
                            if not metrics["legend_visible"] else "",
                        )
                    card["value"].configure(
                        font=(self.DEFAULT_FONT, metrics["secondary_value_font"], 'bold'),
                        anchor='center',
                        justify='center',
                    )
            # Cache only after every widget in this generation accepted the
            # metrics.  A configure event during reconstruction must not make
            # a partially styled generation look complete.
            self._right_sidebar_layout_metrics = metrics_key
            self._apply_work_details_visibility()
        except (tk.TclError, AttributeError):
            return

    @staticmethod
    def _tree_available_width(tree: ttk.Treeview) -> int:
        try:
            tree_width = int(tree.winfo_width())
        except (AttributeError, TypeError, ValueError, tk.TclError):
            tree_width = 0
        if tree_width > 1:
            # Treeview already excludes its sibling scrollbar.  Keep a small
            # border gutter so the final heading never extends into the edge.
            return max(1, tree_width - 4)

        parent_frame = tree.master
        available_width = parent_frame.winfo_width()
        for child in parent_frame.winfo_children():
            try:
                is_scrollbar = child.winfo_class() == "TScrollbar"
            except (AttributeError, tk.TclError):
                try:
                    is_scrollbar = isinstance(child, ttk.Scrollbar)
                except TypeError:
                    is_scrollbar = False
            if is_scrollbar:
                try:
                    scrollbar_width = int(child.winfo_width())
                    if scrollbar_width <= 1:
                        scrollbar_width = int(child.winfo_reqwidth())
                except (AttributeError, TypeError, ValueError, tk.TclError):
                    scrollbar_width = 0
                available_width -= max(0, scrollbar_width)
                break
        return max(1, available_width - 4)

    def _apply_tree_row_styles(self, tree: ttk.Treeview) -> None:
        tree.tag_configure('even', background=self.COLOR_CARD_BG, foreground=self.COLOR_TEXT)
        tree.tag_configure('odd', background=self.COLOR_SIDEBAR_BG, foreground=self.COLOR_TEXT)

    @staticmethod
    def _insert_tree_row(tree: ttk.Treeview, parent: str, index: str, *, values, iid=None, tags=()):
        try:
            return tree.insert(parent, index, values=values, iid=iid, tags=tags)
        except TypeError:
            return tree.insert(parent, index, values=values, iid=iid)

    def _tree_column_required_width(
        self,
        tree: ttk.Treeview,
        column_id: str,
        heading_text: str,
        *,
        fallback: int,
    ) -> int:
        """Return the measured width needed by a heading and current row values."""

        try:
            style_name = str(tree.cget("style") or "Treeview")
            body_spec = self.style.lookup(style_name, "font") or "TkDefaultFont"
            heading_spec = (
                self.style.lookup(f"{style_name}.Heading", "font")
                or "TkHeadingFont"
            )
            body_font = tkfont.Font(root=self.root, font=body_spec)
            heading_font = tkfont.Font(root=self.root, font=heading_spec)
            raw_columns = tree.cget("columns")
            if isinstance(raw_columns, (tuple, list)):
                columns = tuple(str(value) for value in raw_columns)
            else:
                columns = tuple(str(value) for value in tree.tk.splitlist(raw_columns))
            column_index = columns.index(column_id)
            widths = [int(heading_font.measure(str(heading_text or "")))]
            for item_id in tree.get_children():
                values = tuple(tree.item(item_id, "values") or ())
                if column_index < len(values):
                    widths.append(int(body_font.measure(str(values[column_index] or ""))))
            cell_gutter = max(18, int(round(12 * self.scale_factor)))
            return max(int(fallback), max(widths, default=0) + cell_gutter)
        except (
            AttributeError,
            RuntimeError,
            tk.TclError,
            TypeError,
            ValueError,
        ):
            return max(1, int(fallback))

    def _adjust_summary_tree_columns(self, event=None):
        if not (hasattr(self, 'summary_tree') and self.summary_tree.winfo_exists()):
            return
        available_width = self._tree_available_width(self.summary_tree)
        if available_width <= 1:
            return
        def apply_display_columns(columns) -> None:
            desired = tuple(columns)
            raw_current = self.summary_tree.cget("displaycolumns")
            if raw_current in ("#all", ("#all",), ["#all"]):
                raw_current = self.summary_tree.cget("columns")
            if isinstance(raw_current, (tuple, list)):
                current = tuple(str(value) for value in raw_current)
            else:
                current = tuple(str(raw_current or "").split())
            if current != desired:
                self.summary_tree["displaycolumns"] = desired

        scale = max(1.0, min(2.5, float(getattr(self, "scale_factor", 1.0) or 1.0)))
        def apply_compact_columns() -> None:
            # The current-work card already carries the item name.  On a
            # narrow/large-text sidebar, keep the actionable historical keys
            # (code + completed count) fully readable instead of squeezing
            # three data columns into the same width.
            apply_display_columns(("item_code", "count"))
            count_fallback = max(52, int(round(32 * scale)), int(available_width * 0.16))
            count_width = self._tree_column_required_width(
                self.summary_tree,
                "count",
                "건",
                fallback=count_fallback,
            )
            item_required = self._tree_column_required_width(
                self.summary_tree,
                "item_code",
                "품목 코드",
                fallback=max(140, int(round(120 * scale))),
            )
            if item_required + count_width > available_width:
                count_width = max(
                    count_fallback,
                    min(count_width, max(1, available_width - item_required)),
                )
            count_width = min(count_width, max(1, available_width - 1))
            self.summary_tree.heading("item_code", text="품목 코드")
            self.summary_tree.heading("count", text="건")
            self.summary_tree.column(
                "item_code",
                width=max(1, available_width - count_width),
                stretch=tk.NO,
            )
            self.summary_tree.column(
                "count",
                width=count_width,
                stretch=tk.NO,
            )
        full_heading_threshold = int(round(540 * scale))
        if (
            bool(getattr(self, "_left_sidebar_compact", False))
            or available_width < full_heading_threshold
        ):
            apply_compact_columns()
            return

        # Full Korean headings need both a wider baseline than the old 420 px
        # cutoff and physical room for the configured Treeview heading font.
        # Prefer the compact wording whenever that room or the current row data
        # is unavailable at the live sidebar font size.
        headings = {"item_name_spec": "품목명", "item_code": "품목코드", "count": "완료 수량"}
        required_widths = {
            "item_name_spec": self._tree_column_required_width(
                self.summary_tree,
                "item_name_spec",
                headings["item_name_spec"],
                fallback=max(150, int(round(120 * scale))),
            ),
            "item_code": self._tree_column_required_width(
                self.summary_tree,
                "item_code",
                headings["item_code"],
                fallback=max(130, int(round(120 * scale))),
            ),
            "count": self._tree_column_required_width(
                self.summary_tree,
                "count",
                headings["count"],
                fallback=max(100, int(round(72 * scale))),
            ),
        }
        if sum(required_widths.values()) > available_width:
            apply_compact_columns()
            return

        apply_display_columns(("item_name_spec", "item_code", "count"))
        count_width = max(
            required_widths["count"],
            max(100, min(150, int(available_width * 0.22))),
        )
        code_width = max(
            required_widths["item_code"],
            max(130, min(210, int(available_width * 0.32))),
        )
        if (
            count_width
            + code_width
            + required_widths["item_name_spec"]
            > available_width
        ):
            count_width = required_widths["count"]
            code_width = required_widths["item_code"]
        widths = {
            "item_name_spec": max(1, available_width - code_width - count_width),
            "item_code": code_width,
            "count": count_width,
        }
        for col_id, heading in headings.items():
            self.summary_tree.heading(col_id, text=heading)
            self.summary_tree.column(col_id, width=max(1, widths[col_id]), stretch=tk.NO)

    def _adjust_parked_tree_columns(self, event=None):
        if not (hasattr(self, 'parked_tree') and self.parked_tree.winfo_exists()):
            return
        available_width = self._tree_available_width(self.parked_tree)
        if available_width <= 1:
            return
        scale = max(1.0, min(2.5, float(getattr(self, "scale_factor", 1.0) or 1.0)))
        def compact_widths() -> tuple[str, str, int, int]:
            item_heading, count_heading = "품목", "건"
            count_fallback = max(52, int(round(36 * scale)), int(available_width * 0.18))
            count_width = self._tree_column_required_width(
                self.parked_tree,
                "scan_count",
                count_heading,
                fallback=count_fallback,
            )
            item_required = self._tree_column_required_width(
                self.parked_tree,
                "item_name",
                item_heading,
                fallback=max(140, int(round(110 * scale))),
            )
            if item_required + count_width > available_width:
                count_width = max(
                    count_fallback,
                    min(count_width, max(1, available_width - item_required)),
                )
            return item_heading, count_heading, item_required, count_width

        full_heading_threshold = int(round(380 * scale))
        if available_width < full_heading_threshold:
            item_heading, count_heading, _item_required, count_width = compact_widths()
        else:
            item_heading, count_heading = "품목명", "스캔 수량"
            item_required = self._tree_column_required_width(
                self.parked_tree,
                "item_name",
                item_heading,
                fallback=max(160, int(round(120 * scale))),
            )
            count_required = self._tree_column_required_width(
                self.parked_tree,
                "scan_count",
                count_heading,
                fallback=max(128, int(round(84 * scale))),
            )
            if item_required + count_required > available_width:
                item_heading, count_heading, _item_required, count_width = compact_widths()
            else:
                count_width = max(
                    count_required,
                    max(128, min(180, int(available_width * 0.30))),
                )
                if item_required + count_width > available_width:
                    count_width = count_required
        count_width = min(count_width, max(1, available_width - 1))
        self.parked_tree.heading('item_name', text=item_heading)
        self.parked_tree.heading('scan_count', text=count_heading)
        self.parked_tree.column('scan_count', width=count_width, stretch=tk.NO)
        self.parked_tree.column('item_name', width=max(1, available_width - count_width), stretch=tk.NO)

