def _first_run_onboarding_enabled() -> bool:
    if getattr(sys, "frozen", False) and os.name == "nt":
        return True
    value = os.getenv("CONTAINER_AUDIT_ENABLE_FIRST_RUN_ONBOARDING", "").strip().lower()
    return value in {"1", "true", "yes", "on", "enabled"}


def _show_first_run_onboarding_error(failure: CurrentUserOnboardingError) -> None:
    report_path = str(failure.report_path)
    operator_message = f"{FIRST_RUN_ONBOARDING_ERROR_MESSAGE}\n보고서: {report_path}"
    if isinstance(failure.__cause__, DataGenerationBlocked):
        operator_message = failure.__cause__.user_message
    try:
        messagebox.showerror(
            FIRST_RUN_ONBOARDING_ERROR_TITLE,
            operator_message,
        )
    except Exception:
        pass


def _show_bootstrap_integrity_warning(report_path: object) -> None:
    operator_message = (
        f"{BOOTSTRAP_INTEGRITY_WARNING_MESSAGE}\n보고서: {str(report_path or 'UNKNOWN')}"
    )
    try:
        messagebox.showwarning(
            BOOTSTRAP_INTEGRITY_WARNING_TITLE,
            operator_message,
        )
    except Exception:
        pass


def _show_item_catalog_startup_error(cause_code: str) -> None:
    try:
        messagebox.showerror(
            ITEM_CATALOG_STARTUP_ERROR_TITLE,
            f"{ITEM_CATALOG_STARTUP_ERROR_MESSAGE}\n오류 코드: {cause_code}",
        )
    except Exception:  # The fail-closed exit must survive Tk initialization failures.
        pass


def _item_catalog_cache_time_for_display(value: object) -> str:
    text = str(value or "").strip()
    if not text or text == "UNKNOWN":
        return "UNKNOWN"
    try:
        parsed = datetime.datetime.fromisoformat(text)
    except ValueError:
        return "UNKNOWN"
    if parsed.tzinfo is None:
        return "UNKNOWN"
    return parsed.astimezone().strftime("%Y-%m-%d %H:%M:%S %Z")


def main(argv: list[str] | None = None):
    arguments = list(sys.argv[1:] if argv is None else argv)
    from auto_update import startup_gate, trial_context, publish_gui_ready, trial_stop_requested

    application_code_root = Path(__file__).resolve().parent
    gate_result = startup_gate(application_code_root, arguments)
    if gate_result is not None:
        return gate_result
    hosted_result = dispatch_product_mode(arguments)
    if hosted_result is not None:
        return hosted_result

    parser = argparse.ArgumentParser(description="Container_Audit")
    parser.add_argument("--data-root", default=None)
    options, _ = parser.parse_known_args(arguments)
    try:
        startup = _prepare_gui_startup(data_root=options.data_root)
    except DataGenerationBlocked as blocked:
        notice = blocked.user_message
        messagebox.showerror("자료 판 확인", notice)
        return 1
    except DataRootUnavailableError:
        # Display the recovery action after releasing writer admission.
        notify_data_root_error()
        return 1
    if not isinstance(startup, tuple):
        return startup
    app, instance_lease = startup
    if trial_context(application_code_root) is not None:
        app.root.withdraw()
        def await_update_readiness():
            if trial_stop_requested(application_code_root):
                # The hidden trial accepts no scans. Flush its existing queue
                # without prompting to discard an operator's unfinished tray.
                app._finalize_application_close()
                return
            context = trial_context(application_code_root)
            if context is None:
                app._startup_update_pending = False
                app.root.deiconify()
                return
            try:
                publish_gui_ready(application_code_root)
            except (OSError, ValueError):
                pass  # A readback failure remains unconfirmed; data is preserved.
            app.root.after(250, await_update_readiness)
        app.root.after(0, await_update_readiness)
    try:
        # The resident UI must let the relay and background writers acquire
        # admission between their own guarded mutations.
        app.run()
        return 0
    finally:
        if getattr(app, "_loop_cleanup_finished", True):
            instance_lease.release()


@writer_sink("gui_startup", probe_only=True)
def _prepare_gui_startup(*, data_root=None):
    """Check the kernel instance lease before admitting startup mutations."""

    if getattr(sys, 'frozen', False):
        application_path = os.path.dirname(sys.executable)
    else:
        application_path = os.path.dirname(os.path.abspath(__file__))
    try:
        storage_paths = build_container_audit_storage_paths(
            application_path=application_path, data_root=data_root,
        )
    except (OSError, ValueError) as exc:
        raise DataRootUnavailableError("GUI data root is unavailable") from exc
    startup_notice = None
    try:
        instance_lease = acquire_runtime_instance(storage_paths.data_root)
    except OSError:
        startup_notice = (
            messagebox.showerror,
            "프로그램 실행 잠금 실패",
            "데이터 충돌 방지를 위한 실행 잠금을 확인하지 못했습니다. "
            "프로그램을 시작하지 않고 관리자에게 문의합니다.",
        )
    else:
        if instance_lease is None:
            stalled = shutdown_stall_is_live(storage_paths.data_root)
            startup_notice = (
                messagebox.showwarning,
                "프로그램이 이미 실행 중입니다",
                ("이전 프로그램의 종료 정리가 아직 끝나지 않았습니다. "
                 "잠시 기다린 뒤 다시 실행하세요. 앱이 닫히고 다시 안 켜지면 PC를 재시작하세요.")
                if stalled else
                ("같은 PC에서 이적 검사 프로그램을 두 번 실행할 수 없습니다. "
                 "열려 있는 창을 사용해 주세요."),
            )
    if startup_notice is not None:
        show_notice, title, message = startup_notice
        show_notice(title, message)
        return
    startup_complete = False
    try:
        try:
            from data_generation_guard import warm_runtime_release
            warm_runtime_release()
        except Exception:
            pass
        with writer_admission("gui_startup"):
            verify_factory_contract_startup()
            try:
                if storage_paths.custom_data_root and not storage_paths.data_root.is_dir():
                    raise DataRootUnavailableError("GUI data root is unavailable")
                from logistics_runtime_profile import resolve_logistics_profile_path
                profile_candidates = [resolve_logistics_profile_path()]
                profile_override = os.getenv(LOGISTICS_PROFILE_PATH_ENV, "").strip()
                if profile_override:
                    profile_candidates.append(resolve_owner_path(profile_override))
                profile_candidates = [path for path in profile_candidates if path.is_file()]
                protected_admin_profile = default_protected_admin_profile_path()
                # Keep the original reparse policy before binding the admitted path.
                from logistics_runtime_profile import assert_path_has_no_reparse_components
                try:
                    protected_admin_profile = assert_path_has_no_reparse_components(
                        protected_admin_profile, label="protected administrator profile",
                    )
                except (OSError, ValueError) as exc:
                    raise DataGenerationBlocked({"status": "UNKNOWN", "allowed": False}) from exc
                probe_before_owner_paths(storage_paths.data_root, file_paths=(
                    *profile_candidates, protected_admin_profile,
                ))
                prepared_admin_pin_credential = None
                if storage_paths.credential_path.is_file():
                    from direct_sync_runtime import prepare_credential_config
                    prepared_admin_pin_credential = prepare_credential_config(
                        storage_paths.credential_path, data_root=storage_paths.data_root,
                    )
                if storage_paths.custom_data_root:
                    validate_existing_data_root(storage_paths.data_root)
            except (OSError, ValueError) as exc:
                raise DataRootUnavailableError("GUI data root is unavailable") from exc
            if storage_paths.custom_data_root:
                # Keep onboarding, GUI constructors and subprocesses on this selection.
                os.environ[DATA_ROOT_ENV] = str(storage_paths.data_root)
        try:
            clear_shutdown_stall(storage_paths.data_root)
        except Exception as exc:
            # A diagnostic cannot prevent a launch that owns the instance lease.
            print(f"이전 종료 지연 표시 정리 오류: {exc.__class__.__name__}")
        if _first_run_onboarding_enabled():
            try:
                onboarding_report = onboard_current_user(
                    application_path,
                    require_bootstrap_integrity=bool(getattr(sys, "frozen", False)),
                )
            except CurrentUserOnboardingError as exc:
                _show_first_run_onboarding_error(exc)
                return ONBOARDING_EXIT_CODE
            if onboarding_report.get("bootstrap_integrity") == "absent":
                _show_bootstrap_integrity_warning(
                    resolve_current_user_onboarding_paths(
                        application_path
                    ).onboarding_report_path
                )
        record_before_owner_paths(storage_paths.data_root, file_paths=profile_candidates)
        try:
            catalog_unconfirmed = False
            catalog_context = {}
            try:
                active_catalog_path = prepare_startup_item_catalog()
            except ItemCatalogSyncError as exc:
                if not legacy_label_transition_enabled():
                    raise
                # Transition mode starts without a trusted catalog: the bundled
                # list names items and every tray records them as unconfirmed.
                try:
                    write_item_catalog_failure_diagnostic(
                        storage_paths.item_catalog_diagnostic_path,
                        exc,
                    )
                except Exception:
                    pass
                os.environ.pop(ACTIVE_PATH_ENV, None)
                catalog_context = {"transition_cause_code": exc.cause_code}
                catalog_unconfirmed = True
                active_catalog_path = None
            if active_catalog_path is not None:
                catalog_context = get_catalog_attempt_context()
                try:
                    write_item_catalog_startup_diagnostic(
                        storage_paths.item_catalog_diagnostic_path
                    )
                except Exception:
                    pass
            with writer_admission("gui_startup"):
                app = ContainerAudit()
            app._runtime_data_root = storage_paths.data_root
            app._prepared_admin_pin_credential = prepared_admin_pin_credential
            app._protected_admin_profile_path = protected_admin_profile
            if catalog_unconfirmed:
                app.item_catalog_unconfirmed = True
            app._startup_item_catalog_context = catalog_context
            if (
                catalog_unconfirmed
                or catalog_context.get("cache_used")
                or catalog_context.get("pre_send_rejection_code") == PROFILE_ABSENT
            ):
                health = getattr(app, "_direct_sync_health", None)
                if not isinstance(health, RelayHealth):
                    health = RelayHealth("blocked", 0, 0, 0, "", "", "", "relay_health_not_loaded")
                app._apply_direct_sync_health(health)
        except ItemCatalogSyncError as exc:
            try:
                write_item_catalog_failure_diagnostic(
                    storage_paths.item_catalog_diagnostic_path,
                    exc,
                )
            except Exception:  # Diagnostic persistence must not bypass fail-closed exit.
                pass
            _show_item_catalog_startup_error(exc.cause_code)
            return ITEM_CATALOG_STARTUP_EXIT_CODE
        from auto_update import control_root, read_json

        startup_control = control_root(Path(application_path))
        if startup_control is None or not read_json(startup_control / "policy.json").get("feed_url"):
            app.root.after(500, lambda: schedule_update_check(app.root))
        startup_complete = True
        return app, instance_lease
    finally:
        if not startup_complete:
            instance_lease.release()


if __name__ == "__main__":
    raise SystemExit(main())
